INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70007, 'Fisherman''s_Wharf', 'en', 'Fisherman''s Wharf may refer to:', '[{"index": "1", "level": 1, "title": "Places", "content": "Places[edit] Fisherman''s Wharf, San Francisco, a tourist destination and still-functioning wharf, in San Francisco, California Fisherman''s Wharf (Monterey, California), a historic fishing wharf in Monterey, California Tamsui Fisherman''s Wharf, a wharf located in Tamsui (Danshui) District, New Taipei, Taiwan Kaohsiung Fisherman''s Wharf, a wharf located in the city of Kaohsiung, Taiwan Fisherman''s Wharf, the former name of The Laguna Mall, a shopping mall located in Tai Wan, Hong Kong Macau Fisherman''s Wharf, a theme park located in Macau"}, {"index": "2", "level": 1, "title": "Entertainment", "content": "Entertainment[edit] Fisherman''s Wharf (Stan Rogers'' song), a Stan Rogers'' song on the Fogarty''s Cove album Fisherman''s Wharf (film), a 1939 American drama film .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} Topics referred to by the same termThis disambiguation page lists articles about distinct geographical locations with the same name. If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Fisherman''s_Wharf", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:49:47.158739+11:00', '2026-01-13 00:25:13.173081+11:00');
