INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63638, 'Elversstein', 'en', 'The Elversstein in the Harz Mountains of Germany is a granite rock formation with a maximum elevation of 499 m above sea level (NN) on the Steinberg near Hasserode in the county of Harz in Saxony-Anhalt.', '[{"index": "1", "level": 1, "title": "Name", "content": ""}, {"index": "2", "level": 1, "title": "Location", "content": ""}, {"index": "3", "level": 1, "title": "Views", "content": ""}, {"index": "4", "level": 1, "title": "Hiking", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Elversstein", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:25:50.430589+11:00', '2026-01-13 00:25:12.766999+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62388, '灵隐寺', 'en', 'Lingyin Temple is a prominent Chan Buddhist temple near Hangzhou that is renowned for its many pagodas and grottos. Its name is commonly and literally translated into English as Temple of the Soul''s Retreat.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] According to tradition, the monastery was founded in 328 AD during the Eastern Jin dynasty (266–420) by an Indian monk, named Huili in Chinese. From its inception, Lingyin was a famous monastery in the Jiangnan region.&#91;1&#93; At its peak under the Wuyue Kingdom (907–978), the temple boasted 18 pavilions, 72 halls, more than 1300 dormitory rooms, inhabited by more than 3000 monks. Many of the rich Buddhist carvings in the Feilai Feng grottos and surrounding mountains also date from this era. During the Southern Song (1127–1279), the monastery was regarded as one of the ten most important temples of the Chan sect in the Jiangnan region. However, its prominence has not saved the temple from marauders. It has been rebuilt no less than sixteen times since then. While certain existing buildings date from previous Chinese dynasties, much of the current buildings are modern restorations from the late Qing (1644–1911) period. Over the course of the Cultural Revolution, the temple and grounds suffered damage from Hangzhou''s Red Guards but the planned destruction of the temple in 1966 was successfully stopped by locals and students from Zhejiang University, who had been shocked and galvanized by the Guards'' ransacking of the patriotic general Yue Fei''s tomb.&#91;2&#93; Subsequently, the temple was offered a measure of protection by direct instructions from Premier Zhou Enlai. Today the temple is thriving as a destination for both pilgrims and tourists. It is regarded as one of the wealthiest monasteries in China, and regular pilgrims have included former paramount leader Deng Xiaoping. ^ Zi (2012), p.&#160;85. ^ He (2006)."}, {"index": "2", "level": 1, "title": "Surroundings", "content": ""}, {"index": "3", "level": 1, "title": "Feilai Feng grottos", "content": ""}, {"index": "4", "level": 1, "title": "Architecture", "content": ""}, {"index": "5", "level": 2, "title": "Tianwang Dian", "content": ""}, {"index": "6", "level": 2, "title": "Mahavira Hall", "content": ""}, {"index": "7", "level": 2, "title": "Yaoshi Dian", "content": ""}, {"index": "8", "level": 2, "title": "Jigong Dian", "content": ""}, {"index": "9", "level": 2, "title": "Fatang", "content": ""}, {"index": "10", "level": 2, "title": "Cultural Relics Exhibition Hall", "content": ""}, {"index": "11", "level": 2, "title": "Zangjing Ge", "content": ""}, {"index": "12", "level": 2, "title": "Huayan Dian", "content": ""}, {"index": "13", "level": 2, "title": "Luohan Tang", "content": ""}, {"index": "14", "level": 2, "title": "Two Sutra Pillars", "content": ""}, {"index": "15", "level": 1, "title": "Notable monks", "content": ""}, {"index": "16", "level": 1, "title": "Gallery", "content": ""}, {"index": "17", "level": 1, "title": "References", "content": ""}, {"index": "18", "level": 2, "title": "Bibliography", "content": ""}, {"index": "19", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Lingyin_Temple", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:34:23.394773+11:00', '2026-01-13 00:25:12.656968+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70016, 'Blanchard_Springs_Caverns', 'en', 'Blanchard Springs Caverns is a cave system located in the Ozark–St. Francis National Forest in Stone County in northern Arkansas, USA, 2 miles (3.2 km) off Highway 14 a short distance north of Mountain View. It is the only tourist cave owned by the United States Forest Service and the only one owned by the federal government outside the National Park System. Blanchard Springs Caverns is a three-level cave system, all of which can be viewed on guided tours.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Residents knew about the cave by the 1930s and called it Half-Mile Cave.&#91;1&#93; Systematic explorations began in the 1950s and continued sporadically in the 1960s. Explorers discovered a skeleton in the cave in 1955 which was incomplete; a cause of death could not be ascertained. The caverns were opened to the public in 1973 after 10 years of development on the Dripstone Trail. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Rossiter, Phyllis (1992). A Living History of the Ozarks. Pelican Publishing. p.&#160;307. ISBN&#160;978-0882898018."}, {"index": "2", "level": 1, "title": "Geology", "content": "Geology[edit] With 8.1 miles (13.0&#160;km) of surveyed passage, Blanchard is the second longest cave in Arkansas and the largest in volume.&#91;1&#93; The limestone rock from which the caves and their formations developed was laid down in an ancient sea more than 350 million years ago. The cave is in middle Ordovician to lower Mississippian rocks and extends through six stratigraphic formations.&#91;1&#93; The cave has shown over five levels of passage development, but the upper two levels have eroded away as deepening valleys on the surface cut into them. The cave''s formation was largely phreatic in nature (formed below the water table) and passages have elliptical cross-sections typical of these formations. During the cave''s development, active streams have been pirated from one level down to another without much vadose erosion occurring. The present stream currently rises from the cave at Blanchard Springs itself, at the same temperature as the cave, a constant, year-round 58&#160;°F (14&#160;°C). Most of the lower-level Discovery Route is in the approximately 100 feet (30&#160;m) thick Plattin limestone whereas the Dripstone tour route in the uppermost level of the cave spans three units, the Boone Chert, Cason Shale and the Fernvale Limestone.&#91;1&#93; Blanchard remains a \"living\" cave in part because of the care given by visitors and the United States Forest Service. Thus, the formations inside continue to grow as calcite is actively deposited by seeping and dripping water. One of the outstanding examples of formation growth is the Giant Flowstone, one of the largest in the U.S., at 164 feet (50&#160;m) long, 33 feet (10&#160;m) wide, and 30 feet (9.1&#160;m) thick. ^ a b c .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Goodwin, Danny (2009). \"Blanchard Springs Caverns, Arkansas\". In Palmer, Arthur; Palmer, Margaret (eds.). Caves and Karst of the USA. Huntsville, Alabama: National Speleological Society. pp.&#160;174–176. ISBN&#160;9781879961289."}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-