INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69305, 'Т-54', 'en', 'Т-54 — советский средний танк. Принят на вооружение Советской армии ВС СССР в 1946 году, серийно выпускался с 1947 года, постоянно модернизируясь. С 1958 года выпускалась его модификация под названием Т-55, приспособленная к боевым действиям в условиях применения ядерного оружия. В 1961—1967 годах он в основном был сменён в производстве и в танковых войсках СССР танком Т-62, созданным на его базе, но на ОЗТМ выпуск Т-55 продолжался вплоть до 1979 года. Также в ряде стран выпускался сам Т-54 либо его модернизированные или приспособленные к местным условиям варианты.', '[{"index": "1", "level": 1, "title": "История создания", "content": ""}, {"index": "2", "level": 1, "title": "Описание конструкции", "content": ""}, {"index": "3", "level": 2, "title": "Ходовая часть", "content": ""}, {"index": "4", "level": 2, "title": "Вооружение", "content": ""}, {"index": "5", "level": 1, "title": "Серийное производство", "content": ""}, {"index": "6", "level": 1, "title": "Модификации", "content": ""}, {"index": "7", "level": 2, "title": "Т-54-1 (объект 137)", "content": ""}, {"index": "8", "level": 2, "title": "Т-54-2 (объект 137)", "content": ""}, {"index": "9", "level": 2, "title": "Т-54-3 (объект 137)", "content": ""}, {"index": "10", "level": 2, "title": "Т-54А (Объект 137Г)", "content": ""}, {"index": "11", "level": 2, "title": "Т-54АК (Объект 137ГК)", "content": ""}, {"index": "12", "level": 2, "title": "Т-54АМ", "content": ""}, {"index": "13", "level": 2, "title": "Т-54Б (Объект 137Г2)", "content": ""}, {"index": "14", "level": 2, "title": "Т-54БК (Объект 137КЦ)", "content": ""}, {"index": "15", "level": 2, "title": "Т-54К (Объект 137К)", "content": ""}, {"index": "16", "level": 2, "title": "Т-54М (Объект 139)", "content": ""}, {"index": "17", "level": 2, "title": "Объект 141", "content": ""}, {"index": "18", 