INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63837, 'Capocorb_Vell', 'en', 'Capocorb Vell is a talayotic site located about 12 kilometres (7 mi) from Llucmajor on the island of Mallorca, in Spain. It is one of the most highly excavated talayotic sites in the Balearic islands. A similar site is Ses Païsses.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] @media all and (max-width:720px){.mw-parser-output .mod-gallery{width:100%!important}}.mw-parser-output .mod-gallery{display:table}.mw-parser-output .mod-gallery-default{background:transparent;margin-top:4px}.mw-parser-output .mod-gallery-center{margin-left:auto;margin-right:auto}.mw-parser-output .mod-gallery-left{float:left}.mw-parser-output .mod-gallery-right{float:right}.mw-parser-output .mod-gallery-none{float:none}.mw-parser-output .mod-gallery-center .gallery{justify-content:center}.mw-parser-output .mod-gallery-left .gallery{justify-content:left}.mw-parser-output .mod-gallery-right .gallery{justify-content:right}.mw-parser-output .mod-gallery-collapsible{width:100%}.mw-parser-output .mod-gallery .title,.mw-parser-output .mod-gallery .main,.mw-parser-output .mod-gallery .footer{display:table-row}.mw-parser-output .mod-gallery .title>div{display:table-cell;padding:0 4px 4px;text-align:center;font-weight:bold}.mw-parser-output .mod-gallery .main>div{display:table-cell}.mw-parser-output .mod-gallery .gallery.gallery.gallery{line-height:1.35em;display:flex;flex-wrap:wrap;column-gap:4px}.mw-parser-output .mod-gallery .footer>div{display:table-cell;padding:4px;text-align:right;font-size:85%;line-height:1em}.mw-parser-output .mod-gallery .title>div *,.mw-parser-output .mod-gallery .footer>div *{overflow:visible}.mw-parser-output .mod-gallery .gallerybox img{background:none!important}.mw-parser-output .mod-gallery .bordered-images .thumb img{outline:solid var(--background-color-neutral,#eaecf