INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70127, 'Pagsanjan_Falls', 'en', 'Pagsanjan Falls, also known as Cavinti Falls, is one of the most famous waterfalls in the Philippines. Located in the province of Laguna, the falls is one of the major tourist attractions of the region. The three-drop waterfall is reached by a river trip on dugout canoe, known locally as "Shooting the Rapids", originating from the municipality of Pagsanjan. The falls can also be reached from the top by a short hike from Cavinti.', '[{"index": "1", "level": 1, "title": "Location", "content": ""}, {"index": "2", "level": 1, "title": "National Park", "content": ""}, {"index": "3", "level": 1, "title": "Legend", "content": ""}, {"index": "4", "level": 1, "title": "Access to the falls", "content": ""}, {"index": "5", "level": 2, "title": "Pagsanjan", "content": ""}, {"index": "6", "level": 2, "title": "Cavinti", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Pagsanjan_Falls", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:52:08.158170+11:00', '2026-01-13 00:25:13.179344+11:00');
