INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70142, 'Пик_Чехова', 'en', 'Пик Че́хова — горная вершина на Сахалине, в энциклопедии Сахалина указан как одна из высочайших точек острова. Ранее называлась Судзуя дакэ.', '[{"index": "1", "level": 1, "title": "Географическое расположение", "content": ""}, {"index": "2", "level": 1, "title": "Описание", "content": ""}, {"index": "3", "level": 1, "title": "Охранный статус", "content": ""}, {"index": "4", "level": 1, "title": "Флора", "content": ""}, {"index": "5", "level": 1, "title": "Фауна", "content": ""}, {"index": "6", "level": 1, "title": "Примечания", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%9F%D0%B8%D0%BA_%D0%A7%D0%B5%D1%85%D0%BE%D0%B2%D0%B0", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:52:08.158170+11:00', '2026-01-13 00:25:13.179344+11:00');
