INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63980, 'Neptunus', 'en', 'Neptunus is a professional baseball and softball club in Rotterdam, the Netherlands. Following its 2014 championship season, the club signed a sponsorship contract for the 2015 through 2017 seasons with Curaçao and competes under the name Curaçao Neptunus. The club has a revenue of 1 million euros.', '[{"index": "1", "level": 1, "title": "Honours", "content": "Honours[edit] National[edit] Hoofdklasse: 20 (record) 1981, 1991, 1993, 1995, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2009, 2010, 2013, 2014, 2015, 2016, 2017, 2018, 2024 KNBSB Cup: 15 1992, 1995, 1997, 1999, 2000, 2001, 2002, 2003, 2005, 2009, 2010, 2011, 2013, 2014, 2017 International[edit] European Cup: 10 1994, 1996, 2000, 2001, 2002, 2003, 2004, 2015, 2017, 2018 European Super Cup: 7 1995, 1997, 1999, 2000, 2001, 2002, 2003"}, {"index": "2", "level": 2, "title": "National", "content": "National[edit] Hoofdklasse: 20 (record) 1981, 1991, 1993, 1995, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2009, 2010, 2013, 2014, 2015, 2016, 2017, 2018, 2024 KNBSB Cup: 15 1992, 1995, 1997, 1999, 2000, 2001, 2002, 2003, 2005, 2009, 2010, 2011, 2013, 2014, 2017"}, {"index": "3", "level": 2, "title": "International", "content": "International[edit] European Cup: 10 1994, 1996, 2000, 2001, 2002, 2003, 2004, 2015, 2017, 2018 European Super Cup: 7 1995, 1997, 1999, 2000, 2001, 2002, 2003"}, {"index": "4", "level": 1, "title": "European Champions Cup record", "content": "European Champions Cup record[edit] Year Venue Finish Wins Losses Win% Manager 2018 Rotterdam 1st 5 0 1.000 Ronald Jaarsma 2019 Bologna 3rd 4 1 .800 Ronald Jaarsma 2021 Ostrava 4th 2 3 .400 Ronald Jaarsma 2022 Bonn 7th 3 2 .600 Raily Legito Total 14 6 .700"}, {"index": "5", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.m