INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70233, 'ジャングルクルーズ', 'en', 'Jungle Cruise, formally named Jungle River Cruise, and currently named Jungle Cruise: Wildlife Expeditions, is a riverboat amusement ride located in the Adventureland themed section at various Disney theme parks worldwide. The attraction is a simulated riverboat cruise that travels along a waterway using a concealed guidance system through areas with Asian, African, and South American themes. Park guests board replica steam launches from a 1930s British explorers'' lodge, and Audio-Animatronic exotic animals are displayed throughout the ride. A live Disney cast member acts as a tour guide and boat skipper that loosely follows a rehearsed script, providing passengers with a comedic narrative.', '[{"index": "1", "level": 1, "title": "Inspiration and design", "content": ""}, {"index": "2", "level": 1, "title": "Disneyland", "content": ""}, {"index": "3", "level": 2, "title": "Attraction summary", "content": ""}, {"index": "4", "level": 2, "title": "Boats", "content": ""}, {"index": "5", "level": 1, "title": "Magic Kingdom", "content": ""}, {"index": "6", "level": 2, "title": "Queue", "content": ""}, {"index": "7", "level": 2, "title": "Attraction summary", "content": ""}, {"index": "8", "level": 3, "title": "Boats", "content": ""}, {"index": "9", "level": 1, "title": "Tokyo Disneyland", "content": ""}, {"index": "10", "level": 2, "title": "Boats", "content": ""}, {"index": "11", "level": 1, "title": "Hong Kong Disneyland", "content": ""}, {"index": "12", "level": 2, "title": "Attraction summary", "content": ""}, {"index": "13", "level": 3, "title": "Boats", "content": ""}, {"index": "14", "level": 1, "title": "Albert Awol", "content": ""}, {"index": "15", "level": 1, "title": "Major changes", "content": ""}, {"index": "16", "level": 1, "title": "In popular culture", "content": ""}, {"index": "17", "le