INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70234, 'おせんころがし', 'en', 'おせんころがし（漢字:お仙ころがし）は、千葉県勝浦市の西端から鴨川市にまたがる約4kmの崖の通称である。旧国道が崖の中腹を通り、古くは交通の難所であったが、現在は新国道が整備され解消されている。', '[{"index": "1", "level": 1, "title": "概要", "content": ""}, {"index": "2", "level": 1, "title": "歴史", "content": ""}, {"index": "3", "level": 1, "title": "名称の由来", "content": ""}, {"index": "4", "level": 1, "title": "脚注", "content": ""}, {"index": "5", "level": 1, "title": "関連項目", "content": ""}, {"index": "6", "level": 1, "title": "外部リンク", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ja.wikipedia.org/wiki/%E3%81%8A%E3%81%9B%E3%82%93%E3%81%93%E3%82%8D%E3%81%8C%E3%81%97", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:52:08.158170+11:00', '2026-01-13 00:25:13.185786+11:00');
