INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62392, '虎尾驛', 'en', '虎尾驛，原稱五間厝驛，是位於臺灣雲林縣虎尾鎮虎尾糖廠的糖鐵火車站，設立後促進虎尾市街的形成，今已不作運輸，原站建築列雲林縣歷史建築。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70237, 'マーメイドラグーンシアター', 'en', 'マーメイドラグーンシアター(Mermaid Lagoon Theater)は、東京ディズニーシーにあるアトラクション。', '[{"index": "1", "level": 1, "title": "概要", "content": ""}, {"index": "2", "level": 2, "title": "アンダー・ザ・シー", "content": ""}, {"index": "3", "level": 2, "title": "キング・トリトンのコンサート", "content": ""}, {"index": "4", "level": 1, "title": "脚注", "content": ""}, {"index": "5", "level": 2, "title": "注釈", "content": ""}, {"index": "6", "level": 2, "title": "出典", "content": ""}, {"index": "7", "level": 1, "title": "外部リンク", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ja.wikipedia.org/wiki/%E3%83%9E%E3%83%BC%E3%83%A1%E3%82%A4%E3%83%89%E3%83%A9%E3%82%B0%E3%83%BC%E3%83%B3%E3%82%B7%E3%82%A2%E3%82%BF%E3%83%BC", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:52:08.158170+11:00', '2026-01-13 00:25:13.185786+11:00');
