INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70303, '雷丘', 'en', 'Raichu is a Pokémon species in Nintendo and Game Freak''s Pokémon media franchise, and the evolved form of series mascot Pikachu. First introduced in the 1996 video games Pokémon Red and Blue, it was created by Atsuko Nishida at the request of lead designer Ken Sugimori, with the design finalized by Sugimori. Since Raichu''s debut, it has appeared in multiple games including Pokémon Go and the Pokémon Trading Card Game, as well as various merchandise. In media related to the franchise, Raichu has been voiced by various voice actors, including Urara Takano, Kei Shindō, Fumiko Takekuma, and Casey Mongillo.', '[{"index": "1", "level": 1, "title": "Conception and development", "content": ""}, {"index": "2", "level": 2, "title": "Design", "content": ""}, {"index": "3", "level": 1, "title": "Appearances", "content": ""}, {"index": "4", "level": 1, "title": "Critical reception", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Raichu", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:55:36.420012+11:00', '2026-01-13 00:25:13.185786+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70313, 'Núi_Sam', 'en', 'Núi Sam có tên khác Vĩnh Tế Sơn hay Ngọc Lãnh Sơn cao 284 m có chu vi 5.200m, trước thuộc xã Vĩnh Tế, nay thuộc phường Núi Sam, thành phố Châu Đốc, tỉnh An Giang, Việt Nam.', '[{"index": "1", "level": 1, "title": "Tên gọi, vị trí", "content": ""}, {"index": "2", "level": 1, "title": "Thắng cảnh, di tích", "content": ""}, {"index": "3", "level": 1, "title": "Lợi ích khác", "content": ""}, {"index": "4", "level": 1, "title": "Thông tin liên quan", "content": ""}, {"index": "5", "level": 2, "title": "Giới thiệu bia Vĩnh Tế Sơn", "content": ""}, {"index": "6", "level": 2, "title": "Trích văn bia", "content": ""}, {"index": "7", "level": 1, "title": "Chú thích", "content": ""}, {"index": "8", "level": 1, "title": "Liên kết ngoài", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://vi.wikipedia.org/wiki/N%C3%BAi_Sam", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:55:36.420012+11:00', '2026-01-13 00:25:13.185786+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70322, 'Ocean_Adventure', 'en', 'Ocean Adventure is an open-space marine zoological park in the Morong, Bataan portion of the Subic Special Economic and Freeport Zone in the Philippines.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Ocean Adventure opened to the public in October 2001 with its initial facilities built at a cost of $7.5 million.&#91;1&#93; The marine facility was built at Camayan Point which formerly hosted a ammunition pier.&#91;2&#93; In its first year of operations, false killer whale viewing and sea lion shows were among the marine park''s attractions. In June 2002, the Subic Bay Marine Exploratorium (SBME), the parent company of Ocean Adventure, secured a 75-year lease with the Subic Bay Metropolitan Authority (SBMA) over Ilanin Bay''s shoreline and waters, including Miracle Beach which increased the area of the Ocean Adventure marine park from 13 acres (5.3&#160;ha) to 27 acres (11&#160;ha).&#91;1&#93; A dispute has been ongoing between the SBME and the SBMA since the early 2010s.&#91;3&#93; The latter terminated its lease contract with the former alleging that SBME violated terms of its lease agreement; violations cited are illegal subleasing of property, constructing without permits, improper waste storage, and closure of public roads.&#91;4&#93; It began when the SBME developed \"The Hill\", a residential area populated with expatriates.&#91;3&#93; In 2017, the marine park was named Best Theme Park in the inaugural edition of the United Stars Events and Exhibitions Corp.-organized Philippine Tourism Industry Awards in 2017.&#91;5&#93; The SBMA seized undeveloped portions of land owned by SBME, including land meant for future development of Ocean Adventure in October 2019.&#91;6&#93; The SBMA sought to repossess Ocean Adventure in 2019, citing multiple contractual violations and failure to complete developmental commitments and asked the SBME to reduce activities within two years.&#91;4&#93; Operations seized for seven months in 2020, due to the COVID-19 pandemic. Ocean Adventure resumed operations in October 2020.&#91;7&#93; ^ a b .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Adventure like no other at Subic Bay''s unique marine park\". The Philippine Star. November 9, 2002. Retrieved October 30, 2020. ^ Empeño, Henry (November 29, 2019). \"SBMA: No forest destroyed for Subic SEA Games | Henry Empeño\". BusinessMirror. Retrieved October 30, 2020. ^ a b Datu, Mahatma (October 24, 2019). \"Ocean Adventure files raps vs. SBMA\". Philippine News Agency. Retrieved October 30, 2020. ^ a b Roxas, Patrick (September 28, 2019). \"SBMA to close down Ocean Adventure Park\". The Manila Times. Retrieved October 30, 2020. ^ Empeño, Henry (November 9, 2017). \"Subic''s Ocean Adventure named Philippines''s best theme park this yea\". BusinessMirror. ^ \"SBMA takes over undeveloped property of Ocean Adventure\". Rappler. October 28, 2019. Retrieved October 30, 2020. ^ \"Animal shows back at Subic marine theme park\". Philippine Daily Inquirer. October 9, 2020. Retrieved October 30, 2020."}, {"index": "2", "level": 1, "title": "Facilities and attractions", "content": "Facilities and attractions[edit] Dolphin show at Ocean Adventure. Ocean Adventure is managed by Subic Bay Marine Exploratorium, Inc which is a locator in the Subic Special Economic and Freeport Zone and also runs the Camayan Beach Resort and the Adventure Beach Waterpark.&#91;1&#93; The marine park itself is located within the West Ilanin Forest Area which is in the town of Morong, Bataan portion of the Subic economic zone.&#91;2&#93; The marine park has three primary attractions namely the Sea Lion Show, Whale Presentation and the Discovery Aquarium.&#91;3&#93; ^ Cite error: The named reference filesraps was invoked but never defined (see the help page). ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Getting there\". Ocean Adventure, Subic Bay. Retrieved October 30, 2020. ^ Cite error: The named reference businessmirror was invoked but never defined (see the help page)."}, {"index": "3", "level": 1, "title": "Visitors", "content": "Visitors[edit] According to data from the Subic Bay Metropolitan Authority in 2012, the marine park receives 500,000 visitors annually making Ocean Adventure among the top tourist destinations in the Central Luzon region.&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Marine park owner hits back at activists\". Philippine Daily Inquirer. 15 October 2012. Retrieved October 30, 2020."}, {"index": "4", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Ocean_Adventure", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:55:36.420012+11:00', '2026-01-13 00:25:13.185786+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70329, 'Space_Shuttle', 'en', 'The Space Shuttle is a retired, partially reusable low Earth orbital spacecraft system operated from 1981 to 2011 by the U.S. National Aeronautics and Space Administration (NASA) as part of the Space Shuttle program. Its official program name was the Space Transportation System (STS), taken from the 1969 plan led by U.S. vice president Spiro Agnew for a system of reusable spacecraft where it was the only item funded for development.', '[{"index": "1", "level": 1, "title": "Design and development", "content": ""}, {"index": "2", "level": 2, "title": "Historical background", "content": "Historical background[edit] In the late 1930s, the German government launched the \"Amerikabomber\" (English: America bomber) project, and Eugen Sänger''s idea, together with mathematician Irene Bredt, was a winged rocket called the Silbervogel (German for \"silver bird\").&#91;1&#93; During the 1950s, the United States Air Force proposed using a reusable piloted glider to perform military operations such as reconnaissance, satellite attack, and air-to-ground weapons employment. In the late 1950s, the Air Force began developing the partially reusable X-20 Dyna-Soar. The Air Force collaborated with NASA on the Dyna-Soar and began training six pilots in June 1961. The rising costs of development and the prioritization of Project Gemini led to the cancellation of the Dyna-Soar program in December 1963. In addition to the Dyna-Soar, the Air Force had conducted a study in 1957 to test the feasibility of reusable boosters. This became the basis for the aerospaceplane, a fully reusable spacecraft that was never developed beyond the initial design phase in 1962–1963.&#91;2&#93;&#58;&#8202;162–163&#8202; Beginning in the early 1950s, NASA and the Air Force collaborated on developing lifting bodies to test aircraft that primarily generated lift from their fuselages instead of wings, and tested the NASA M2-F1, Northrop M2-F2, Northrop M2-F3, Northrop HL-10, Martin Marietta X-24A, and the Martin Marietta X-24B. The program tested aerodynamic characteristics that would later be incorporated in design of the Space Shuttle, including unpowered landing from a high altitude and speed.&#91;3&#93;&#58;&#8202;142&#8202;&#91;4&#93;&#58;&#8202;16–18&#8202; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Wall, Mike (June 28, 2011). \"How the Space Shuttle Was Born\". Space.com. Archived from the original on March 30, 2023. Retrieved March 30, 2023. ^ Williamson, Ray (1999). \"Developing the Space Shuttle\" (PDF). Exploring the Unknown: Selected Documents in the History of the U.S. Civil Space Program, Volume IV: Accessing Space. Washington, D.C.: NASA. Archived (PDF) from the original on May 31, 2020. Retrieved April 23, 2019. ^ Reed, R. Dale (January 1, 1997). Wingless Flight: The Lifting Body Story (PDF). NASA. ISBN&#160;9780160493904. Archived (PDF) from the original on December 18, 2014. Retrieved April 25, 2019. ^ Baker, David (April 2011). NASA Space Shuttle: Owners'' Workshop Manual. Somerset, UK: Haynes Manual. ISBN&#160;978-1-84425-866-6."}, {"index": "3", "level": 2, "title": "Design process", "content": ""}, {"index": "4", "level": 2, "title": "Development", "content": ""}, {"index": "5", "level": 2, "title": "Testing", "content": ""}, {"index": "6", "level": 1, "title": "Description", "content": "Description[edit] The Space Shuttle was the first operational orbital spacecraft designed for reuse. Each Space Shuttle orbiter was designed for a projected lifespan of 100 launches or ten years of operational life, although this was later extended.&#91;1&#93;&#58;&#8202;11&#8202; At launch, it consisted of the orbiter, which contained the crew and payload, the external tank (ET), and the two solid rocket boosters (SRBs).&#91;2&#93;&#58;&#8202;363&#8202; Responsibility for the Space Shuttle components was spread among multiple NASA field centers. The KSC was responsible for launch, landing, and turnaround operations for equatorial orbits (the only orbit profile actually used in the program). The U.S. Air Force at the Vandenberg Air Force Base was responsible for launch, landing, and turnaround operations for polar orbits (though this was never used). The Johnson Space Center (JSC) served as the central point for all Shuttle operations and the MSFC was responsible for the main engines, external tank, and solid rocket boosters. The John C. Stennis Space Center handled main engine testing, and the Goddard Space Flight Center managed the global tracking network.&#91;3&#93; Orbiter[edit] .mw-parser-output .hatnote{font-style:italic}.mw-parser-output div.hatnote{padding-left:1.6em;margin-bottom:0.5em}.mw-parser-output .hatnote i{font-style:normal}.mw-parser-output .hatnote+link+.hatnote{margin-top:-0.5em}@media print{body.ns-0 .mw-parser-output .hatnote{display:none!important}}Main article: Space Shuttle orbiter Shuttle launch profiles. From left: Columbia, Challenger, Discovery, Atlantis, and Endeavour The orbiter had design elements and capabilities of both a rocket and an aircraft to allow it to launch vertically and then land as a glider.&#91;2&#93;&#58;&#8202;365&#8202; Its three-part fuselage provided support for the crew compartment, cargo bay, flight surfaces, and engines. The rear of the orbiter contained the Space Shuttle Main Engines (SSME), which provided thrust during launch, as well as the Orbital Maneuvering System (OMS), which allowed the orbiter to achieve, alter, and exit its orbit once in space. Its double-delta wings were 18&#160;m (60&#160;ft) long, and were swept 81° at the inner leading edge and 45° at the outer leading edge. Each wing had an inboard and outboard elevon to provide flight control during reentry, along with a flap located between the wings, below the engines to control pitch. The orbiter''s vertical stabilizer was swept backwards at 45° and contained a rudder that could split to act as a speed brake.&#91;2&#93;&#58;&#8202;382–389&#8202; The vertical stabilizer also contained a two-part drag parachute system to slow the orbiter after landing. The orbiter used retractable landing gear with a nose landing gear and two main landing gear, each containing two tires. The main landing gear contained two brake assemblies each, and the nose landing gear contained an electro-hydraulic steering mechanism.&#91;2&#93;&#58;&#8202;408–411&#8202; Crew[edit] The Space Shuttle crew varied per mission. They underwent rigorous testing and training to meet the qualification requirements for their roles. The crew was divided into three categories: Pilots, Mission Specialists, and Payload Specialists. Pilots were further divided into two roles: the Space Shuttle Commander, who would seat in the forward left seat and the Space Shuttle Pilot who would seat in the forward right seat.&#91;4&#93; The test flights, STS-1 through STS-4 only had two members each, the commander and pilot. The commander and the pilot were both qualified to fly and land the orbiter. The on-orbit operations, such as experiments, payload deployment, and EVAs, were conducted primarily by the mission specialists who were specifically trained for their intended missions and systems. Early in the Space Shuttle program, NASA flew with payload specialists, who were typically systems specialists who worked for the company paying for the payload''s deployment or operations. The final payload specialist, Gregory B. Jarvis, flew on STS-51-L, and future non-pilots were designated as mission specialists. An astronaut flew as a crewed spaceflight engineer on both STS-51-C and STS-51-J to serve as a military representative for a National Reconnaissance Office payload. A Space Shuttle crew typically had seven astronauts, with STS-61-A flying with eight.&#91;5&#93;&#58;&#8202;III-21&#8202; Crew compartment[edit] The crew compartment comprised three decks and was the pressurized, habitable area on all Space Shuttle missions. The flight deck consisted of two seats for the commander and pilot, as well as an additional two to four seats for crew members. The mid-deck was located below the flight deck and was where the galley and crew bunks were set up, as well as three or four crew member seats. The mid-deck contained the airlock, which could support two astronauts on an extravehicular activity (EVA), as well as access to pressurized research modules"}, {"index": "7", "level": 2, "title": "Orbiter", "content": ""}, {"index": "8", "level": 3, "title": "Crew", "content": ""}, {"index": "9", "level": 3, "title": "Crew compartment", "content": ""}, {"index": "10", "level": 3, "title": "Airlock", "content": ""}, {"index": "11", "level": 3, "title": "Flight systems", "content": ""}, {"index": "12", "level": 3, "title": "Payload bay", "content": ""}, {"index": "13", "level": 3, "title": "Remote Manipulator System", "content": ""}, {"index": "14", "level": 3, "title": "Spacelab", "content": ""}, {"index": "15", "level": 3, "title": "RS-25 engines", "content": ""}, {"index": "16", "level": 3, "title": "Orbital Maneuvering System", "content": ""}, {"index": "17", "level": 3, "title": "Thermal protection system", "content": ""}, {"index": "18", "level": 2, "title": "External tank", "content": ""}, {"index": "19", "level": 2, "title": "Solid Rocket Boosters", "content": ""}, {"index": "20", "level": 2, "title": "Support vehicles", "content": ""}, {"index": "21", "level": 1, "title": "Mission profile", "content": ""}, {"index": "22", "level": 2, "title": "Launch preparation", "content": ""}, {"index": "23", "level": 2, "title": "Launch", "content": ""}, {"index": "24", "level": 2, "title": "In orbit", "content": ""}, {"index": "25", "level": 2, "title": "Re-entry and landing", "content": ""}, {"index": "26", "level": 3, "title": "Landing sites", "content": ""}, {"index": "27", "level": 2, "title": "Post-landing processing", "content": ""}, {"index": "28", "level": 1, "title": "Space Shuttle program", "content": ""}, {"index": "29", "level": 2, "title": "Budget", "content": ""}, {"index": "30", "level": 2, "title": "Disasters", "content": ""}, {"index": "31", "level": 2, "title": "Criticism", "content": ""}, {"index": "32", "level": 2, "title": "Retirement", "content": ""}, {"index": "33", "level": 1, "title": "See also", "content": ""}, {"index": "34", "level": 1, "title": "Notes", "content": ""}, {"index": "35", "level": 1, "title": "References", "content": ""}, {"index": "36", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Space_Shuttle", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:55:36.420012+11:00', '2026-01-13 00:25:13.185786+11:00');
