INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70460, 'มูลนิธิธรรมกาย', 'en', 'มูลนิธิธรรมกาย ก่อตั้งขึ้นในปี พ.ศ. 2513 ตั้งอยู่ที่เลขที่ 40 หมู่ที่ 8 ตำบลคลองสอง อำเภอคลองหลวง จังหวัดปทุมธานี เป็นองค์การไม่แสวงหาผลกำไร (NPO) และองค์การนอกภาครัฐ (NGO) ที่เป็นสมาชิกองค์การสหประชาชาติ มีหน้าที่ในการส่งเสริมกิจกรรมต่าง ๆ ด้านสันติภาพ การศึกษา วัฒนธรรม สังคมสงเคราะห์ การปฏิบัติธรรม ควบคู่กับวัดพระธรรมกายมาตลอด', '[{"index": "1", "level": 1, "title": "ประวัติ", "content": ""}, {"index": "2", "level": 1, "title": "วัตถุประสงค์", "content": ""}, {"index": "3", "level": 1, "title": "กรรมการมูลนิธิ", "content": ""}, {"index": "4", "level": 1, "title": "การทำงาน", "content": ""}, {"index": "5", "level": 2, "title": "ด้านการคณะสงฆ์", "content": ""}, {"index": "6", "level": 2, "title": "ด้านสาธารณสงเคราะห์", "content": ""}, {"index": "7", "level": 1, "title": "เกียรติคุณ", "content": ""}, {"index": "8", "level": 1, "title": "อ้างอิง", "content": ""}, {"index": "9", "level": 1, "title": "ดูเพิ่ม", "content": ""}, {"index": "10", "level": 1, "title": "แหล่งข้อมูลอื่น", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://th.wikipedia.org/wiki/%E0%B8%A1%E0%B8%B9%E0%B8%A5%E0%B8%99%E0%B8%B4%E0%B8%98%E0%B8%B4%E0%B8%98%E0%B8%A3%E0%B8%A3%E0%B8%A1%E0%B8%81%E0%B8%B2%E0%B8%A2", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:58:03.431850+11:00', '2026-01-13 00:25:13.192089+11:00');
