INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70569, 'วัดราชพลี', 'en', 'วัดราชพลี เป็นวัดโบราณประเภทวัดร้างที่ตั้งอยู่ทางตะวันตกนอกเกาะเมืองอยุธยา อยู่ทางใต้ของวัดกษัตราธิราชวรวิหาร อาจจะสร้างในสมัยอยุธยาตอนต้นแต่ไม่มีการระบุว่าใครเป็นผู้สร้าง ซึ่งวัดราชพลีได้ปรากฏชื่อเป็นครั้งแรกในพระราชพงศาวดาร ฉบับพันจันทนุมาศ (เจิม) สรุปใจความได้ว่า ในช่วงเดือน 5 แรม 14 ค่ำ ระหว่างสงครามพระเจ้าอลองพญา กองทัพพม่าได้ใช้วัดราชพลีและวัดกษัตราธิราชเป็นค่ายและเป็นที่ตั้งปืนใหญ่ยิงถล่มเข้าไปในพระนคร ในครั้งนั้นพระเจ้าอยู่หัวซึ่งหมายถึงสมเด็จพระเจ้าอุทุมพร ได้ทรงช้างต้นชื่อ พลายแสนพลพ่าย เสด็จมาบัญชาการรบด้วยพระองค์เองที่วัดสวนหลวงสบสวรรค์ ซึ่งคาดว่าทางฝ่ายอยุธยาได้วางกำลังไว้อย่างหนาแน่นตรงบริเวณนี้', '[{"index": "1", "level": 1, "title": "อ้างอิง", "content": "อ้างอิง[แก้] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://th.wikipedia.org/wiki/%E0%B8%A7%E0%B8%B1%E0%B8%94%E0%B8%A3%E0%B8%B2%E0%B8%8A%E0%B8%9E%E0%B8%A5%E0%B8%B5", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:58:03.431850+11:00', '2026-01-13 00:25:13.192089+11:00');
