INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70626, 'チャチャワールドいしこし', 'en', 'チャチャワールドいしこしは、宮城県登米市にある遊園地である。旧石越町が町おこしのために整備したもので、1995年（平成7年）4月29日に開園した。', '[{"index": "1", "level": 1, "title": "沿革", "content": ""}, {"index": "2", "level": 2, "title": "開園まで", "content": ""}, {"index": "3", "level": 2, "title": "開園以後", "content": ""}, {"index": "4", "level": 1, "title": "施設", "content": ""}, {"index": "5", "level": 2, "title": "幻の2期計画", "content": ""}, {"index": "6", "level": 1, "title": "名前の由来", "content": ""}, {"index": "7", "level": 1, "title": "料金・営業時間", "content": ""}, {"index": "8", "level": 1, "title": "関連項目", "content": ""}, {"index": "9", "level": 1, "title": "脚注", "content": ""}, {"index": "10", "level": 2, "title": "註", "content": ""}, {"index": "11", "level": 2, "title": "公式サイト", "content": ""}, {"index": "12", "level": 2, "title": "二次資料", "content": ""}, {"index": "13", "level": 1, "title": "外部リンク", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ja.wikipedia.org/wiki/%E3%83%81%E3%83%A3%E3%83%81%E3%83%A3%E3%83%AF%E3%83%BC%E3%83%AB%E3%83%89%E3%81%84%E3%81%97%E3%81%93%E3%81%97", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:01:52.312000+11:00', '2026-01-13 00:25:13.198512+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70647, 'Little_India,_Malacca', 'en', 'Little India Malacca is a Little India in Malacca City, Malacca, Malaysia.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Littleton Pipe Wolferstan was the British Governor of Malacca in the 1910s. A road in Malacca was named after him. Its name is Ulberston Road. Its current name has been changed to Jalan Bendahara. It is on this road that Malacca Little India is located. St. Peter''s Church[edit] St. Peter''s Church is located at the intersection of Malacca Little India Road and Park Raya Road. The oldest in Malaysia. The Dutch demolished the temple already built by the Portuguese. Later renovation was done in 1710. During the Japanese (Kempeitai) period, the temple was called Karunkugai."}, {"index": "2", "level": 2, "title": "St. Peter''s Church", "content": ""}, {"index": "3", "level": 1, "title": "Architecture", "content": ""}, {"index": "4", "level": 1, "title": "Business", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Little_India%2C_Malacca", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:01:52.312000+11:00', '2026-01-13 00:25:13.198512+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64482, 'Henriette', 'en', 'Henriette may refer to:', '[{"index": "1", "level": 1, "title": "People", "content": "People[edit] Nobles[edit] Ordered chronologically Henriette, Countess of Montbéliard (1387–1444), Sovereign Countess of Montbéliard Henriette of Cleves (1542–1601), Duchess of Nevers, Countess of Rethel and Princess of Mantua Henriette Marie of the Palatinate (1626–1651), daughter of Elizabeth Stuart, Queen of Bohemia Princess Henriette Adelaide of Savoy (1636–1676), Electress of Bavaria Henriette Louise de Bourbon (1703–1772), French princess and abbess Henriette of France (1727–1752), French princess, daughter of King Louis XV Other[edit] Ordered alphabetically Henriette Chandet (1901-1989), French feminist, columnist, and historian Henriette Willemina Crommelin (1870-1957), Dutch labor leader and temperance reformer Henriette Delamarre de Monchaux (1854–1911), French naturalist, geologist and paleontologist Henriette Dibon (1902–1989), French poet and short story writer Henriette Hansen (disambiguation) Henriette Homann (1819–1892), Norwegian photographer and painter Henriette Tabita Hutabarat Lebang (born 1952), Indonesian religious leader and former the General Chairperson of the Communion of Churches in Indonesia Henriette Löfman (1784–1836), Swedish composer Henriette Mankiewicz (1852-1906), art embroiderer Henriette Nissen-Saloman (1819–1879), Swedish opera singer Henriette Petit (1894–1983), Chilean painter Henriette Pressburg (1788–1863), mother of Karl Marx Henriette Reker (born 1956), German politician and first woman to be mayor of Cologne Henriette Sauret (1890–1976), French feminist, author, pacifist, journalist Henriette Strobel (born 1953), Dutch singer and model Henriette Yvonne Stahl (1900–1984), Romanian novelist, short story writer and translator Henriette Widerberg (1796–1872), Swedish opera singer Henriette Wienecke Stadfeldt (1819–1907), Norwegian-Danish composer Henriette Wulfsberg (1843–1906), Norwegian school owner and writer"}, {"index": "2", "level": 2, "title": "Nobles", "content": "Nobles[edit] Ordered chronologically Henriette, Countess of Montbéliard (1387–1444), Sovereign Countess of Montbéliard Henriette of Cleves (1542–1601), Duchess of Nevers, Countess of Rethel and Princess of Mantua Henriette Marie of the Palatinate (1626–1651), daughter of Elizabeth Stuart, Queen of Bohemia Princess Henriette Adelaide of Savoy (1636–1676), Electress of Bavaria Henriette Louise de Bourbon (1703–1772), French princess and abbess Henriette of France (1727–1752), French princess, daughter of King Louis XV"}, {"index": "3", "level": 2, "title": "Other", "content": "Other[edit] Ordered alphabetically Henriette Chandet (1901-1989), French feminist, columnist, and historian Henriette Willemina Crommelin (1870-1957), Dutch labor leader and temperance reformer Henriette Delamarre de Monchaux (1854–1911), French naturalist, geologist and paleontologist Henriette Dibon (1902–1989), French poet and short story writer Henriette Hansen (disambiguation) Henriette Homann (1819–1892), Norwegian photographer and painter Henriette Tabita Hutabarat Lebang (born 1952), Indonesian religious leader and former the General Chairperson of the Communion of Churches in Indonesia Henriette Löfman (1784–1836), Swedish composer Henriette Mankiewicz (1852-1906), art embroiderer Henriette Nissen-Saloman (1819–1879), Swedish opera singer Henriette Petit (1894–1983), Chilean painter Henriette Pressburg (1788–1863), mother of Karl Marx Henriette Reker (born 1956), German politician and first woman to be mayor of Cologne Henriette Sauret (1890–1976), French feminist, author, pacifist, journalist Henriette Strobel (born 1953), Dutch singer and model Henriette Yvonne Stahl (1900–1984), Romanian novelist, short story writer and translator Henriette Widerberg (1796–1872), Swedish opera singer Henriette Wienecke Stadfeldt (1819–1907), Norwegian-Danish composer Henriette Wulfsberg (1843–1906), Norwegian school owner and writer"}, {"index": "4", "level": 1, "title": "Other uses", "content": "Other uses[edit] Henriette, Minnesota Hurricane Henriette (disambiguation) La fête à Henriette, a 1952 French film often known simply as Henriette"}, {"index": "5", "level": 1, "title": "See also", "content": "See also[edit] All pages with titles beginning with Henriette Henrietta (disambiguation) Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Henriette.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Henriette", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:54:51.624106+11:00', '2026-01-13 00:25:12.816605+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64488, 'Ми-4', 'en', 'The Mil Mi-4 is a Soviet transport helicopter that served in both military and civilian roles.', '[{"index": "1", "level": 1, "title": "Design and development", "content": ""}, {"index": "2", "level": 1, "title": "Operational history", "content": "Operational history[edit] The Mi-4 transport helicopter laid the groundwork of Soviet Army Aviation. It was widely used both in the armed forces and in Soviet civil aviation, and for several decades remained the main type of helicopter in the inventory of the Soviet Armed Forces and of the Civil Air Fleet. The Mi-4 went out of service with the development of the Mi-8. It is no longer used by the Russian Air Force, though it remained in service in some countries as a utility helicopter or as a military transport a while longer. Albania was thought to be the final country using the helicopter, and by 2005 all were out of service. The Mi-4 played a very important role in the Bangladesh liberation war of 1971. The Mi-4 was the workhorse of the Indian Air Force&#91;1&#93; covering the medium lift role at the time. A highly successful heli-borne operation, the Meghna Heli Bridge, using Mi-4s helped the Indian Army''s 57 Mountain Division clear the Meghna River. The helilift of a battalion of Indian troops to the outskirts of Sylhet was the first heli-borne operation of the Indian army. Much like the UH-1 Huey, after it was gradually phased out of military service, it was used in various domestic roles: search and rescue, firefighting, polar expeditioning, construction site cargo helicopter, commercial flights and many others.&#91;2&#93; An official video of a North Korean Air Force combat flying skills competition released in 2014 shows that the Mi-4 is still in limited service in North Korea.&#91;3&#93;&#91;4&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Indian Air Force Gallery&#160;:: Mil Mi-4 - Bharat Rakshak\". Bharat Rakshak. Retrieved 2017-11-05. ^ John Pike. \"Mi-4 HOUND (MIL)\". Globalsecurity.org. Retrieved 2012-10-28. ^ Cite error: The named reference :1 was invoked but never defined (see the help page). ^ Archived at Ghostarchive and the Wayback Machine: \"朝鲜空军飞行技术大赛 North Korea Air Force combat flying skills contest\". YouTube. 15 May 2014."}, {"index": "3", "level": 1, "title": "Variants", "content": ""}, {"index": "4", "level": 1, "title": "Operators", "content": ""}, {"index": "5", "level": 1, "title": "Specifications (Mi-4A)", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "Notes", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Mil_Mi-4", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:55:05.058665+11:00', '2026-01-13 00:25:12.816605+11:00');
