INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70719, 'タワー・オブ・テラー', 'en', 'Tower of Terror may refer to:', '[{"index": "1", "level": 1, "title": "Amusement rides", "content": "Amusement rides[edit] Tower of Terror (Gold Reef City), a vertical drop roller coaster in Johannesburg, South Africa Tower of Terror II, a shuttle roller coaster in Queensland, Australia The Twilight Zone Tower of Terror, an accelerated drop tower attraction at Disney theme parks"}, {"index": "2", "level": 1, "title": "Film and television", "content": "Film and television[edit] Tower of Terror (1913 film), an Italian silent film Tower of Terror (1941 film), a British spy thriller Tower of Terror (1971 film), a British thriller Tower of Terror (1990 film), an American action comedy Tower of Terror (1997 film), an American mystery film loosely based on the Disney theme park amusement ride \"Tower of Terror\" (Pokémon episode) Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Tower of Terror.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Tower_of_Terror", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:01:52.312000+11:00', '2026-01-13 00:25:13.198512+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70783, 'Cape_Agulhas', 'en', 'Cape Agulhas is a rocky headland in Western Cape, South Africa. It is the geographic southern tip of Africa and the beginning of the traditional dividing line between the Atlantic and Indian oceans according to the International Hydrographic Organization. It is approximately half a degree of latitude, or 55 kilometres (34 mi), farther south than the Cape of Good Hope.', '[{"index": "1", "level": 1, "title": "Geography", "content": ""}, {"index": "2", "level": 1, "title": "Climate", "content": ""}, {"index": "3", "level": 1, "title": "Shipping hazards", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Cape_Agulhas", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:03:36.688008+11:00', '2026-01-13 00:25:13.198512+11:00');
