INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64635, 'Mieszko_I', 'en', 'Mieszko I was Duke of Poland from 960 until his death in 992 and the founder of the first unified Polish state, the Civitas Schinesghe. A member of the Piast dynasty, he was the first Christian ruler of Poland and continued the policies of both his father Siemomysł and his grandfather Lestek, who initiated a process of unification among the Polish tribes and the creation of statehood.', '[{"index": "1", "level": 1, "title": "Early life", "content": ""}, {"index": "2", "level": 1, "title": "Reign", "content": ""}, {"index": "3", "level": 2, "title": "Early reign", "content": ""}, {"index": "4", "level": 2, "title": "Margrave Gero''s war; Mieszko''s homage to the Emperor", "content": ""}, {"index": "5", "level": 2, "title": "Marriage and conversion to Christianity", "content": ""}, {"index": "6", "level": 2, "title": "Conquest of Pomerania", "content": ""}, {"index": "7", "level": 2, "title": "War against Margrave Odo I of Ostmark", "content": ""}, {"index": "8", "level": 2, "title": "Acquisitions in the east", "content": ""}, {"index": "9", "level": 2, "title": "Involvement in German internal disputes; Second marriage", "content": ""}, {"index": "10", "level": 2, "title": "Cooperation with Sweden and the war against Denmark", "content": ""}, {"index": "11", "level": 2, "title": "Participation in German civil war", "content": ""}, {"index": "12", "level": 2, "title": "War against Bohemia; incorporation of Silesia and Lesser Poland", "content": ""}, {"index": "13", "level": 2, "title": "Dagome iudex", "content": ""}, {"index": "14", "level": 2, "title": "Late reign, death and succession", "content": ""}, {"index": "15", "level": 1, "title": "Legacy", "content": ""}, {"index": "16", "level": 1, "title": "Marriages and issue", "content": ""}, {"index": "17", "level": 1, "title": "Notes", "content": ""}, {"index": "18", "level": 1, "title": "Bibliography", "content": ""}, {"index": "19", "level": 1, "title": "See also", "content": ""}, {"index": "20", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Mieszko_I", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:59:50.111599+11:00', '2026-01-13 00:25:12.829328+11:00');
