INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70801, 'Laguna_Verde', 'en', 'Laguna Verde, the Spanish-language form of green lagoon or green lake, may refer to:', '[{"index": "1", "level": 1, "title": "Bolivia", "content": "Bolivia[edit] Laguna Verde (Bolivia), a salt lake in Potosi Department Laguna Verde (Beni), a lake in Beni Department Laguna Verde (Comarapa), a lake in Comarapa"}, {"index": "2", "level": 1, "title": "Chile", "content": "Chile[edit] Laguna Verde, Chile, a town Laguna Verde (lake of Chile), in the Andes Laguna Verde (volcano), in the Salar de Atacama"}, {"index": "3", "level": 1, "title": "Other places", "content": "Other places[edit] Laguna Verde (Hong Kong), a residential complex in Kowloon, Hong Kong, China Laguna Verde Nuclear Power Station, in Alto Lucero, Veracruz, Mexico"}, {"index": "4", "level": 1, "title": "See also", "content": "See also[edit] Green Lake (disambiguation) Lago Verde (disambiguation) Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Laguna Verde.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Laguna_Verde", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:03:36.688008+11:00', '2026-01-13 00:25:13.198512+11:00');
