INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70833, 'Huguenot_Monument', 'en', 'The Huguenot Monument in Franschhoek, Western Cape, South Africa, is dedicated to the cultural influences that Huguenots have brought to the Cape Colony after their immigration during the 17th and 18th centuries. These French and Belgian Protestants were fleeing violent religious persecution, especially in Roman Catholic France.', '[{"index": "1", "level": 1, "title": "Other Huguenot monuments and memorials in South Africa", "content": "Other Huguenot monuments and memorials in South Africa[edit] the Huguenot Monument in the Johannesburg Botanical Garden was erected in 1988, to commemorate the 300th anniversary of the arrival of the Huguenots in South Africa. In the Johannesburg Botanical Garden stands a memorial commemorating the 300th anniversary of the arrival of the Huguenots in South Africa. Joubert Square of Wellington, Western Cape, has a Huguenot Fountain. On Queen Victoria Street, Cape Town, stands the Huguenot Memorial Building, erected by the Huguenot Memorial Society. The remains of President Kruger lay in state here before being taken to the Netherlands for burial."}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] Huguenots in South Africa"}, {"index": "3", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Huguenot Monument, Franschhoek. Wikimedia Commons has media related to Saasveld House..mw-parser-output .preview-warning{font-style:italic;padding-left:1.6em;margin-bottom:0.5em;color:var(--color-error,red)}.mw-parser-output .preview-warning+link+.preview-warning{margin-top:-0.5em}Preview warning: Commons category does not match the Commons sitelink on Wikidata – please check The Huguenot Memorial Museum website The Huguenot Heritage The Huguenot Society of South Africa"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Huguenot_Monument", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:04:47.302622+11:00', '2026-01-13 00:25:13.204746+11:00');
