INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70950, 'Bomas_of_Kenya', 'en', 'Bomas of Kenya is a tourist village in Langata, Nairobi, in Kenya. Bomas interpreted to mean (homesteads) displays traditional villages belonging to the several Kenyan tribes. Bomas of Kenya is home to one of the largest auditoriums in Africa. It is located approximately 10km from Nairobi''s central business district.', '[{"index": "1", "level": 1, "title": "Origin", "content": ""}, {"index": "2", "level": 1, "title": "Cultural Tourism", "content": ""}, {"index": "3", "level": 1, "title": "Political and Constitutional Importance", "content": ""}, {"index": "4", "level": 1, "title": "Renovations", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Bomas_of_Kenya", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:07:08.620326+11:00', '2026-01-13 00:25:13.204746+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62359, 'Мунку-Сардык', 'en', 'Mönkh Saridag, also spelled as Munku-Sardyk, is the highest mountain in the Sayan Mountains of Asia. It is 3,491 metres (11,453 ft) tall and is on the international border between Mongolia and Russia. It is also the highest mountain in Buryatia and the highest mountain in Mongolia''s Khövsgöl Province. On the southern side, the tree line is at 2000 meters, on the northern side at 2200 meters.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of highest points of Russian federal subjects List of ultras of Central Asia List of mountains in Mongolia"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"