INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70998, 'برج_الصحوة', 'en', 'Burj al Sahwa is a tower in the province of Seeb in Mawaleh in the Sultanate of Oman. It''s located inside a roundabout linking many important provinces such as Muscat and Sohar via the N5 and Nizwa and Salalah via the N2. Burj al Sahwa also represents a waiting point for a lot of trips due to its location near a transfer hub that serves nationwide & international bus and taxi trips.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Burj al Sahwa opened in October 1985. It has 4 faces each containing a digital clock and a large bell in the center of the tower ringing at every hour head.&#91;1&#93; The roundabout has seen particularly in the early morning hours heavy traffic which led to the use of traffic lights inside the roundabout during peak traffic times in 2020.&#91;2&#93; However, their effectiveness has been debated heavily as many have said that the traffic lights have not relived traffic but added to the problem.&#91;3&#93; ^ As-Seeb.com Archived 2015-11-25 at the Wayback Machine ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Traffic lights installed at Burj Al Sahwa roundabout in Seeb\". The Arabian Stories News. 2020-06-28. Retrieved 2025-09-12. ^ kaabi, Ahmed Al (2024-09-16). \"Traffic blues at Burj Al Sahwa hard to beat\". Oman Observer. Retrieved 2025-09-12."}, {"index": "2", "level": 1, "title": "Architectural design", "content": "Architectural design[edit] The tower was built with a traditional Arabic Omani design. The tower specializes with its dark colors inlaid with a layer of marble on the side. The outside walls are engraved with drawings expressing the Ottoman environment, and the grounds are decorated with greenery and some rocks."}, {"index": "3", "level": 1, "title": "Al Sahwa Gardens", "content": "Al Sahwa Gardens[edit] On 8 December 2007 near Burj as Sahwa, Sayyid Khalid al Busaidi opened the Sahwa gardens. The garden covers an area of 300,000 square meters; it contains a group of parks in which each has been independently designed with its own special shape and plants."}, {"index": "4", "level": 1, "title": "See also", "content": "See also[edit] Muscat Oman Muscat International Airport"}, {"index": "5", "level": 1, "title": "Revisions", "content": "Revisions[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Burj_Al_Sahwa", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:07:08.620326+11:00', '2026-01-13 00:25:13.204746+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71005, 'Ruacana_Falls', 'en', 'Ruacana Falls is a waterfall located in Ruacana, Omusati on the Kunene River in Northern Namibia. The waterfall is 120 meters (390 ft) high and 700 meters (2,300 ft) wide in full flood. It is among the largest waterfalls in Africa, both by volume and width.', '[{"index": "1", "level": 1, "title": "Description", "content": "Description[edit] The Ruacana Falls is formed by the 1,050 km (650 mi) long Kunene River, which marks part of the border between Namibia and Angola, plunging into a 120 metre deep and 700 metre wide gorge.&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.sk