INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71081, 'معبد_هندوسي', 'en', 'A Hindu temple, also known as a Mandir, Devasthanam, Pura, Kshetram or Kovil, is a sacred place where Hindus worship and show their devotion to deities through worship, sacrifice, and prayers. It is considered the house of the god to whom it is dedicated. Hindu temple architecture, which makes extensive use of squares and circles, has its roots in later Vedic traditions, which also influence the temples'' construction and symbolism. Through astronomical numbers and particular alignments connected to the temple''s location and the relationship between the deity and the worshipper, the temple''s design also illustrates the idea of recursion and the equivalency of the macrocosm and the microcosm. A temple incorporates all elements of the Hindu cosmos—presenting the good, the evil and the human, as well as the elements of the Hindu sense of cyclic time and the essence of life—symbolically presenting dharma, artha, kama, moksha, and karma.', '[{"index": "1", "level": 1, "title": "Significance and meaning of a temple", "content": ""}, {"index": "2", "level": 1, "title": "Forms and designs of Hindu temples", "content": ""}, {"index": "3", "level": 2, "title": "Site", "content": ""}, {"index": "4", "level": 2, "title": "Manuals", "content": ""}, {"index": "5", "level": 2, "title": "Plan", "content": ""}, {"index": "6", "level": 2, "title": "Symbolism", "content": ""}, {"index": "7", "level": 2, "title": "Building teams", "content": ""}, {"index": "8", "level": 1, "title": "Social functions of Hindu temples", "content": ""}, {"index": "9", "level": 2, "title": "Library of manuscripts", "content": ""}, {"index": "10", "level": 2, "title": "Temple schools", "content": ""}, {"index": "11", "level": 2, "title": "Hospitals, community kitchen, monasteries", "content": ""}, {"index": "12", "level": 1, "title": "Styles", "content": ""}, {"index": "13", "level": 1, "title": "Arts inside Hindu temples", "content": ""}, {"index": "14", "level": 1, "title": "Historical development and destruction", "content": ""}, {"index": "15", "level": 1, "title": "Customs and etiquette", "content": ""}, {"index": "16", "level": 1, "title": "Regional variations in Hindu temples", "content": ""}, {"index": "17", "level": 2, "title": "Nagara Architecture of North Indian temples", "content": ""}, {"index": "18", "level": 2, "title": "Temples in West Bengal", "content": ""}, {"index": "19", "level": 2, "title": "Temples in Odisha", "content": ""}, {"index": "20", "level": 2, "title": "Temples of Goa and Konkani", "content": ""}, {"index": "21", "level": 2, "title": "South Indian and Sri Lankan temples", "content": ""}, {"index": "22", "level": 3, "title": "Temples in Kerala", "content": ""}, {"index": "23", "level": 3, "title": "Temples in Tamil Nadu", "content": ""}, {"index": "24", "level": 2, "title": "Temples in Nepal", "content": ""}, {"index": "25", "level": 2, "title": "Khmer Temples", "content": ""}, {"index": "26", "level": 2, "title": "Temples in Indonesia", "content": ""}, {"index": "27", "level": 2, "title": "Temples in Vietnam", "content": ""}, {"index": "28", "level": 2, "title": "Temples in Thailand", "content": ""}, {"index": "29", "level": 2, "title": "Temples outside Asia", "content": ""}, {"index": "30", "level": 3, "title": "New York/New Jersey", "content": ""}, {"index": "31", "level": 3, "title": "Outside New York/New Jersey", "content": ""}, {"index": "32", "level": 1, "title": "Temple management", "content": ""}, {"index": "33", "level": 1, "title": "Etymology and nomenclature", "content": ""}, {"index": "34", "level": 1, "title": "See also", "content": ""}, {"index": "35", "level": 1, "title": "Notes", "content": ""}, {"index": "36", "level": 1, "title": "References", "content": ""}, {"index": "37", "level": 1, "title": "Bibliography", "content": ""}, {"index": "38", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hindu_temple", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:07:08.620326+11:00', '2026-01-13 00:25:13.211128+11:00');
