INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71240, 'Oskar_Schindler', 'en', 'Oskar Schindler was a German industrialist, humanitarian, and member of the Nazi Party who is credited with saving the lives of 1,200 Jews during the Holocaust by employing them in his enamelware and ammunitions factories in occupied Poland and the Protectorate of Bohemia and Moravia. He is the subject of the 1982 novel Schindler''s Ark and its 1993 film adaptation, Schindler''s List.', '[{"index": "1", "level": 1, "title": "Early life and education", "content": ""}, {"index": "2", "level": 1, "title": "Spy for the <i>Abwehr</i>", "content": ""}, {"index": "3", "level": 1, "title": "World War II", "content": ""}, {"index": "4", "level": 2, "title": "Emalia", "content": ""}, {"index": "5", "level": 2, "title": "Płaszów", "content": ""}, {"index": "6", "level": 2, "title": "Brünnlitz", "content": ""}, {"index": "7", "level": 1, "title": "After the war", "content": ""}, {"index": "8", "level": 2, "title": "Escape to the American lines", "content": ""}, {"index": "9", "level": 1, "title": "Legacy", "content": ""}, {"index": "10", "level": 2, "title": "Films and book", "content": ""}, {"index": "11", "level": 2, "title": "Schindler''s suitcase", "content": ""}, {"index": "12", "level": 2, "title": "Copies of the list", "content": ""}, {"index": "13", "level": 2, "title": "Museum", "content": ""}, {"index": "14", "level": 2, "title": "Other memorabilia", "content": ""}, {"index": "15", "level": 1, "title": "See also", "content": ""}, {"index": "16", "level": 1, "title": "Notes", "content": ""}, {"index": "17", "level": 1, "title": "References", "content": ""}, {"index": "18", "level": 1, "title": "Sources", "content": ""}, {"index": "19", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Oskar_Schindler", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:11:40.586864+11:00', '2026-01-13 00:25:13.218501+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71249, 'Gold_Reef_City', 'en', 'Gold Reef City is an amusement park in Johannesburg, South Africa. Located on an old gold mine which closed in 1971, the park is themed around the gold rush that started in 1886 on the Witwatersrand, and the buildings in the park are designed to mimic this period. There is a museum dedicated to gold mining on the grounds where it is possible to see a gold-containing ore vein and see how gold is poured into barrels.', '[{"index": "1", "level": 1, "title": "Rides and attractions", "content": "Rides and attractions[edit] Liquid gold being poured into a cast to make a bullion bar at a Gold Reef City demonstration Some of the popular rides at the theme park include: The Anaconda, the world''s only Giovanola inverted coaster. Golden Loop, a Schwarzkopf Shuttle Loop coaster. Originally White Lightnin'' at Carowinds. Jozi Express, a high-speed roller coaster built and manufactured by the German amusement park ride manufacturer Zierer. Miner''s Revenge Raging River Rapids Runaway Train Storm Chaser The High Flying Maverick Tower of Terror, a high-speed roller coaster with a vertical drop into an old mineshaft and the highest g-force of any active roller coaster at 6.3 g. UFO, a giant wheel that spins at high speed while being lifted from a horizontal position to a near-60-degree position. Giant Wheel, a Ferris wheel"}, {"index": "2", "level": 1, "title": "Potential flooding", "content": "Potential flooding[edit] It was reported in 2013 that acidic mine water was slowly rising within the mine on which the park is built and that there was a possibility of the park being flooded if left unattended. Mine tours were temporarily halted, and the museum was moved from 215m underground to 80m aboveground.&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Acid mine water rises under Gold Reef City\". Business Day. 11 October 2013. Retrieved 4 August 2014."}, {"index": "3", "level": 1, "title": "Photo gallery", "content": "Photo gallery[edit] Original mining houses from the early 20th century on display in the park The living room in the mine manager''s house The dining room in the mine manager''s house The kitchen in the mine manager''s house The mine headgear as seen from the Big Wheel Class 19D steam locomotive on display The information board for the Class 19D locomotive on display in the park"}, {"index": "4", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "5", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Gold Reef City. Official Website .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,.mw-parser-output .hlist dl ol,.mw-parser-output .hlist dl ul,.mw-parser-output .hlist ol dl,.mw-parser-output .h