INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66383, 'Chysauster_Ancient_Village', 'en', 'Chysauster Ancient Village is a late Iron Age and Romano-British village of courtyard houses in Cornwall, England, United Kingdom, which is currently in the care of English Heritage. The village included eight to ten houses, each with its own internal courtyard. To the south east is the remains of a fogou, an underground structure of uncertain function.', '[{"index": "1", "level": 1, "title": "Location", "content": ""}, {"index": "2", "level": 1, "title": "Settlement", "content": ""}, {"index": "3", "level": 1, "title": "Fogou", "content": ""}, {"index": "4", "level": 1, "title": "References", "content": ""}, {"index": "5", "level": 1, "title": "Further reading", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Chysauster_Ancient_Village", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:52:10.075883+11:00', '2026-01-13 00:25:12.939827+11:00');
