INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66411, 'Bílá_hora', 'en', 'Bílá hora nằm ở ngoại ô phía tây của Praha, ở bên phải phía trên thung lũng của Litovický Potok.', '[{"index": "1", "level": 1, "title": "Địa lý", "content": "Địa lý[sửa | sửa mã nguồn] Bílá hora nằm ở độ cao 379 mét. Từ trung tâm của Praha bằng giao thông công cộng mất khoảng 25-30 phút để tới đó (tuyến tàu điện 22 và 25)."}, {"index": "2", "level": 1, "title": "Lịch sử", "content": "Lịch sử[sửa | sửa mã nguồn] .mw-parser-output .hatnote{font-style:italic}.mw-parser-output div.hatnote{padding-left:1.6em;margin-bottom:0.5em}.mw-parser-output .hatnote i{font-style:normal}.mw-parser-output .hatnote+link+.hatnote{margin-top:-0.5em}@media print{body.ns-0 .mw-parser-output .hatnote{display:none!important}}Bài chi tiết: Trận đánh tại Núi trắng Tại đây đã xảy ra vào ngày 8 tháng 11 năm 1620 trận đánh quyết định đầu tiên của cuộc Chiến tranh 30 năm, Trận đánh tại Núi trắng. Tại vị trí của trận đánh một nhà nguyện và từ 1704 tới 1714 một nhà thờ Đức mẹ baroque được xây."}, {"index": "3", "level": 1, "title": "Chú thích", "content": "Chú thích[sửa | sửa mã nguồn] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list