INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66648, 'Hortus_Haren', 'en', 'Hortus Haren is a botanical garden in Haren, Groningen, Netherlands. First created in 1626 by the pharmacist Henricus Munting, it was then situated between Grote Rozenstraat and Grote Kruisstraat in Groningen. Because of space considerations it relocated to Haren in 1967 and became the largest botanical garden in the country.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] Building depicting a boat in the Chinese garden of the Hidden Realm of Ming pavilion. Bridge in the Chinese garden. Waterfall in the Chinese garden. Lake in the Hortus Haren (Voedselarme plas). Chinese Garden The Hidden Empire Ming, mosaic pavement courtyard. ‘In The Wind’. Artwork by Jeroen Boersma. Wikimedia Commons Picture of the Day, 21 September 2022"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-out