INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71400, 'سد_وادي_جازان', 'en', 'The Jizan Dam, also spelled Jazan, is a gravity dam on Wadi Jizan about 16 km (9.9 mi) northeast of Abu `Arish in Jizan Province of southwest Saudi Arabia. It has several purpose to include irrigation and flood control. Located in a desert, the dam collects run-off and stores it for periodic releases downstream. Water released from the dam is distributed by two diversion dams downstream for the irrigation of 8,000 ha of land. Crops grown include sorghum with eucalyptus and tamarisk grown for anti-desertification. The dam was completed in 1970 and is owned by the Ministry of Water and Electricity.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of dams in Saudi Arabia"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .portalbox{padding:0;margin:0.5em 0;display:table;box-sizing:border-box;max-width:175px;list-style:none}.mw-parser-output .portalborder{border:1px solid var(--border-color-base,#a2a9b1);padding:0.1em;background:var(--background-color-neutral-subtle,#f8f9fa)}.mw-parser-output .portalbox-entry{display:table-row;font-size:85%;line-height:110%;height:1.9em;font-style:italic;font-weight:bold}.mw-parser-output .portalbox-image{display:table-cell;padding:0.2em;vertical-align:middle;text-align:center}.mw-parser-output .portalbox-link{display:table-cell;padding:0.2em 0.2em 0.2em 0.3em;vertical-align:middle}@media(min-width:720px){.mw-parser-output .portalleft{margin:0.5em 1em 0.5em 0}.mw-parser-output .portalright{clear:right;float:right;margin:0.5em 0 0.5em 1em}} Saudi Arabia portal"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Jizan_Dam", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:16:32.508293+11:00', '2026-01-13 00:25:13.224899+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71414, 'ديوان_جبل_أثلب', 'en', 'ديوان جبل أثلب يوجد في جبل أثلب في الشمال الشرقي من مدائن صالح، ويحيط به فضاء واسع، وكما في مدينة البتراء بالأردن فلمنطقة الجبل طريق ضيق يسمى (السيق)، ونحت داخل الصخرة صالة كبيرة مفتوحة تسمى الديوان، ومحاطة بعمودين وبعض المصطبات الحجرية على الجدران الثلاثة الداخلية، والديوان عبارة عن قاعة ذات زوايا مربعة، عرضها عشرة أمتار، وعمقها اثنا عشر متر، وارتفاعها ثمانية أمتار، ولها مدخل عرضه ثمانية أمتار و35 سنتمتر، واراتفاعه سبعة أمتار وزهاء خمسة سنتيمترات، على كل جانب منه عمود من حجر، جعلت زواياه مربعة، أما الباب فقد تلف ويوصل إلى هذا المدخل مدرج.', '[{"index": "1", "level": 1, "title": "المراجع", "content": "المراجع[عدل] .mw-parser-output .reflist-wrap{overflow-y:auto;max-height:300px}.mw-parser-output .reflist{font-size:90%;margin-bottom:0.5em;list-style-type:decimal}.mw-parser-output .reflist .references{font-size:100%;margin-bottom:0;list-style-type:inherit}.mw-parser-output .reflist-columns-2{column-width:36em}.mw-parser-output .reflist-columns-3{column-width:28em}.mw-parser-output .reflist-columns-4{column-width:20em}.mw-parser-output .reflist-columns{margin-top:0.3em}.mw-parser-output .reflist-columns ol{margin-top:0}.mw-parser-output .reflist-columns li{page-break-inside:avoid;break-inside:avoid-column}.mw-parser-output .reflist-upper-alpha{list-style-type:upper-alpha}.mw-parser-output .reflist-upper-roman{list-style-type:upper-roman}.mw-parser-output .reflist-lower-alpha{list-style-type:lower-alpha}.mw-parser-output .reflist-lower-greek{list-style-type:lower-greek}.mw-parser-output .reflist-lower-roman{list-style-type:lower-roman}@media print{.mw-parser-output .reflist{overflow-y:visible!important;max-height:none!important}} .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-