INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62419, '古奇峰', 'en', '古奇峰位於台灣新竹市郊，原稱平埔頂，四周環繞著令人心曠神怡的自然綠意，包括十八尖山、青草湖、清華大學、交通大學及科學園區等，風光明媚。「古奇遠眺」是竹塹八景之一。
