INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62435, '天涯海角', 'en', 'Tianya Haijiao is a popular visitor attraction 24 kilometres (15 mi) west of Sanya city, Hainan, China.', '[{"index": "1", "level": 1, "title": "Popular tourist attractions", "content": "Popular tourist attractions[edit] The Rocks of Sun and Moon (日月石) are two boulders near hundreds of other uniquely shaped rocks. Here the \"Sun\" refers to \"husband\" and the \"Moon\" refers to \"wife\". Looking from the distance, they resemble a couple entwined to each other but they are in fact separate rocks. Southern Heaven Rock (南天一柱), a boulder near the Rock of Sun and Moon, with a famous poem of Fan Yun-Ti (范雲梯) inscribed on its top.&#91;1&#93; Tian-Ya Cliff (天涯), with an inscription by Cheng Zhe on the top. Pre-Historic Shell Museum ^ The Southern Heaven Rock"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.r