INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62442, '太魯閣牌樓', 'en', '太魯閣牌樓，台灣中橫公路的入口牌樓，為花蓮縣秀林鄉旅遊景點之一，位於錦文橋南端橋頭與中橫公路交會之路口上，標高60公尺，其里程位置是台8線187.5K與花2線2.720K。在公路旁的岩壁上則刻「魯閣長春」四字，在太魯閣牌樓附近設置的展望台，可供遊客駐足觀賞其景點。
