INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62446, '水木清华', 'en', '水木清华是北京清华园中一個景点，位于清华大学工字厅的北侧。', '[{"index": "1", "level": 1, "title": "歷史", "content": "歷史[编辑] 荷塘南侧的古建本为工字厅的后厦，为“水木清华”的正廊，正额“水木清华”据历史记载是清朝康熙皇帝的御笔。 “水木清华”出于晋朝谢混诗：“惠风荡繁囿，白云屯曾阿。景昃鸣禽集，水木湛清华。”正廊朱柱上悬有源自清代扬州瘦西湖贺园的名联：“槛外山光历春夏秋冬万千变幻都非凡境，窗中云影任东西南北去来澹荡洵是仙居。” 此对联在李斗（1749年—1817年）《扬州画舫录》中有记载，具体作者不详。&#91;1&#93; 咸丰皇帝即位后，借用99年前乾隆皇帝在此处的题词，把工字厅命名为“清华园”，清华园因此得名。&#91;2&#93; 1978年清华大学纪念朱自清逝世30周年，把近春园荷花池边的古亭改名为“自清亭”，并于水木清华荷塘北侧树立朱自清教授的汉白玉塑像。但是朱自清的《荷塘月色》中所称的荷塘并非水木清华的荷塘，而是清华园中另一景近春园的荷花池。 ^ 李斗. 扬州画舫录. 北京: 中华书局. 2016: 323. ISBN&#160;978-7-101-01705-2 （繁体中文）. 槛外山光历春夏秋冬万千变幻都非凡境，窗中云影任东西南北去来澹荡洵是仙居&#160; 引文格式1维护：未识别语文类型 (link) ^ 苗日新. 清九代王朝熙春园（清华园）主人的更替. 清华大学新闻网. 清华校友通讯. 2007 &#91;2010-11-14&#93;. （原始内容存档于2016-09-13） （中文（中国大陆））.&#160;"}, {"index": "2", "level": 1, "title": "風景", "content": "風景[编辑] 水木清华的主体景观是工字厅后面的一个荷塘，荷塘之畔垂杨山水之中掩映着一幢秀雅的古建筑，清華校友常將其与颐和园中的谐趣园相比。&#91;1&#93; 水木清华的景观设计者独具匠心，用山林环拢着一泓碧水，山水之间掩映着两座典雅的古亭，其中一亭中就悬挂着清华校徽的那座钟。 ^ 引用错误：没有为名为11a的参考文献提供内容"}, {"index": "3", "level": 1, "title": "外部链接", "content": "外部链接[编辑] 水木清华照片：访学闲记（三）----清华园之荷塘"}, {"index": "4", "level": 1, "title": "参考文献", "content": "参考文献[编辑] .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,.mw-parser-output .hlist dl ol,.mw-parser-output .hlist dl ul,.mw-parser-output .hlist ol dl,.mw-parser-output .hlist ol ol,.mw-parser-output .hlist ol ul,.mw-parser-output .hlist ul dl,.mw-parser-output .hlist ul ol,.mw-parser-output .hlist ul ul{display:inline}.mw-parser-output .hlist .mw-empty-li{display:none}.mw-parser-output .hlist dt::after{content:\" 