INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68255, 'Дувало', 'en', 'Duvalo is an active geothermal surface feature situated close to the village of Kosel, near Lake Ohrid in the southwest of North Macedonia. Located at 740 metres above the sea level, it resembles a miniature crater with a diameter of 50 metres and a depth of 30 metres. Gaseous carbon dioxide and sulfur dioxide are released from the hole, and the smell of sulfur is said to be felt in a 3 kilometre radius around it. It represents the last traces of the historically significant volcanic activity in the area. During the Ottoman Empire it was used to mine sulfur.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] Duvalo. Duvalo. Duvalo. Duvalo. Duvalo. Duvalo. Duvalo. Duvalo. Duvalo. Duvalo. Duvalo. Duvalo."}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] Lists of volcanoes"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-