INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62496, '湖口老街', 'en', '湖口老街是位在臺灣新竹縣湖口鄉的一條街道，其中包括街頭、橫街、新街三條街。其興衰與鐵路密切相關，這一帶因為劉銘傳所鋪設的鐵路延伸至此，設有「大湖口火車碼頭」而繁榮，並在日治時期整建成今日風貌，但後來因為鐵路路線調整，「湖口驛」移到下北勢而使街道商業衰退。街道上有新竹縣縣定古蹟湖口三元宮與歷史建築老湖口天主堂，而湖口天主堂即是在舊車站原址上建造而成。近年來經由居民與政府社區總體營造之下，翻修老街牌樓、店亭、石板路與綠化工程，湖口老街有了新風貌。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62497, '馬山觀測所', 'en', 'The Mashan Broadcasting and Observation Station is a historical broadcasting station and observation tower in Jinsha Township, Kinmen County, Taiwan.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The station used to send out propaganda message to the People''s Liberation Army soldiers in Mainland China to surrender and join the Republic of China Armed Forces.&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inher