INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69221, 'OzIris', 'en', 'OzIris is an inverted roller coaster designed by Bolliger & Mabillard operating at Parc Astérix in France since 7 April 2012. It is only one of two Bolliger & Mabillard inverted coasters in France, the other being The Monster at Walygator Parc. It is named after Iris, a character from the comic Asterix.', '[{"index": "1", "level": 1, "title": "Ride", "content": ""}, {"index": "2", "level": 2, "title": "Theme", "content": ""}, {"index": "3", "level": 2, "title": "Storyline", "content": ""}, {"index": "4", "level": 1, "title": "Awards", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/OzIris", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:20:08.327149+11:00', '2026-01-13 00:25:13.122005+11:00');
