INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62508, 'Dhuandhar_Falls', 'en', 'The Dhuandhar Falls (धुआंधार) is a waterfall in Jabalpur district in the Indian state of Madhya Pradesh.', '[{"index": "1", "level": 1, "title": "Etymology", "content": ""}, {"index": "2", "level": 1, "title": "The Falls", "content": ""}, {"index": "3", "level": 1, "title": "Cable car service at Dhuandhar Waterfalls", "content": ""}, {"index": "4", "level": 1, "title": "Gallery", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Dhuandhar_Falls", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:41:57.525892+11:00', '2026-01-13 00:25:12.682722+11:00');
