INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69484, 'Agua_Azul', 'en', 'The Cascadas de Agua Azul are a series of waterfalls found on the Xanil River in the southern Mexican state of Chiapas. They are located in the Municipality of Tumbalá, 69 kilometres (43 mi) from Palenque, near Mexican Federal Highway 199.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] The series of Agua Azul cascades seen from the top Trees in different stages of calcification Xanil River basin"}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] List of waterfalls"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "4", "level": 1, "title": "External links", "content": "