INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69494, 'Candlestick_Tower', 'en', 'Candlestick Tower is a 450-foot-tall (140 m) sandstone butte located in the Island in the Sky District of Canyonlands National Park, in San Juan County, Utah. Its descriptive name comes from its resemblance to a candlestick. Candlestick Tower is composed of Wingate Sandstone, which is the remains of wind-borne sand dunes deposited approximately 200 million years ago in the Late Triassic.', '[{"index": "1", "level": 1, "title": "Climbing", "content": ""}, {"index": "2", "level": 1, "title": "Climate", "content": ""}, {"index": "3", "level": 1, "title": "Gallery", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Candlestick_Tower", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:31:10.712663+11:00', '2026-01-13 00:25:13.141045+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69497, 'Mount_Sylvania', 'en', 'Mount Sylvania is an extinct volcano, part of the Boring Lava Field, on the outskirts of Portland, Oregon. Parts of the mountain are within the cities of Portland, Lake Oswego, and Tigard.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/c