INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69528, 'Little_Finland', 'en', 'Little Finland is a scenic red rock area, located in a remote section of Clark County, Nevada, south of Mesquite, known for its red rock scenery and strangely-shaped, delicate rock formations. The landscape is similar to Valley of Fire State Park, which is about 20 miles (32 km) to the west, across Lake Mead. The rock formations are composed of red Aztec Sandstone, fossil sand dunes. Many of the features are small erosional fins, hence the name.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit]"}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] .mw-parser-output .portalbox{padding:0;margin:0.5em 0;display:table;box-sizing:border-box;max-width:175px;list-style:none}.mw-parser-output .portalborder{border:1px solid var(--border-color-base,#a2a9b1);padding:0.1em;background:var(--background-color-neutral-subtle,#f8f9fa)}.mw-parser-output .portalbox-entry{display:table-row;font-size:85%;line-height:110%;height:1.9em;font-style:italic;font-weight:bold}.mw-parser-output .portalbox-image{display:table-cell;padding:0.2em;vertical-align:middle;text-align:center}.mw-parser-output .portalbox-link{display:table-cell;padding:0.2em 0.2em 0.2em 0.3em;vertical-align:middle}@media(min-width:720px){.mw-parser-output .portalleft{margin:0.5em 1em 0.5em 0}.mw-parser-output .portalright{clear:right;float:right;margin:0.5em 0 0.5em 1em}} Nevada portal Lake Mead National Recreation Area, to the west and south of Little Finland &#91;1&#93; Grand Canyon-Parashant National Monument, to the east, in Arizona &#91;1&#93; Bureau of Land Management Back Country Byway ^ a b Cite error: The named reference map was invoked but never defined (see the help page)."}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-