INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69580, 'Balls_Creek_Campground', 'en', 'Balls Creek Campground is a historic Methodist camp meeting and national historic district located near Bandy''s Crossroads, Catawba County, North Carolina.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The site was established in 1853 and is an offshoot of Rock Springs Campmeeting in Denver, NC after Lincoln was split into Catawba and Lincoln counties which is believed to be one of the largest religious campgrounds in the southern United States.&#91;1&#93; A camp meeting continues to be held there every August, with \"tents\" selling for as much as $65,000 each.&#91;2&#93; The site was added to the National Register of Historic Places in 1990.&#91;3&#93; On September 29, 2019, a \"suspicious\" fire destroyed or damaged 40 of the site''s 302 cabins and elicited the response of more than 14 fire departments and over 100 firefighters from Catawba and surrounding counties.&#91;4&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisou