INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69719, 'Courthouse_Towers', 'en', 'The Courthouse Towers is a collection of tall stone columns located within the Park Avenue section of Arches National Park. The formation was named after its reminiscence to tall buildings in Park Avenue, New York City.', '[{"index": "1", "level": 1, "title": "Access", "content": "Access[edit] This hike begins at the Park Avenue viewpoint and trailhead, located on the north side of the Arches Scenic Drive, 2.3 miles from the visitor center. The trail also gives access to the Three Gossips.&#91;1&#93; ^ Details: Park Avenue Trail, HikingWalking.com, July 9, 2023, https://hikingwalking.com/index.php/destinations/ut/ut_se/arches/park_avenue/park_avenue_detail"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-outp