INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69740, 'Ledge_View_Nature_Center', 'en', 'Ledge View Nature Center is a 105-acre (0.42 km2) park and interpretive center. It is located two miles (3 km) south of Chilton, Wisconsin. The facility is part of the Calumet County Parks system operated by Calumet County.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The site was purchased from Zimmermann in 1969. The nature center was built in 1981, and an addition was constructed in 1986. In 1998 the Frisch Family exhibit hall was constructed."}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] List of botanical gardens and arboretums in Wisconsin Other caves on the Niagara Escarpment Cherney Maribel Caves County Park (also has caves open to tours) Door Peninsula § Caves and sinkholes Spider Cave"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alph