INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69744, 'Earthplace', 'en', 'Earthplace is a non-profit science education organization, in Westport, Connecticut, in the United States. Its main focus is on the natural world and sustainability.', '[{"index": "1", "level": 1, "title": "Features", "content": ""}, {"index": "2", "level": 1, "title": "Environmental activities", "content": ""}, {"index": "3", "level": 1, "title": "Education", "content": ""}, {"index": "4", "level": 1, "title": "History", "content": "History[edit] Earthplace was founded in 1958 as one of the many science and nature museums being developed around the US by groups led by naturalist John Ripley Forbes. The Mid-Fairfield County Youth Museum opened in 1961. In 1973 the organization changed its name to the Nature Center for Environmental Activities. In 2002 the name was changed to Earthplace, The Nature Discovery Center. In 2007, the 22 acre Partrick Wetlands open space was donated to Earthplace."}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Earthplace", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:40:21.128947+11:00', '2026-01-13 00:25:13.160767+11:00');
