INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69899, 'Two_Brothers_Rocks', 'en', 'The Two Brothers Rocks are a rock formation in the Ionian Sea to the north-east of Syracuse in Sicily.', '[{"index": "1", "level": 1, "title": "Geography", "content": ""}, {"index": "2", "level": 2, "title": "The rocks", "content": ""}, {"index": "3", "level": 1, "title": "Legend of the two brothers", "content": ""}, {"index": "4", "level": 1, "title": "Flora and fauna", "content": ""}, {"index": "5", "level": 1, "title": "Tourism", "content": ""}, {"index": "6", "level": 1, "title": "How to reach the rocks", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Two_Brothers_Rocks", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:45:58.188265+11:00', '2026-01-13 00:25:13.167116+11:00');
