INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69994, 'Bubbleator', 'en', 'The Bubbleator was a large, bubble-shaped hydraulic elevator with transparent acrylic glass walls operated from an elevated chair built for the 1962 World''s Fair in Seattle. These transparent walls gave the illusion of looking through an actual ''soap bubble'' by refracting light to obtain a rainbow-like effect for the riders inside. It was originally part of the Washington State Coliseum, where it lifted 100 passengers at a time up one floor through a structure of interlocking aluminum cubes to the "World of Tomorrow" exhibit. T. C. Howard of Synergetics, Inc. designed the Bubbleator and the exhibit. After the fair, the Bubbleator was relocated to the Center House at Seattle Center. By 1984, it had been removed and put in storage to make way for the Seattle Children''s Museum. It was sold to a private owner in Des Moines, Washington, who recycled the upper part of the dome into a greenhouse. The control chair, which had also been in private hands, was donated to the Museum of History and Industry in 2005.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-l