INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70058, 'Tanjung_Tuan', 'en', 'Tanjung Tuan, formerly known as Cape Rachado as named by the Portuguese, meaning ''broken cape'', is an area in Alor Gajah District, Malacca, Malaysia. It is a semi-exclave of Malacca adjacent to Port Dickson, Negeri Sembilan.', '[{"index": "1", "level": 1, "title": "Lighthouse", "content": ""}, {"index": "2", "level": 1, "title": "Forest reserve", "content": ""}, {"index": "3", "level": 1, "title": "Burial Place", "content": ""}, {"index": "4", "level": 1, "title": "Further reading", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "Notes and references", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Tanjung_Tuan", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:50:34.098854+11:00', '2026-01-13 00:25:13.179344+11:00');
