INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70297, 'Thác_Prenn', 'en', 'Thác Prenn là một thác nước ở thành phố Đà Lạt thuộc tỉnh Lâm Đồng, Việt Nam.', '[{"index": "1", "level": 1, "title": "Nguồn gốc tên gọi", "content": "Nguồn gốc tên gọi[sửa | sửa mã nguồn] Theo truyền thuyết mà các già làng kể lại thì thác có tên gọi trên là xuất phát từ tiếng K’Ho đầu tiên có tên gọi Prềnh – có nghĩa là Cà đắng, sau người dân đọc lại thành Prenn. Bằng chứng là ngày nay, ở khu vực thượng nguồn của thác, dọc hai bên bờ suối vẫn còn rất nhiều cây Cà đắng mọc hoang. Loại cà này có trái nhỏ và tròn như cà pháo nhưng vỏ xanh và có điểm nhiều chấm trắng, khi chín có màu vàng. Ngày xưa người dân tộc đem chế biến và ăn có vị đắng rất ngon. Còn theo các nhà dân tộc học thì tên của thác nước này, lại xuất phát từ tiếng Chăm. Prenn có nghĩa là “vùng lấn chiếm”. Tên gọi này xuất phát từ cuộc chiến tranh khá dai dẳng của các bộ tộc người thiểu số sống trên vùng đất này để chống lại những lần “Tây tiến” của người Chăm ở Panduranga (Ninh Thuận) vào thế kỷ 17, và người dân địa phương lấy tên này đặt tên cho thác nước hùng vĩ quanh năm nước chảy tạo sương trắng bảng lảng cả một vùng và từ đó thác có tên gọi Prenn."}, {"index": "2", "level": 1, "title": "Miêu tả", "content": "Miêu tả[sửa | sửa mã nguồn] Để vào thác, du khách phải qua một chiếc cầu ngắn bắc ngang dòng suối đã được kè chắn bằng bêtông nhằm tránh bị xói lở. Con đường xuống thác thật đẹp với những bậc đá ôm theo sườn đồi được bố trí một cách hợp lý; Du khách sẽ nhìn thấy một bức màn nước buông mình từ độ cao gần 10m xuống thung lũng nhỏ đã được chỉnh sửa thành vườn hoa mà từ đây có nhiều lối đẹp đưa chân lên các đồi thông thoáng đãng chung quanh. Du khách có thể men theo các con đường dẫn đến vườn thú, vườn lan hay thư thả dạo gót hoa viên ngắm nhìn những bông hoa khoe sắc, những căn chòi xinh xinh trên ngọn cây hoặc đung đưa cùng cầu treo bắc ngang dòng suối nhỏ. Ở một góc độ khác, vườn đá Thái Dương với sự sắp xếp đầy ngẫu hứng tạo được một bất ngờ thú vị. Đặc biệt với hệ thống cáp treo, du khách có thể ngang qua dòng thác trong cảm giác phiêu bồng, tưởng như đang đi vào cõi thần tiên... Trải nghiệm các dịch vụ tại khu du lịch thác Prenn: Cưỡi Voi lội suối; cưỡi đà điểu, lạc đà, cưỡi ngựa, cưỡi trâu Tham gia các trò chơi dân gian: Bắn cung, bắn nỏ, bắn súng; dịch vụ hóa trang dân tộc, bơi thuyền lội suối... Thác Prenn đã được bộ VH-TT công nhận và cấp bằng di tích lịch sử văn hoá quốc gia (năm 2000). Đặc biệt trong năm 2002, đơn vị quản lý đã đầu tư xây dựng đền thờ Âu Lạc trên đỉnh núi cao nhìn xuống thác.(dựa theo truyền thuyết Lạc Long Quân và Âu Cơ) ở phía trên đồi cao để khách tham quan, dâng hương. Hiện nay, thác Prenn do Công ty cổ phần Dịch vụ Du lịch Đà Lạt quản lý khai thác.&#91;1&#93; Thác Prenn mùa bão lũ năm 2006 Thác Prenn tháng 6 năm 2011 ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva)