INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70397, '忍野八海', 'en', 'Oshino Hakkai are the eight springs found in Oshino, Yamanashi, Japan. The aquifer water from Mount Fuji comes out to the ground to form these springs. They are a Natural monument of Japan, part of the Mount Fuji World Heritage Site, and one of Yamanashi Prefecture''s important tourist attractions.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] The traditional eight springs are called: Deguchiike Pond (出口池) Okamaike Pond (お釜池) Sokonashiike Pond (底抜池) Choshiike Pond (銚子池) Wakuike Pond (涌池) Nigoriike Pond (濁池) Kagamiike Pond (鏡池) Shobuike Pond (菖蒲池)"}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] Fuji Five Lakes Fuji-Hakone-Izu National Park"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-ty