INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70776, 'Rhodes_Memorial', 'en', 'The Rhodes Memorial is a large monument in the style of an ancient Greek temple on Devil''s Peak in Cape Town, South Africa, situated close to Table Mountain. It is a memorial to the English-born South African politician Cecil John Rhodes, was designed by architect Herbert Baker and finished in 1912.', '[{"index": "1", "level": 1, "title": "Location", "content": ""}, {"index": "2", "level": 1, "title": "Architecture", "content": ""}, {"index": "3", "level": 1, "title": "Outdoor activities", "content": ""}, {"index": "4", "level": 1, "title": "The area around the memorial", "content": ""}, {"index": "5", "level": 1, "title": "Controversy of the memorial", "content": ""}, {"index": "6", "level": 2, "title": "Vandalism", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Rhodes_Memorial", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:03:36.688008+11:00', '2026-01-13 00:25:13.198512+11:00');
