INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (70849, 'Epupa_Falls', 'en', 'Epupa Falls is a series of large waterfalls formed by the Cunene River on the border of Angola and Namibia, in the Kaokoland area of the Kunene Region. The river is about 0.5 kilometres (1,600 ft) wide in this area and drops in a series of waterfalls across a length of 1.5 kilometres (0.93 mi), with the greatest single drop being 37 metres (121 ft). The settlement near the falls is also called Epupa.', '[{"index": "1", "level": 1, "title": "Toponymy", "content": ""}, {"index": "2", "level": 1, "title": "Ecology", "content": ""}, {"index": "3", "level": 1, "title": "Access", "content": ""}, {"index": "4", "level": 2, "title": "People", "content": ""}, {"index": "5", "level": 1, "title": "In the media", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "Sources", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Epupa_Falls", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:05:36.009247+11:00', '2026-01-13 00:25:13.204746+11:00');
