INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71340, 'هزار', 'en', 'The common nightingale, rufous nightingale or simply nightingale, is a small passerine bird which is best known for its powerful and beautiful song. An Old World flycatcher, it belongs to a group of more terrestrial species, often called chats. Its range partly overlaps with that of the more northerly thrush nightingale, a closely related species with which hybrids have occurred.', '[{"index": "1", "level": 1, "title": "Taxonomy", "content": ""}, {"index": "2", "level": 1, "title": "Description", "content": "Description[edit] Male Luscinia megarhynchos The common nightingale is slightly larger than the European robin, at 15–16.5&#160;cm (5.9–6.5&#160;in) length. It is plain brown above except for the reddish tail. It is buff to white below. The sexes are similar. The eastern subspecies (L. m. golzi) and the Caucasian subspecies (L. m. africana) have paler upper parts and a stronger face-pattern, including a pale supercilium. The song of the male nightingale&#91;1&#93; has been described as one of the most beautiful sounds in nature, inspiring songs, fairy tales, opera, books, and a great deal of poetry.&#91;2&#93; However, historically most people were not aware that female nightingales do not sing. Song recorded in Devon, England ^ British Library Sound Archive. British wildlife recordings: Nightingale, accessed 29 May 2013 ^ Maxwell, Catherine. \"The Female Sublime from Milton to Swinburne: Bearing Blindness\", Manchester University Press, 2001, pp. 26–29 .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}ISBN&#160;0719057523"}, {"index": "3", "level": 1, "title": "Distribution and habitat", "content": ""}, {"index": "4", "level": 1, "title": "Behaviour and ecology", "content": ""}, {"index": "5", "level": 1, "title": "Cultural connotations", "content": ""}, {"index": "6", "level": 1, "title": "Cultural depictions", "content": ""}, {"index": "7", "level": 2, "title": "In the Baha''i Faith", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Common_nightingale", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:15:20.038405+11:00', '2026-01-13 00:25:13.218501+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62593, 'Дом_Шадрина', 'en', 'Дом купцов Шадриных — памятник архитектуры начала XX века, один из символов Барнаула. Расположен в Центральном районе города на Красноармейском проспекте рядом с площадью Спартака.', '[{"index": "1", "level": 1, "title": "История", "content": ""}, {"index": "2", "level": 1, "title": "Архитектура", "content": ""}, {"index": "3", "level": 1, "title": "См. также", "content": ""}, {"index": "4", "level": 1, "title": "Литература", "content": ""}, {"index": "5", "level": 1, "title": "Примечания", "content": ""}, {"index": "6", "level": 1, "title": "Ссылки", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%94%D0%BE%D0%BC_%D0%A8%D0%B0%D0%B4%D1%80%D0%B8%D0%BD%D0%B0", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:45:49.398015+11:00', '2026-01-13 00:25:12.694154+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (71370, 'Larabanga_Mosque', 'en', 'The Larabanga Mosque is a mosque built in the Sudanese architectural style in the village of Larabanga, Savanna Region of Ghana. It is the oldest mosque in the country and one of the oldest in West Africa, and has been referred to as the "Mecca of West Africa". The mosque has undergone restoration several times since it was founded in 1421 CE; most recently in 2023. The World Monuments Fund (WMF) has contributed substantially to its restoration and lists it as one of the 100 Most Endangered Sites. The restoration works have revived the knowledge of adobe maintenance.', '[{"index": "1", "level": 1, "title": "Location", "content": ""}, {"index": "2", "level": 1, "title": "History", "content": "History[edit] According to a legend, in 1421 an Islamic trader named Ayuba had a dream while staying here, near a \"mystic stone\", instructing him to build a mosque. Strangely, when he awoke, he found that the foundations were already in place and he proceeded to construct the mosque until it was completed.&#91;1&#93;&#91;2&#93; There is a belief that he left instructions that he should be buried close to the mosque, when he dies, and after three days, the baobab which would shoot up on his grave was to be preserved for generations. The baobab tree next to the mosque today is reputed to mark the site of Ayuba''s grave.&#91;1&#93; The townsfolk of Larabanga supposedly depend on the leaves and stem of this baobab tree for healing of ailments. Unlike mosques situated in urban settings in West Africa, the Larabanga Mosque is comparatively small. Rural mosques, like Larabanga''s, were usually conceived by a single marabout and loosely based on styles seen elsewhere such as in the Great Mosque of Djenné.&#91;3&#93; In order to achieve a physical resemblance to the architecture used elsewhere, the Larabanga Mosque had to incorporate large buttresses in order to compensate for the poorer quality of building materials.&#91;3&#93; Larabanga is one of eight ancient and highly revered mosques in Ghana and is also the oldest. It is a place of pilgrimage and is considered the Mecca of West Africa.&#91;1&#93; In the 1970s, a mixture of sand and cement was applied to the external faces of the mosque with the intention of protecting the mosque from wind and rain damage. However, this treatment resulted in substantial damage to the building as moisture became trapped in the walls built of adobe and started a deterioration process of the structure, with termites infesting the wooden supports under humid conditions.&#91;4&#93; This resulted in part of the mosque collapsing and during the repair work it caused some distortions of the structural elements and the exterior of the mosque.&#91;4&#93; Owing to the effect of prevailing winds and rains on the walls, the mosque has needed several renovations and restoration work which over the years have altered some of its exterior designs.&#91;5&#93;&#91;6&#93; In September 2002, a severe storm destroyed the mihrab and the minaret. As a result, the World Monuments Fund (WMF) placed the mosque on the 2002 World Monuments Watch,&#91;4&#93; also considering the damage sustained after the inappropriate restoration in the 1970s.&#91;4&#93; The Ghana Museums and Monuments Board decided to restore the mosque and sought advice from CRAterre, an architectural firm based in Grenoble, France which has expertise in building earthen structures.&#91;4&#93; The renovation work was supported by a WMF, with a grant fund of US$50,000 from American Express.&#91;7&#93; The local community also provided support.&#91;4&#93; The conservation process involved removal of the earlier cement plaster from the surfaces of the mosque, the wooden structural components were replaced, the minaret and the mihrab were reconstructed, the portal was redone, and the interior and exterior surfaces were plastered in the traditional way.&#91;4&#93;&#91;7&#93; The renovation resulted in reassessing the state of conservation of the site, involving a team of local artisans and labourers. It helped to restore the monument with special emphasis on reviving the knowledge of Adobe maintenance.&#91;4&#93; ^ a b c .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output "}, {"index": "3", "level": 1, "title": "Features", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 2, "title": "Bibliography", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Larabanga_Mosque", "text": "Wikipedia"}]'::jsonb, '2026-01-13 15:15:43.777542+11:00', '2026-01-13 00:25:13.218501+11:00');
