INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62600, '高昌故城', 'en', '高昌故城 是公元前1世纪到公元14世纪吐鲁番盆地的第一大中心城镇，也是新疆留存最大的故城遗址。城遗址位于新疆维吾尔自治区吐鲁番市高昌區三堡乡，即火焰山南麓木头沟河三角洲。
