INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62360, '小油坑', 'en', '小油坑是位於臺灣北部陽明山國家公園內的一處火山噴氣孔，位於七星山西北麓，海拔約805公尺，亦為七星山登山口之一。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62361, '爨底下村', 'en', 'Cuandixia is a historic village dating from the Ming dynasty located in Zhaitang, Mentougou District in Beijing, China. It is a popular tourist attraction known for its well preserved courtyard homes.', '[{"index": "1", "level": 1, "title": "Name", "content": ""}, {"index": "2", "level": 1, "title": "Architecture", "content": ""}, {"index": "3", "level": 1, "title": "Location", "content": ""}, {"index": "4", "level": 1, "title": "History", "content": "History[edit] Cuandixia was founded during the Ming dynasty (1368–1644) by members of the Han clan who moved from Shanxi Province.&#91;1&#93;&#91;2&#93; Towards the end of the Qing Dynasty, Cuandixia prospered from trading in coal, fur, and grain.&#91;2&#93; ^ Cite error: The named reference Visit was invoked but never defined (see the help page). ^ a b The Ancient Village of Chuandixia in Beijing, China.org.cn. Accessed 2 August 2023."}, {"index": "5", "level": 1, "title": "Attractions", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Cuandixia", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:33:13.777165+11:00', '2026-01-13 00:25:12.656968+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62365, '天封塔', 'en', '天封塔是中国浙江省宁波市的一座佛塔，位于海曙区大沙泥街，始建于武周，是宁波旧城的标志性建筑物。目前建筑重修于1984年，1961年5月公布为宁波市文物保护单位。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65674, 'Сидорівський_замок', 'en', NULL, NULL, '[{"ref": "ref2", "url": null, "text": "Historical records and archives"}, {"ref": "ref3", "url": "https://whc.unesco.org", "text": "UNESCO World Heritage documentation"}, {"ref": "ref1", "url": "https://example.com/tourism", "text": "Official tourism website"}]'::jsonb, '2026-01-14 21:11:02.746391+11:00', '2026-01-13 00:25:12.896116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62368, 'Тавдинские_пещеры', 'en', 'Тавдинские или Талдинские пещеры — массив из большого числа пещер карстового происхождения в Алтайском районе Алтайского края, на левом берегу Катуни. Своё название пещеры получили от названия деревни Тавда, ранее располагавшейся неподалёку от этих мест. Протяжённость скал с пещерами составляет около 5 км. Входы в пещеры находятся в отвесных скалах и утесах, большая часть из которых легко доступна. В связи с популярностью и большой посещаемостью этого места туристами, некоторые входы даже оборудованы деревянными ступенями, в самые посещаемые туристами пещеры проведён свет. Многие пещеры имеют по несколько входов и соединяются друг с другом, образуя большую взаимосвязанную систему. Вход в легкодоступные пещеры оборудован турникетами и является платным.', '[{"index": "1", "level": 1, "title": "Большая Тавдинская пещера", "content": "Большая Тавдинская пещера[править | править код] .mw-parser-output .ambox{align-items:center;border:1px solid var(--border-color-base,#a2a9b1);border-left:10px solid #36c;background:var(--background-color-neutral-subtle,#f8f9fa);box-sizing:border-box;display:flex;margin:0 10%}html body.mediawiki.skin-minerva .mw-parser-output .ambox{border-width:0 0 0 4px}.mw-parser-output .ambox+link+.ambox,.mw-parser-output .ambox+link+style+.ambox,.mw-parser-output .ambox+link+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+style+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+link+.ambox{margin-top:-1px}html body.mediawiki .mw-parser-output .ambox.mbox-small-left{margin:4px 1em 4px 0;overflow:hidden;width:238px;border-collapse:collapse;font-size:88%;line-height:1.25em}.mw-parser-output .ambox-speedy{border-left:10px solid var(--border-color-error,#b32424);background-color:var(--background-color-error-subtle,#fee7e6)}.mw-parser-output .ambox-delete{border-left:10px solid var(--border-color-error,#b32424)}.mw-parser-output .ambox-content{border-left:10px solid #f28500}.mw-parser-output .ambox-style{border-left:10px solid var(--color-warning,#edab00)}.mw-parser-output .ambox-good{border-left:10px solid #66cc44}.mw-parser-output .ambox-discussion{border-left:10px solid #339966}.mw-parser-output .ambox-merge{border-left:10px solid #9932cc}.mw-parser-output .ambox-move{border-left:10px solid #9932cc}.mw-parser-output .ambox-protection{border-left:10px solid #a2a9b1}.mw-parser-output .ambox .mbox-text{border:none;padding:0.25em 0.5em;width:100%}.mw-parser-output .ambox .mbox-image{border:none;padding:2px 0 2px 0.5em;text-align:center}.mw-parser-output .ambox .mbox-imageright{border:none;padding:2px 0.5em 2px 0;text-align:center}.mw-parser-output .ambox .mbox-empty-cell{border:none;padding:0;width:1px}.mw-parser-output .ambox .mbox-image-div{width:52px}.mw-parser-output .ambox .mbox-textsmall-div{font-size:90%}html.client-js body.skin-minerva .mw-parser-output .mbox-text-span{margin-left:23px!important}@media(max-width:1366px){.mw-parser-output .ambox{margin-left:6%;margin-right:6%}}@media(max-width:719px){.mw-parser-output .ambox{margin-left:0;margin-right:0}}В разделе не хватает ссылок на источники (см. рекомендации по поиску). Информация должна быть проверяема, иначе она может быть удалена. Вы можете отредактировать статью, добавив ссылки на авторитетные источники в виде сносок. (7 марта 2025) Пещера под названием «Большая Тавдинская» (другие названия этой пещеры&#160;— «Девичьи слёзы», «Тавдинская-1»)&#160;— это наиболее посещаемая туристами пещера в Тавдинском массиве. Нижние входы в неё находятся в 70-80&#160;м от дороги и видны в просветы между деревьями. Главная галерея довольно просторна и постепенно поднимается. Перепад от самого нижнего входа к высшему составляет 23 метра. На последнем 40-метровом участке, перед самым высшим входом, галерея, возвышаясь, закручивается спиралью, перекрывая свою нижнюю часть и образуя уступ. Во время археологических раскопок в пещере были обнаружены предметы гончарного производства, рыболовные принадлежности. Найдены также предметы, относящиеся к эпохе бронзы."}, {"index": "2", "level": 1, "title": "Тавдинская карстовая арка", "content": "Тавдинская карстовая арка[править | править код] .mw-parser-output .ambox{align-items:center;border:1px solid var(--border-color-base,#a2a9b1);border-left:10px solid #36c;background:var(--background-color-neutral-subtle,#f8f9fa);box-sizing:border-box;display:flex;margin:0 10%}html body.mediawiki.skin-minerva .mw-parser-output .ambox{border-width:0 0 0 4px}.mw-parser-output .ambox+link+.ambox,.mw-parser-output .ambox+link+style+.ambox,.mw-parser-output .ambox+link+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+style+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+link+.ambox{margin-top:-1px}html body.mediawiki .mw-parser-output .ambox.mbox-small-left{margin:4px 1em 4px 0;overflow:hidden;width:238px;border-collapse:collapse;font-size:88%;line-height:1.25em}.mw-parser-output .ambox-speedy{border-left:10px solid var(--border-color-error,#b32424);background-color:var(--background-color-error-subtle,#fee7e6)}.mw-parser-output .ambox-delete{border-left:10px solid var(--border-color-error,#b32424)}.mw-parser-output .ambox-content{border-left:10px solid #f28500}.mw-parser-output .ambox-style{border-left:10px solid var(--color-warning,#edab00)}.mw-parser-output .ambox-good{border-left:10px solid #66cc44}.mw-parser-output .ambox-discussion{border-left:10px solid #339966}.mw-parser-output .ambox-merge{border-left:10px solid #9932cc}.mw-parser-output .ambox-move{border-left:10px solid #9932cc}.mw-parser-output .ambox-protection{border-left:10px solid #a2a9b1}.mw-parser-output .ambox .mbox-text{border:none;padding:0.25em 0.5em;width:100%}.mw-parser-output .ambox .mbox-image{border:none;padding:2px 0 2px 0.5em;text-align:center}.mw-parser-output .ambox .mbox-imageright{border:none;padding:2px 0.5em 2px 0;text-align:center}.mw-parser-output .ambox .mbox-empty-cell{border:none;padding:0;width:1px}.mw-parser-output .ambox .mbox-image-div{width:52px}.mw-parser-output .ambox .mbox-textsmall-div{font-size:90%}html.client-js body.skin-minerva .mw-parser-output .mbox-text-span{margin-left:23px!important}@media(max-width:1366px){.mw-parser-output .ambox{margin-left:6%;margin-right:6%}}@media(max-width:719px){.mw-parser-output .ambox{margin-left:0;margin-right:0}}В разделе не хватает ссылок на источники (см. рекомендации по поиску). Информация должна быть проверяема, иначе она может быть удалена. Вы можете отредактировать статью, добавив ссылки на авторитетные источники в виде сносок. (7 марта 2025) Тавдинская карстовая арка Уникальна Тавдинская карстовая арка. Она представляет редкую форму&#160;— остаток свода карстового туннеля или пещеры, имевший первоначально вид широкого пролёта&#160;— моста, а позднее&#160;— арки. Тавдинская арка находится на высоте около 80 метров над уровнем воды реки Катунь. Ширина сквозного отверстия арки колеблется от 3 до 13 метров, высота&#160;— от 3 до 5 метров. Свод арки, толщиной 5 метров, покрыт редкой травяной растительностью и соснами. С 1996&#160;г. Тавдинская карстовая арка имеет статус памятника природы."}, {"index": "3", "level": 1, "title": "Примечания", "content": "Примечания[править | править код] Ошибка в сносках?:&#x20;Тег &lt;ref&gt; с именем «ООПТ», определённый в &lt;references&gt;, не используется в предшествующем тексте."}, {"index": "4", "level": 1, "title": "Ссылки", "content": "Ссылки[править | править код] Сайт «Наш Алтай»&#160;— Тавдинские пещеры Информационный портал ТК «Бирюзовая Катунь»&#160;— Тавдинские пещеры"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%A2%D0%B0%D0%B2%D0%B4%D0%B8%D0%BD%D1%81%D0%BA%D0%B8%D0%B5_%D0%BF%D0%B5%D1%89%D0%B5%D1%80%D1%8B", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:34:23.394773+11:00', '2026-01-13 00:25:12.656968+11:00');
