INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62389, '十分瀑布', 'en', 'Shifen Waterfall is a scenic waterfall located in Pingxi District, New Taipei City, Taiwan, on the upper reaches of the Keelung River. The falls'' total height is 20 metres (66 ft) and 40 metres (130 ft) in width, making it the broadest waterfall in Taiwan. It is a cascade waterfall in which the water flows in one direction and the rock is sloped in the opposite.', '[{"index": "1", "level": 1, "title": "Name", "content": ""}, {"index": "2", "level": 1, "title": "Geology", "content": ""}, {"index": "3", "level": 1, "title": "Access", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Shifen_Waterfall", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:34:23.394773+11:00', '2026-01-13 00:25:12.656968+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62394, 'Siddha_Cave', 'en', 'Siddha Cave or Siddha Gufa is a cave located in Bimalnagar, Tanahun District, Nepal. It has an inner area of around 0.5 kilometers and can accommodate around 2,500 people.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of caves in Nepal"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} Siddha Cave Nepal binamra .mw-parser-output .asbox{position:relative;overflow:hidden}.mw-parser-output .asbox table{background:transparent}.mw-parser-output .asbox p{margin:0}.mw-parser-output .asbox p+p{margin-top:0.25em}.mw-parser-output .asbox-body{font-style:italic}.mw-parser-output .asbox-note{font-size:smaller}.