INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62397, 'मुक्तिनाथ', 'en', 'Muktinath is an ancient Vishnu temple located in Mustang, Nepal. The temple of Muktinath, known as ''the lord of liberation'', is sacred to both Hindus and Buddhists whom they worship as an abode of Hindu deity Vishnu and Buddhist deity Avalokiteśvara respectively. Located in the Muktinath valley at the foot of the Thorong La mountain pass, it is one of the world''s highest temples at an altitude of 3,800 meters. The temple is given a status of one of the 108 Divya Desams of Sri Vaishnavism as well as one of the eight most sacred shrines in that tradition, known as the Svayam Vyakta Ksetras or Sthalas. It is also one of the 51 Shakta pithas, associated with the head of goddess Sati. The temple complex is known as Mukti Kshetra, which literally means "the place of liberation (moksha)" and is one of the Char Dham in Nepal.', '[{"index": "1", "level": 1, "title": "Legend", "content": ""}, {"index": "2", "level": 1, "title": "Architecture", "content": ""}, {"index": "3", "level": 1, "title": "Religious significance", "content": ""}, {"index": "4", "level": 2, "title": "Hinduism", "content": ""}, {"index": "5", "level": 3, "title": "Vaishnavism", "content": ""}, {"index": "6", "level": 3, "title": "Shaktism", "content": ""}, {"index": "7", "level": 2, "title": "Buddhism", "content": ""}, {"index": "8", "level": 1, "title": "Gallery", "content": ""}, {"index": "9", "level": 1, "title": "See also", "content": ""}, {"index": "10", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Muktinath", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:35:45.617699+11:00', '2026-01-13 00:25:12.656968+11:00');
