INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62473, 'Ильмовая_падь', 'en', 'И́льмовая падь — комплекс хуннских могильников II—I веков до н. э., расположенный в Кяхтинском районе Республики Бурятия.', '[{"index": "1", "level": 1, "title": "Географическое положение", "content": ""}, {"index": "2", "level": 1, "title": "Могильники комплекса «Ильмовая падь»", "content": ""}, {"index": "3", "level": 2, "title": "Ильмовая падь I", "content": ""}, {"index": "4", "level": 2, "title": "Ильмовая падь II (Хана-Шулуун)", "content": ""}, {"index": "5", "level": 2, "title": "Ильмовая Падь III (Капчеранка)", "content": ""}, {"index": "6", "level": 1, "title": "Примечания", "content": ""}, {"index": "7", "level": 1, "title": "Литература", "content": ""}, {"index": "8", "level": 1, "title": "См. также", "content": ""}, {"index": "9", "level": 1, "title": "Ссылки", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%98%D0%BB%D1%8C%D0%BC%D0%BE%D0%B2%D0%B0%D1%8F_%D0%BF%D0%B0%D0%B4%D1%8C", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:39:31.586747+11:00', '2026-01-13 00:25:12.682722+11:00');
