INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62485, '隘門', 'en', '隘門，臺灣清領時期傳入台灣，為早期相當普遍設置於村落或城市街道巷弄中的防禦建築。形式有磚石造的牆門及單開間的門樓，平日入夜後即行關閉，阻止盜賊進犯，以確保居民的安全，保護同鄉住所
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65691, 'Daugailių_II_piliakalnis', 'en', NULL, NULL, '[{"ref": "ref2", "url": null, "text": "Historical records and archives"}, {"ref": "ref3", "url": "https://whc.unesco.org", "text": "UNESCO World Heritage documentation"}]'::jsonb, '2026-01-14 21:11:02.746391+11:00', '2026-01-13 00:25:12.896116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62486, '半邊井', 'en', '半邊井位於台灣彰化縣鹿港鎮，「三槐挺秀」的王家宅院內。特色是井的一邊在住家圍牆內，另一邊在牆外。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62491, '马蹄寺石窟群', 'en', '马蹄寺石窟群，位于中华人民共和国甘肃省张掖市肃南裕固族自治县境内，是包括马蹄北寺、马蹄南寺、千佛洞、金塔寺、上观音洞、中观音洞、下观音洞等7处洞窟群在内的石窟群。该石窟群始建于五胡十六国时期，最晚持续至清朝年间。由于年久失修，部分石窟已严重损毁，大量造像缺失。1996年，马蹄寺石窟群被列为全国重点文物保护单位。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65692, 'Kartupėnų_piliakalnis', 'en', NULL, NULL, '[{"ref": "ref2", "url": null, "text": "Historical records and archives"}, {"ref": "ref1", "url": "https://example.com/tourism", "text": "Official tourism website"}]'::jsonb, '2026-01-14 21:11:02.746391+11:00', '2026-01-13 00:25:12.896116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62503, '遇林亭窑址', 'en', '遇林亭窑址位于中国福建省武夷山市武夷山风景名胜区西北部燕子窠村和白岩村，面积近6万平方米，2006年被列为第六批全国重点文物保护单位，归入建窑遗址。
