INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62504, '歪腰郵筒', 'en', '歪腰郵筒，是臺灣臺北市中山區兩個遭到颱風蘇迪勒侵襲而掉落的招牌砸歪的郵箱，由於其造型可愛而獲得民眾的高度關注。之後中華郵政響應民眾的要求而同意考慮將歪斜的郵箱予以保留，並且進一步發展成為臺北市另類景點。在考量週遭民眾安全和交通狀況，決定將歪腰郵筒遷移至臺北郵局。但是計畫遷移的舉動則受到許多民間人士反對，前中華民國文化部部長龍應台更批評中華郵政不懂其價值。之後中華郵政順應社會大眾意見而暫緩遷移工作，並計畫與專家學者共同討論。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62506, '개선문', 'en', 'A triumphal arch is a free-standing monumental structure in the shape of an archway with one or more arched passageways, often designed to span a road, and usually standing alone, unconnected to other buildings. In its simplest form, a triumphal arch consists of two massive piers connected by an arch, typically crowned with a flat entablature or attic on which a statue might be mounted or which bears commemorative inscriptions. The main structure is often decorated with carvings, sculpted reliefs, and dedications. More elaborate triumphal arches may have multiple archways, or in a tetrapylon, passages leading in four directions.', '[{"index": "1", "level": 1, "title": "Origins and development", "content": ""}, {"index": "2", "level": 2, "title": "Roman triumphal arches", "content": ""}, {"index": "3", "level": 2, "title": "Post-Roman triumphal arches", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "Notes", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Triumphal_arch", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:41:57.525892+11:00', '2026-01-13 00:25:12.682722+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62524, '天津之眼', 'en', 'Tianjin Eye, the official name The Tientsin Eye, is a 120-meter (394 ft)-tall giant ferris wheel built above the Yongle Bridge, over the Hai River in Tianjin, China.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,.mw-parser-output .hlist dl ol,.mw-parser-output .hlis