INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62526, 'Royal_Tombs_of_the_Joseon_Dynasty', 'en', 'Royal Tombs of the Joseon Dynasty (Korean: 조선왕릉) is a UNESCO World Heritage Site registered in 2009 that includes 40 tombs of members of the House of Yi, which ruled Korea between 1392 and 1910. These tombs are scattered over 18 locations across the Korean Peninsula. They were built to honor and respect the ancestors and their achievements and assert their royal authority. Two other Joseon tombs, located in Kaesong, North Korea, were proposed but not submitted.', '[{"index": "1", "level": 1, "title": "Structure of the tombs", "content": ""}, {"index": "2", "level": 2, "title": "Area around Jeongjagak", "content": ""}, {"index": "3", "level": 2, "title": "Area just past the gate", "content": ""}, {"index": "4", "level": 2, "title": "The sacred ground of the grave mounds", "content": ""}, {"index": "5", "level": 2, "title": "Other structures", "content": ""}, {"index": "6", "level": 1, "title": "Tombs", "content": ""}, {"index": "7", "level": 2, "title": "Donggureung (동구릉)", "content": ""}, {"index": "8", "level": 2, "title": "Gwangneung (광릉)", "content": ""}, {"index": "9", "level": 2, "title": "Heonilleung (헌인릉)", "content": ""}, {"index": "10", "level": 2, "title": "Hongyureung (홍유릉)", "content": ""}, {"index": "11", "level": 2, "title": "Jangneung (Gimpo) (김포 장릉)", "content": ""}, {"index": "12", "level": 2, "title": "Jangneung (Paju) (파주 장릉)", "content": ""}, {"index": "13", "level": 2, "title": "Jangneung (Yeongwol) (영월 장릉)", "content": ""}, {"index": "14", "level": 2, "title": "Jeongneung (정릉)", "content": ""}, {"index": "15", "level": 2, "title": "Olleung (온릉)", "content": ""}, {"index": "16", "level": 2, "title": "Paju Samneung Cluster (파주 삼릉)", "content": ""}, {"index": "17", "level": 2, "title": "Sareung (사릉)", "content": ""}, {"index": "18", "level": 2, "title": "Seonjeongneung (선정릉)", "content": ""}, {"index": "19", "level": 2, "title": "Seooreung Cluster (서오릉)", "content": ""}, {"index": "20", "level": 2, "title": "Seosamneung Cluster (서삼릉)", "content": ""}, {"index": "21", "level": 2, "title": "Taegangneung (태강릉)", "content": ""}, {"index": "22", "level": 2, "title": "Uireung (의릉)", "content": ""}, {"index": "23", "level": 2, "title": "Yeongneung (영릉)", "content": ""}, {"index": "24", "level": 2, "title": "Yunggeolleung (융건릉)", "content": ""}, {"index": "25", "level": 1, "title": "See also", "content": ""}, {"index": "26", "level": 1, "title": "References", "content": ""}, {"index": "27", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Royal_Tombs_of_the_Joseon_Dynasty", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:42:53.398508+11:00', '2026-01-13 00:25:12.694154+11:00');
