INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62586, '开元寺泰佛殿', 'en', '开元寺泰佛殿 是位于广东省潮州市湘桥区韩江大桥东侧的泰式佛教建筑，由潮州籍泰国华人谢慧如捐资而建，于1992年2月14日落成。建筑风格模仿自泰国云石寺，殿内供奉素可泰王朝风格释迦牟尼佛（成功佛）像。
