INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62610, '百狮坊', 'en', '百狮坊，位于山东省菏泽市单县牌坊街，是中华人民共和国山东省文物保护单位之一。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62612, '溪州铜柱', 'en', '溪州铜柱位于湖南省湘西土家族苗族自治州永顺县，建于五代后晋天福五年（940年），柱面上刻有楚王馬希範与土司彭仕愁停战盟誓的条约，是研究中国古代民族关系的重要实物资料，“是渝湘鄂黔毗邻地区少数民族土司制度逐步形成的里程碑”。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65712, 'Spitrėnų_piliakalnis', 'en', NULL, NULL, '[{"ref": "ref1", "url": "https://example.com/tourism", "text": "Official tourism website"}, {"ref": "ref2", "url": null, "text": "Historical records and archives"}, {"ref": "ref3", "url": "https://whc.unesco.org", "text": "UNESCO World Heritage documentation"}]'::jsonb, '2026-01-14 21:11:02.746391+11:00', '2026-01-13 00:25:12.896116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65713, 'Jaurelio_piliakalnis', 'en', NULL, NULL, '[{"ref": "ref2", "url": null, "text": "Historical records and archives"}, {"ref": "ref1", "url": "https://example.com/tourism", "text": "Official tourism website"}]'::jsonb, '2026-01-14 21:11:02.746391+11:00', '2026-01-13 00:25:12.896116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62613, '旭丘山', 'en', '旭丘山，又稱旭岡、旭丘，是位於台灣基隆市中正區的山丘，位在大沙灣的久留米嶺後方。日治時代以「旭岡觀日」名列台灣八景之一，當時規劃為「平和公園」，也稱作「旭丘公園」，山下有孤拔濱 以及法國公墓。現今山頂區域設有正濱國中、三軍總醫院基隆院區與軍方營區。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63433, 'Oldendorfer_Totenstatt', 'en', 'The Oldendorfer Totenstatt is a group of six burial mounds and megalith sites in Oldendorf north of Amelinghausen in the valley of the River Luhe in Lüneburg district in the German state of Lower Saxony. It consists of dolmens and tumuli.', '[{"index": "1", "level": 1, "title": "Sites 1, 3 and 4", "content": "Sites 1, 3 and 4[edit] Model of Site III Site 1 is a 45&#160;m-long (148&#160;ft) dolmen, most of which has been destroyed. Site 3 is the remains of the earth embankment, still 43 m long. Most of its external stones are still there, either in situ or overturned. The chamber must have been located in the section that no longer exists. Site 4 is an 80&#160;m-long (260&#160;ft) dolmen. It originally had about 100 external stones, 14 of which are still in situ, the remainder were put back during its restoration (some with dry stone walling filling the gaps). The passage grave consisted of a roughly 8&#160;m-long (26&#160;ft) chamber with 12 upright supporting stones and a pair of passageway stones. The original five capstones of the chamber as well as the capstone for the passage are missing. The location of the chamber in the dolmen is right at the end, likewise the side entrance to the chamber is offset well to the end, so that the site is classified as one of the so-called Holsteiner Kammer (\"Holstein Chamber\") type."}, {"index": "2", "level": 1, "title": "Sites 2, 5 and 6", "content": "Sites 2, 5 and 6[edit] Site 2 is a tumulus about 20 m in diameter in the centre of which the remains (the uprights and the joist (Schwellenstein)) of a passage grave are located. Sites 5 and 6 are Bronze Age tumuli."}, {"index": "3", "level": 1, "title": "Finds", "content": "Finds[edit] Inside the chamber of site 2 and 4 were found relicts of Funnelbeaker, Globular amphora, and Corded Ware cultures at different levels."}, {"index": "4", "level": 1, "title": "Literature", "content": "Literature[edit] Laux F.: Die Steingräber von Oldendorf an der Luhe In: Körner G. (ed.) Dokumentation zur Archäologie Niedersachsens in Denkmalpflege und Forschung, 1975"}, {"index": "5", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Oldendorfer Totenstatt. The Oldendorf Totenstatt at www.oldendorf-luhe.de .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefault,.mw-parser-output .geo-multi-punct,.mw-parser-output .geo-inline-hidden{display:none}.mw-parser-output .longitude,.mw-parser-output .latitude{white-space:nowrap}53°8′47.0364″N 10°13′9.91″E&#xfeff; / &#xfeff;53.146399000°N 10.2194194°E&#xfeff; / 53.146399000; 10.2194194"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Oldendorfer_Totenstatt", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:19:49.451326+11:00', '2026-01-13 00:25:12.753773+11:00');
