INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63442, 'York_Dungeon', 'en', 'York Dungeon is a tourist attraction in York, England. York Dungeon depicts history of the dungeon using actor led shows, special effects and displays of models and objects.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] York Dungeon was opened in 1986 at 12 Clifford Street, York, England. It was the second Dungeon attraction created, the first being the London Dungeon in 1975. Like the London Dungeon, it was designed as a live action interactive horror show loosely based on factual events throughout history. As part of a £3.5 million investment across both Dungeons, a new feature opened in 1997 showcasing tales of the ''Lost Roman legion'' in York. Further additions and expansions continued with a Plague section encounter in a Plague doctor''s surgery. 2002 saw the opening of ''Gorvik'' (the name a pun on ''Jorvik'', the kings name for York), which detailed the Viking history of the City and brutal attacks from Viking forces. Other attractions included the Torture Chamber, The Gunpowder Plot, Dick Turpin, and the Courtroom. 2003 saw the arrival of the Witch Trials that detailed the witch trials in York through the use of a detailed set and animatronics. This area subsequently became the ''Ghosts of York'' show in 2007. Like London, over time, the Dungeon evolved from a museum to an actor led experience. The Dungeon remains the smallest of the dungeons chain. The Dungeon has been subject to severe flooding numerous times, due to its close proximity to the River Ouse. This has occurred in 2001, 2004 and twice in 2012, leading to a complete refurbishment. Many exhibits were totally refurbished, particularly the torture chamber which as a result was drastically reduced in size, had most of the original exhibits removed, and script rewrites to focus on actor-guest interaction instead. As with entire Dungeons brand, the York Dungeon received a rebranding in 2013 to coincide with the relocation of the London Dungeon. This included a new set of scripts and additional comedy elements to shows."}, {"index": "2", "level": 1, "title": "Exhibits and shows", "content": ""}, {"index": "3", "level": 1, "title": "Criticism", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/York_Dungeon", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:19:49.451326+11:00', '2026-01-13 00:25:12.753773+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63445, 'Hinteri_Egg', 'en', 'The Hinteri Egg is a mountain of the Jura, located south of Reigoldswil in the Swiss canton of Basel-Landschaft, close to the border with the canton of Solothurn.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] Hinteri Egg on Hikr .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-pa