INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63640, 'Равелинные_ворота', 'en', 'Равелинные ворота — городские ворота, одни из четырёх сохранившихся крепостных ворот Аннинских укреплений города Выборга. Возведённое в середине XVIII века в стиле русского классицизма в качестве части оборонительного комплекса Выборгской крепости сооружение включено в перечень памятников архитектуры.', '[{"index": "1", "level": 1, "title": "История", "content": "История[править | править код] В течение 1730-х — 1750-х годов для защиты Выборга с северо-западной стороны по проекту генерала А. С. Кулона была возведена крепость Короно-Санкт-Анны, охватившая полукольцом побережье напротив Выборгского замка. Крепость, напоминавшая в плане корону, включала в себя три «зубца» — равелина треугольной формы перед крепостным рвом между бастионами. Через второй равелин была проложена Фридрихсгамская дорога, по которой осуществлялось всё движение из города на запад. Дорога начиналась от Фридрихсгамских ворот в куртине между вторым и третьим бастионами, затем по насыпи через ров пешеходы и повозки попадали на равелин, прорезанный аналогичными воротами, от которых через ров на гласис перекинут деревянный мост. Таким образом, до второй половины XIX века путь в город был надёжно прикрыт оборонительными сооружениями с двойными воротами: внутренними Фридрихсгамскими и внешними — Равелинными&#91;1&#93;. После того как в 1865 году через устаревшие укрепления была проложена широкая шоссейная дорога (теперь это Островная улица), старая дорога через ворота стала пешеходной (нынешнее название — Петровская улица). Двойные ворота до сих пор используются по прямому назначению, в отличие от Вторых Фридрихсгамских ворот (между третьим и четвёртым бастионами) и сортии во втором бастионе. Арочный проезд Равелинных ворот, замощённый брусчаткой, с обеих сторон оформлен в стиле русского классицизма в виде портика с пилястрами и антаблементом. На братской могиле на гласисе перед воротами установлен обелиск — памятник русским воинам, погибшим при осаде Выборга в 1710 году. Равелинные ворота в 1890-е гг. Дорога через равелин со стороны Фридрихсгамских ворот ↑ Знакомьтесь, Выборг"}, {"index": "2", "level": 1, "title": "Примечания", "content": "Примечания[править | править код]"}, {"index": "3", "level": 1, "title": "Литература", "content": "Литература[править | править код] .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"«\"\"»\"\"„\"\"“\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free a::after,.mw-parser-output .id-lock-limited a::after,.mw-parser-output .id-lock-registration a::after,.mw-parser-output .id-lock-subscription a::after,.mw-parser-output .cs1-ws-icon a::after{content:\"\";width:1.1em;height:1.1em;display:inline-block;vertical-align:middle;background-position:center;background-repeat:no-repeat;background-size:contain}.mw-parser-output .id-lock-free.id-lock-free a::after{background-image:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")}.mw-parser-output .id-lock-limited.id-lock-limited a::after,.mw-parser-output .id-lock-registration.id-lock-registration a::after{background-image:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")}.mw-parser-output .id-lock-subscription.id-lock-subscription a::after{background-image:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")}.mw-parser-output .cs1-ws-icon a::after{background-image:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.