INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63642, 'Col_du_Soulor', 'en', 'Col du Soulor is a mountain pass in the Pyrenees in France, linking Argelès-Gazost with Arthez-d''Asson. It connects the Ouzom and Arens valleys. A road leaves the pass to the west to reach the higher Col d''Aubisque.', '[{"index": "1", "level": 1, "title": "Details of the climbs", "content": ""}, {"index": "2", "level": 1, "title": "Tour de France", "content": ""}, {"index": "3", "level": 2, "title": "Passages in the Tour de France (since 1947)", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Col_du_Soulor", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:25:50.430589+11:00', '2026-01-13 00:25:12.766999+11:00');
