INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63676, 'Buckden_Pike', 'en', 'Buckden Pike is a fell at the head of Wharfedale, a valley in the Yorkshire Dales, that stands above the village of Buckden, England. At 702 metres (2,303 ft), it narrowly misses out on being the highest peak in the area, the title instead going to nearby Great Whernside. The summit is marked by a trig point.', '[{"index": "1", "level": 1, "title": "Routes of ascent", "content": ""}, {"index": "2", "level": 1, "title": "Buckden Pike Memorial Cross", "content": ""}, {"index": "3", "level": 1, "title": "The view", "content": ""}, {"index": "4", "level": 1, "title": "Buckden Pike Fell Race", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Buckden_Pike", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:27:55.076619+11:00', '2026-01-13 00:25:12.766999+11:00');
