INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63722, 'Låtefossen', 'en', 'Låtefossen or Låtefoss is a waterfall located in Ullensvang Municipality in Vestland County, Norway. The 165-metre (541 ft) tall waterfall is unique and thus it is a well-known tourist attraction in the area. It is special in that it consists of two separate streams flowing down from the lake Lotevatnet, and as they fall, they join in the middle of the waterfall, just before going under the Norwegian National Road 13 built in 1867–69, making for a spectacular view as one drives over the old, stone, six-arched bridge.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] View of the bridge Section from Låtefossen View of the falls View of the visitors'' center"}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] List of waterfalls §&#160;Norway @media screen{html.skin-theme-clientpref-night .mw-parser-output .sister-inline-image img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sister-inline-image img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}} Media related to Låtefossen at Wikimedia Commons"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=low