INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62620, '新竹市眷村博物館', 'en', 'The Hsinchu Museum of Military Dependents Village is a museum about the military dependents'' village in North District, Hsinchu City, Taiwan.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The museum was established by the Cultural Affairs Bureau of Hsinchu City Government on 28 December 2002.&#91;1&#93; After the civil war between the Kuomintang (also known as the Chinese Nationalist Party) and the Communist Party in 1949, the Nationalist Government retreated to Taiwan. The military, civilian, and government personnel of all provinces were forced to move to settle in Taiwan. According to statistics, from 1945 to 1950, nearly 2 million soldiers and civilians from all parts of mainland China moved to Taiwan. In order to solve the housing problem caused by the population explosion, the Nationalist Government began to build houses or arrange dormitories, and the new residents were grouped in a certain range with the military service, occupation, and characteristics, which is now known as the “Military Dependents Village”. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Military Dependants Village Museum Of Hsinchu City - China culture\". Arts.cultural-china.com. Archived from the original on 2014-03-31. Retrieved 2014-03-02."}, {"index": "2", "level": 1, "title": "Architecture", "content": ""}, {"index": "3", "level": 1, "title": "Exhibitions", "content": ""}, {"index": "4", "level": 1, "title": "Transportation", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hsinchu_Museum_of_Military_Dependents_Village", "text": "Wikipedia"}]'::jsonb