INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63861, 'Expedition_GeForce', 'en', 'Expedition GeForce is a steel roller coaster located at Holiday Park in Haßloch, Germany. It is one of the largest roller coasters in Europe and has an 82 degree first drop. The trains travel up to 120 kilometres per hour (75 mph) through a course 1.2 kilometres (0.75 mi) long with seven periods of weightlessness. At its highest, the ride reaches 53 metres (174 ft) above ground.', '[{"index": "1", "level": 1, "title": "Ride information", "content": ""}, {"index": "2", "level": 1, "title": "Ride layout", "content": ""}, {"index": "3", "level": 1, "title": "Vehicles", "content": ""}, {"index": "4", "level": 1, "title": "Incident", "content": ""}, {"index": "5", "level": 1, "title": "Rankings", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Expedition_GeForce", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:34:11.022829+11:00', '2026-01-13 00:25:12.779272+11:00');
