INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63878, 'Great_Shunner_Fell', 'en', 'Great Shunner Fell is the third-highest mountain in the Yorkshire Dales, North Yorkshire, England, and the highest point in Wensleydale; at 716 metres above sea level. In clear weather the summit affords views of Wensleydale to the south, Ribblesdale to the southwest and Swaledale to the north, as well as views into Cumbria and County Durham beyond the A66.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] The last few yards to the summit The summit plateau of Great Shunner Fell viewed from the south"}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] List of peaks in the Yorkshire Dales"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-l