INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63904, 'Szczeliniec_Wielki', 'en', 'Szczeliniec Wielki is the highest peak of the Table Mountains in the Table Mountains National Park in Lower Silesia, Poland. It is very close to the Poland-Czech border, but entirely within Polish territory. It belongs to the Crown of Polish Mountains and is one of the biggest tourist attractions of the Sudetes, the landscape reserve and viewing terraces with panoramic views of the Sudetes.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{marg