INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64042, 'Suur_Munamägi', 'en', 'Suur Munamägi is the highest peak in Estonia, reaching 318 metres (1,043 ft) above sea level. It is located near the village of Haanja, in Võru County in the southeastern corner of Estonia, close to the borders of both Latvia and Russia. The landscape around the peak—the Haanja Upland—is gently hilly.', '[{"index": "1", "level": 1, "title": "Name", "content": "Name[edit] Suur Munamägi was attested in historical sources as Munna Mäggi in 1790, and as Mun̄a Mäggi and Eyer Berg in 1798. The name derives from comparison of its rounded shape with an egg (Estonian: muna). The metaphor is frequent in oronyms because there are at least 19 hills named Munamägi in the historical county of Võrumaa.&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-tim