INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64045, 'Ballysaggartmore_Towers', 'en', ' Ballysaggartmore Towers are two ornate entrance lodges that are situated on the former Ballysaggartmore Demesne approx 2.5 kilometres from the town of Lismore in County Waterford, Ireland. The structures are considered architectural "follies".', '[{"index": "1", "level": 1, "title": "Origins", "content": ""}, {"index": "2", "level": 1, "title": "Folklore and folly", "content": ""}, {"index": "3", "level": 1, "title": "Legacy", "content": ""}, {"index": "4", "level": 1, "title": "Post Keily-Ussher", "content": ""}, {"index": "5", "level": 1, "title": "Modern era", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Ballysaggartmore_Towers", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:40:34.646738+11:00', '2026-01-13 00:25:12.791685+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64056, 'Biblioteca_Salaborsa', 'en', 'Salaborsa is the main public library in Bologna, region of Emilia-Romagna, Italy.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The library was opened in 2001, although the building it resides in, Palazzo d''Accursio, is far older. The ruins, on which the site was built, include remains from the ancient city of Bononia, which dates back to 189 BC.&#91;1&#93; There are also Etruscan ruins on site that predate the Roman ones.&#91;2&#93; ^ Cite error: The named reference :0 was invoked but never defined (see the help page). ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subs