INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64098, 'Rheinturm', 'en', 'The Rheinturm is a 240.5-metre-high (789 ft) concrete telecommunications tower in Düsseldorf, capital of the federal state (Bundesland) of North Rhine-Westphalia, Germany. Construction commenced in 1979 and finished in 1981. The Rheinturm carries aerials for directional radio, FM and TV transmitters. It stands 172.5 metres (564ft) tall and houses a revolving restaurant and an observation deck at a height of 168 metres (551ft). It is the tallest building in Düsseldorf.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] Rheinturm at blue hour View from the Rheinturm looking down onto Stadtmitte Rheinturm Düsseldorf 70th Anniversary of the state NRW Illumination with Rhine Comet The Rheinturm displaying the time. The number of dots represents the Hour, Minutes, and Seconds as shown in the image above View from the Rheinturm looking down onto Bürger Park"}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] List of tallest structures in Germany List of tallest structures in Europe List of tallest towers in the world"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-s