INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64148, 'Mosaik', 'en', 'Mosaik is a German comic book magazine. First published in December 1955, it is the longest-running German monthly comic book and the only one originating in East Germany that still exists. Mosaik also appeared in other countries and other languages. In its English-language edition it was published under the title Mosaic.', '[{"index": "1", "level": 1, "title": "Digedags years", "content": ""}, {"index": "2", "level": 1, "title": "Abrafaxe years", "content": ""}, {"index": "3", "level": 1, "title": "English-language editions", "content": ""}, {"index": "4", "level": 1, "title": "Other known foreign-language publications", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "Sources", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Mosaik", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:42:04.566794+11:00', '2026-01-13 00:25:12.797906+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64172, 'Chislehurst_Caves', 'en', 'The Chislehurst Caves are a series of intersecting man-made tunnels and caverns covering some 22 miles (35.4 km) in Chislehurst in the London Borough of Bromley.', '[{"index": "1", "level": 1, "title": "Second World War shelter", "content": ""}, {"index": "2", "level": 1, "title": "Mythology", "content": ""}, {"index": "3", "level": 1, "title": "TV and film", "content": ""}, {"index": "4", "level": 1, "title": "Music venue", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Chislehurst_Caves", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:42:04.566794+11:00', '2026-01-13 00:25:12.797906+11:00');
