INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64201, 'Hardraw_Force', 'en', 'Hardraw Force is a waterfall on Hardraw Beck in Hardraw Scar, a wooded ravine just outside the hamlet of Hardraw, 0.9 miles (1.5 km) north of the town of Hawes, Wensleydale, in the Yorkshire Dales. The Pennine Way long distance footpath passes close by.', '[{"index": "1", "level": 1, "title": "Hardraw Scar", "content": ""}, {"index": "2", "level": 1, "title": "Hardraw Force in popular culture", "content": ""}, {"index": "3", "level": 1, "title": "See also", "content": ""}, {"index": "4", "level": 1, "title": "Notes", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hardraw_Force", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:45:07.598646+11:00', '2026-01-13 00:25:12.797906+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64205, 'Goudurix', 'en', 'Goudurix is a steel roller coaster located in Parc Astérix in France. The Vekoma-built ride jointly held the European record for the greatest number of inversions upon its opening in 1989. The record was lost in 1995 to Dragon Khan in Spain. It is one of only two coasters in the world to feature a butterfly element. In 2007, following the release of the animated movie Asterix and the Vikings, Viking theming was added to the station and nearby rides, in the form of a wooden Viking longboat. Goudurix is located in the back-west of the park, near the Tonnerre 2 Zeus. The ride was repainted to a yellow and red track with grey supports color scheme from its previous white and yellow track with blue supports. It is one of the park''s main attractions, along with the Tonnerre 2 Zeus, OzIris, Trace du Hourra and Toutatis rollercoasters.', '[{"index": "1", "level": 1, "title": "Ride elements", "content": "Ride elements[edit] Goudurix has seven inversions in total: Batwing (2 inversions 1 element) Butterfly (2 inversions 1 element) Vertical Loop Double Corkscrew"}, {"index": "2", "level": 1, "title": "History", "content": "History[edit] Goudurix has seen many changes of its track, electrical systems and theme since its creation. 1988&#160;: Goudurix built by Vekoma with known problems (such as violent turns) 2000&#160;: Trains are changed and a few different wheels are tested in order to improve the ride comfort 2007&#160;: Total recovery of electrical device 2007&#160;: Theming added to the station 2009&#160;: The whole track is entirely repainted in red and yellow (instead of white and blue) 2010&#160;: A part of the trains are changed, making them heavier 2011&#160;: Test with new wheels to reduce vibrations 2013&#160;: Retracking&#91;1&#93; 2025&#160;: New trains from Vekoma &#91;2&#93; ^ .mw-parser-outpu