INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64326, 'Flatruet', 'en', 'Flatruet is a fell in north western Härjedalen, Sweden, between Mittådalen in Härjedalen Municipality and Ljungdalen. Flatruet comprises many ravines dating back to the end of the ice age. The ravines were formed when the ice lake in the Messlingen valley area burst and rushed down into the valley below. The majority of the ravines reside on the south side of Flatruet.', '[{"index": "1", "level": 1, "title": "Climate", "content": "Climate[edit] Climate data for Flatruet V 1991-2020 (932m) Month Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec Year Mean daily maximum °C (°F) −4.9(23.2) −5.2(22.6) −3.0(26.6) 1.3(34.3) 6.6(43.9) 12.0(53.6) 15.1(59.2) 13.5(56.3) 8.8(47.8) 2.4(36.3) −2.1(28.2) −4.2(24.4) 3.4(38.0) Daily mean °C (°F) −7.5(18.5) −7.7(18.1) −5.7(21.7) −1.7(28.9) 3.1(37.6) 8.0(46.4) 11.1(52.0) 9.6(49.3) 5.4(41.7) −0.1(31.8) −4.3(24.3) −6.7(19.9) 0.3(32.5) Mean daily minimum °C (°F) −10.4(13.3) −10.9(12.4) −9.0(15.8) −5.0(23.0) −0.5(31.1) 4.1(39.4) 7.3(45.1) 6.4(43.5) 2.7(36.9) −2.2(28.0) −6.7(19.9) −9.4(15.1) −2.8(27.0) Source: NOAA&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.