INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64379, 'Alice''s_Curious_Labyrinth', 'en', 'Alice''s Curious Labyrinth is a hedge maze attraction at the Disneyland Park within Disneyland Paris. It opened in 1992 with the Park, and belongs to the British part of Fantasyland. A similar maze attraction, based on both the 1951 and 2010 Disney film adaptations of Lewis Carroll''s Alice in Wonderland, exists at Shanghai Disneyland Park.', '[{"index": "1", "level": 1, "title": "Disneyland Paris", "content": ""}, {"index": "2", "level": 2, "title": "The Labyrinth", "content": ""}, {"index": "3", "level": 2, "title": "Tulgey Wood", "content": ""}, {"index": "4", "level": 2, "title": "Queen of Hearts''s Maze", "content": ""}, {"index": "5", "level": 1, "title": "March Hare Refreshments", "content": ""}, {"index": "6", "level": 1, "title": "In Epic Mickey", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Alice''s_Curious_Labyrinth", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:51:23.495744+11:00', '2026-01-13 00:25:12.810409+11:00');
