INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64526, 'Minija', 'en', 'The Minija is a river in western Lithuania and a right tributary to the Nemunas. It is 202 km (126 mi) long. It begins from small Lake Didovas, and hydrographically from lake Sydeklis, 14 km south of Telšiai. The rivulet that flows out of Sydeklis here is called Mava, in between Lake Ilgis and Lake Pluotinalis - Kliurkė and only after Lake Didovo it gets the Minija name.', '[{"index": "1", "level": 1, "title": "Tributary rivers", "content": "Tributary rivers[edit] Left: Pala, Alantas, Žvelsa, Agluona, Veiviržas, Tenenys Right: Sausdaravas, Babrungas, Mišupė, Salnatas"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} Minija near Kintai .mw-p