INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64691, 'Yılankale', 'en', 'Yılankale is a late 12th–13th century Armenian castle in Adana Province of Turkey. It is known in Armenian as Levonkla after its possible founder—King Leo (Levon) I the Magnificent of the Armenian Kingdom of Cilicia. Medieval Armenian names attached to the site are Kovara and Vaner.', '[{"index": "1", "level": 1, "title": "Architecture", "content": ""}, {"index": "2", "level": 1, "title": "History", "content": "History[edit] In late 19th century, the inhabitants of Yılankale were Nogai immigrants from the Crimean War.&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Barkley, Henry C. (1891). A Ride through Asia Minor and Armenia. London: William Clowes and Sons Limited. p.&#160;193. We pitched our tent in the village of Yilan Kalé (Snake Castle), belonging to some Nogai Tartars, who settled here just after the Crimean war."}, {"index": "3", "level": 1, "title": "Gallery", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Y%C4%B1lankale", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:00:52.598864+11:00', '2026-01-13 00:25:12.829328+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64716, 'Salamis', 'en', 'Salamis may refer to :', '[{"index": "1", "level": 1, "title": "Places and battles", "content": "Places and battles[edit] Salamis Island in the Saronic Gulf of the Aegean Sea, near Athens, Greece Salamina (city), former municipality on Salamis Island Salamis Naval Base, a Greek naval base on Salamis Island Battle of Salamis, 480 BC, between allied Greeks and Achaemenid Persian empire Salamis, Cyprus or Constantia, an ancient city in Cyprus Battle of Salamis in Cyprus (450 BC), between Greeks and Persians Battle of Salamis (306 BC), between Ptolemy I and Demetrius Salamis (ruin), site in Northern Israel that had formerly been a fortress"}, {"index": "2", "level": 1, "title": "Other uses", "content": "Other uses[edit] Greek battleship Salamis, a dreadnought ordered in 1912 Salamis (mythology), a nymph in Greek mythology Salamis (butterfly), a genus in the family Nymphalidae Salamis (novel), a 2020 book by Harry Turtledove Salamis Tablet, a counting board (300 BC) discovered on Salamis Island"}, {"index": "3", "level": 1, "title": "See also", "content": "See also[edit] Salami, a type of cured sausage Salamina (disambiguation) Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Salamis.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Salamis", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:02:02.521340+11:00', '2026-01-13 00:25:12.829328+11:00');
