INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (64969, 'Hadrianopolis', 'en', 'Hadrianopolis or Adrianopolis may refer to several cities named after Hadrian:', '[{"index": "1", "level": 1, "title": "Europe", "content": "Europe[edit] Hadrianopolis, a former quarter of Athens, Greece; see Arch of Hadrian (Athens) Hadrianopolis in Epiro, a town and bishopric of ancient Epirus, now Albania Hadrianopolis in Haemimontus, a former name of Edirne, Turkey Hadrianopolis (Macedonia), a town of ancient Macedonia, Greece"}, {"index": "2", "level": 1, "title": "Asia", "content": "Asia[edit] Hadrianopolis in Caria or Stratonicea (Caria), a former name of Eskihisar, Turkey Hadrianopolis in Cilicia, a former name of Mersin, Turkey Hadrianopolis in Lycia, another name of Olympus (Lycia), Turkey Hadrianopolis in Lydia or Stratonicea (Lydia), a former name of Siledik, Turkey Hadrianopolis in Paphlagonia, a town and bishopric of ancient Paphlagonia and later Bithynia, now Turkey Hadrianopolis in Pisidia, a former name of Şarkikaraağaç, Turkey Hadrianopolis (Pisidia), a town of ancient Pisidia, now Turkey Hadrianopolis in Phrygia, a town and bishopric of ancient Phrygia, now Turkey Hadrianopolis in Pontus, a former name of Amasya, Turkey Hadrianopolis in Pontus, a former name of Niksar, Turkey Hadrianopolis in Syria, a former name of Palmyra, Syria"}, {"index": "3", "level": 1, "title": "Africa", "content": "Africa[edit] Hadrianopolis in Africa, a former name of Carthage, Tunisia Hadrianopolis in Cyrenaica, a former name of Deriana, Libya .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} Topics referred to by the same termThis disambiguation page lists articles about distinct geographical locations with the same name. If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hadrianopolis", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:06:20.431002+11:00', '2026-01-13 00:25:12.848271+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65000, 'Schöner_Brunnen', 'en', 'Schöner Brunnen is a 14th-century fountain located on Nuremberg''s main market next to the town hall and is considered one of the main attractions of the city''s Historical Mile. The fountain is approximately 19 metres high and has the shape of a Gothic spire.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The fountain was built by Heinrich Beheim from 1385 to 1396. During ww2 the fountain was surrounded by concrete to protect it from bombings.&#91;1&#93; Spinning the good luck bringing wish ring .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Wilder, Johann Christoph Jakob (1824). Der schöne Brunnen zu Nürnberg (in German) (2nd&#160;ed.). Riegel und Wießner. .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Sch%C3%B6ner_Brunnen", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:06:20.431002+11:00', '2026-01-13 00:25:12.848271+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65033, 'Fan_Bwlch_Chwyth', 'en', 'Fan Bwlch Chwyth is a peak in the Fforest Fawr section of the Brecon Beacons National Park and within the county of Powys.', '[{"index": "1", "level": 1, "title": "Geology", "content": "Geology[edit] The hill is formed from sandstones and mudstones of the Senni Beds Formation and Brownstones Formation of the Old Red Sandstone laid down during the Devonian period. A north-northwest - south-southeast trending fault runs across its north-eastern face. This face is much the steepest and has its origins in the ice ages when a minor glacier grew at this spot. It has left a couple of arcuate moraines which are readily seen from the track. The glaciated rock face has been quarried. The quarry is designated as a site of special scientific interest for its geological interest.&#91;1&#93; ^ British Geological Survey 1:50,000 map sheet 231 ''Brecon'' &amp; accompanying sheet explanation"}, {"index": "2", "level": 1, "title": "Access", "content": "Access[edit] The entire hill is open country across which the walker can wander at will. A bridleway runs south-eastward from the minor road between Heol Senni and the A4067 road. The bridleway follows, in part at least, the vehicular track (no public vehicular access) to the disused quarry."}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "4", "level": 1, "title": "External links", "content": "External links[edit] images of Fan Bwlch Chwyth on Geograph website"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Fan_Bwlch_Chwyth", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:06:20.431002+11:00', '2026-01-13 00:25:12.854542+11:00');
