INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65137, 'Fort_de_Bellegarde', 'en', 'The Fort de Bellegarde is a 17th-century bastion fortification located above the town of Le Perthus, in the Pyrénées-Orientales département of southern France.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Le Perthus became French territory after the Treaty of the Pyrenees (1659). Bellegarde was captured by the Spaniards in 1674, but retaken by Schomberg in 1675. In 1678, Vauban''s plans for the new fortress of Bellegarde were approved. During the War of the Pyrenees, the fortress was besieged in May - June 1793 by the Spanish and then by the French (May - Sept. 1794).&#91;1&#93; During World War II, the fort was used as a holding prison by the Gestapo for escaped prisoners of war and enemy agents. ^ historyofwar.org, Napoleonic War website entry."}, {"index": "2", "level": 1, "title": "In popular culture", "content": ""}, {"index": "3", "level": 1, "title": "Tourism", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Fort_de_Bellegarde", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:06:20.431002+11:00', '2026-01-13 00:25:12.860734+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65141, 'Tkalnia_Sp._A._Wyrobów_Wełnianych_i_Bawełnianych_Marcusa_Silbersteina', 'en', 'Emen is a village in Bor District of Niğde Province, Turkey. Its population is 130 (2022). It is situated in the Central Anatolian plains. Its distance to Bor is 15 kilometres (9.3 mi) to Niğde is 29 kilometres (18 mi).', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,.mw-parser-output .hlist dl ol,.mw-parser-output .hlist dl ul,.mw-parser-output .hlist ol dl,.mw-parser-output .hlist ol ol,.mw-parser-output .hlist ol ul,.mw-parser-output .hlist ul dl,.mw-parser-output .hlist ul ol,.mw-parser-output .hlist ul ul{display:inline}.mw-parser-output .hlist .mw-empty-li{display:none}.mw-parser-output .hlist dt::after{content:\": \"}.mw-parser-output .hlist dd::after,.mw-parser-output .hlist li::after{content:\"\\a0 · \";font-weight:bold}.mw-parser-output .hlist dd:last-child::after,.mw-parser-output .hlist dt:last-child::after,.mw-parser-output .hlist li:last-child::after{content:none}.mw-parser-output .hlist dd dd:first-child::before,.mw-parser-output .hlist dd dt:first-child::before,.mw-parser-output .hlist dd li:first-child::before,.mw-parser-output .hlist dt dd:first-child::before,.mw-parser-output .hlist dt dt:first-child::before,.mw-parser-output .hlist dt li:first-child::before,.mw-parser-output .hlist li dd:first-child::before,.mw-parser-output .hlist li dt:first-child::before,.mw-parser-output .hlist li li:first-child::before{conten