INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65319, 'Ojo_Guareña', 'en', 'Ojo Guareña is a karst complex located in the Cantabrian Mountains of Castile and Leon, Spain, declared a natural monument by the government of Castile and Leon in 1996. It is composed of over 90 kilometres (56 mi) of galleries and passages within an area of some 13,850 hectares. The limestone formation containing the system is approximately 100 metres (330 ft) thick and sits on a massive water-resistant layer of marl. The caves were formed in the limestone by erosion sometime within the Coniacian Age. Ojo Guareña was considered the greatest karst system of the Iberian Peninsula until 2009, when a significant length of new passages was discovered in the Mortillano system. It is also the 24th longest cave system.', '[{"index": "1", "level": 1, "title": "Features", "content": ""}, {"index": "2", "level": 1, "title": "Flora and fauna", "content": ""}, {"index": "3", "level": 1, "title": "Archaeology", "content": ""}, {"index": "4", "level": 2, "title": "Palaeolithic", "content": ""}, {"index": "5", "level": 2, "title": "Neolithic and Bronze Age", "content": ""}, {"index": "6", "level": 1, "title": "Protected status", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Ojo_Guare%C3%B1a", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:06:20.431002+11:00', '2026-01-13 00:25:12.871472+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65370, 'Geijersgården', 'en', 'Geijersgården is located in Uppsala, Sweden, north of Carolina Rediviva, the main building of Uppsala University Library.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit]"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] [1]"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Geijersg%C3%A5rden", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:06:20.431002+11:00', '2026-01-13 00:25:12.877077+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65411, 'Ankerwycke_Yew', 'en', 'The Ankerwycke Yew is an ancient yew tree close to the ruins of St Mary''s Priory, the site of a Benedictine nunnery built in the 12th century, near Wraysbury in Berkshire, England. It is a male tree with a girth of 8 metres (26 ft) at 0.3 metres. The tree is at least 1,400 years old, and could be as old as 2,500 years.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Fortingall Yew List of individual trees List of oldest trees"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "3", "level": 1, "title": "External links", "content": "External links[edit] Magna Carta and the Ankerwycke Yew Ancient yews under threat in Churchyards and sacred groves"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Ankerwycke_Yew", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:22:19.853824+11:00', '2026-01-13 00:25:12.877077+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65412, 'Mont_Saint-Michel_(Alsace)', 'en', 'Mont Saint-Michel is a hill, 437 metres high, in the Vosges mountains in the French region of Alsace. It rises above the town and abbey of Saint-Jean-Saverne. It is home to a St. Michael''s Shrine like its more famous cousin in Normandy, but historically is not related to it.', '[{"index": "1", "level": 1, "title": "Literature", "content": "Literature[edit] Jean-Joseph Ring: Promenades historiques et archéologiques autour de Saverne. Saverne, 2000, .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}ISSN&#160;1159-4705"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Mont_Saint-Michel_(Alsace)", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:22:19.853824+11:00', '2026-01-13 00:25:12.877077+11:00');
