INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65468, 'Opstainių_II_piliakalnis', 'en', 'Life in the Snow is a 2016 British television show created by the BBC Natural History Unit.', '[{"index": "1", "level": 1, "title": "Episodes", "content": "Episodes[edit] No.TitleOriginal release date1\"Life in the Snow\"29&#160;December&#160;2016&#160;(2016-12-29)&#91;1&#93; Gordon Buchanan meets the animals who live in nature''s winter wonderlands, from the polar bear mother helping her cubs to the owl searching for food..mw-parser-output .wikiepisodetable tr.vevent,.mw-parser-output .wikiepisodetable tr.vevent th{text-align:center}.mw-parser-output .wikiepisodetable .summary{text-align:left}@media screen{html.skin-theme-clientpref-night .mw-parser-output .module-episode-list-row small[style]{color:#d5d584!important;background:#333;padding:8px}html.skin-theme-clientpref-night .mw-parser-output .wikiepisodetable span[style^=\"color\"]{color:inherit!important;border-bottom:dotted 1px}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .module-episode-list-row small[style]{color:#d5d584!important;background:#333;padding:8px}html.skin-theme-clientpref-os .mw-parser-output .wikiepisodetable span[style^=\"color\"]{color:inherit!important;border-bottom:dotted 1px}} ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em cente