INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65715, 'Warton_Crag', 'en', 'Warton Crag is a limestone hill in north west Lancashire, England. It lies to the north west of Warton village, in City of Lancaster district. At 163 metres (535 ft) it is the highest point in the Arnside and Silverdale Area of Outstanding Natural Beauty, and is listed as a "HuMP" or "Hundred Metre Prominence", having a "drop" or "prominence" of 126 metres (413 ft) with its parent being Hutton Roof Crags. Two areas are Local Nature Reserves, called Warton Crag and Warton Crag Quarry. Different sections are owned by Lancashire County Council, the Wildlife Trust for Lancashire, Manchester and North Merseyside, Lancaster City Council and the Royal Society for the Protection of Birds.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Scheduled monuments in Lancashire Leighton Hall Leighton Moss RSPB reserve Morecambe Bay"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-o