INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65721, 'Walden_7', 'en', 'The Walden 7 is an apartment building designed by Ricardo Bofill Taller de Arquitectura and located in Sant Just Desvern near Barcelona, in Catalonia, Spain. Construction began in 1972, with it being inaugurated three years later. It was renovated due to damage from 1993 to 1995.', '[{"index": "1", "level": 1, "title": "Name", "content": ""}, {"index": "2", "level": 1, "title": "Structure and usage", "content": ""}, {"index": "3", "level": 1, "title": "Reception", "content": ""}, {"index": "4", "level": 1, "title": "In popular culture", "content": ""}, {"index": "5", "level": 1, "title": "Gallery", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "Citations", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Walden_7", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:32:47.949946+11:00', '2026-01-13 00:25:12.896116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65756, 'Гуркало', 'en', 'The Hurkalo waterfall is located on the Velyka Richka River, 3 kilometres (1.9 mi) south-west of Korchyn, Stryi Raion, Lviv Oblast of western Ukraine. The waterfall is 5 metres (16 ft) high.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of waterfalls Waterfalls of Ukraine"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-pars