INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65933, 'Tornado', 'en', 'A tornado, also known as a twister, is a rapidly rotating column of air that extends vertically from the surface of the Earth to the base of a cumulonimbus or cumulus cloud. Tornadoes are often visible in the form of a condensation funnel originating from the cloud base, with a cloud of rotating debris and dust close to the ground. Most tornadoes have wind speeds less than 180 kilometers per hour, are about 80 meters across, and travel several kilometers before dissipating. The most extreme tornadoes can attain wind speeds of more than 480 kilometers per hour (300 mph), can be more than 3 kilometers (2 mi) in diameter, and can stay on the ground for more than 100 km (62 mi).', '[{"index": "1", "level": 1, "title": "Rating", "content": ""}, {"index": "2", "level": 1, "title": "Etymology", "content": ""}, {"index": "3", "level": 1, "title": "Definitions", "content": ""}, {"index": "4", "level": 2, "title": "Funnel cloud", "content": ""}, {"index": "5", "level": 2, "title": "Outbreaks and families", "content": ""}, {"index": "6", "level": 1, "title": "Characteristics", "content": ""}, {"index": "7", "level": 2, "title": "Size and shape", "content": ""}, {"index": "8", "level": 2, "title": "Track length", "content": ""}, {"index": "9", "level": 2, "title": "Appearance", "content": ""}, {"index": "10", "level": 2, "title": "Rotation", "content": ""}, {"index": "11", "level": 2, "title": "Sound and seismology", "content": ""}, {"index": "12", "level": 2, "title": "Electromagnetic, lightning, and other effects", "content": ""}, {"index": "13", "level": 1, "title": "Life cycle", "content": ""}, {"index": "14", "level": 2, "title": "Supercell relationship", "content": ""}, {"index": "15", "level": 2, "title": "Formation", "content": ""}, {"index": "16", "level": 2, "title": "Maturity", "content": ""}, {"index": "17", "level": 2, "title": "Dissipation", "content": ""}, {"index": "18", "level": 1, "title": "Types", "content": ""}, {"index": "19", "level": 2, "title": "Multiple vortex", "content": ""}, {"index": "20", "level": 2, "title": "Waterspout", "content": ""}, {"index": "21", "level": 2, "title": "Landspout", "content": ""}, {"index": "22", "level": 2, "title": "Similar circulations", "content": ""}, {"index": "23", "level": 3, "title": "Gustnado", "content": ""}, {"index": "24", "level": 3, "title": "Dust devil", "content": ""}, {"index": "25", "level": 3, "title": "Fire whirls", "content": ""}, {"index": "26", "level": 3, "title": "Steam devils", "content": ""}, {"index": "27", "level": 1, "title": "Intensity and damage", "content": ""}, {"index": "28", "level": 1, "title": "Climatology", "content": ""}, {"index": "29", "level": 2, "title": "Associations with climate and climate change", "content": ""}, {"index": "30", "level": 1, "title": "Detection", "content": ""}, {"index": "31", "level": 2, "title": "Radar", "content": ""}, {"index": "32", "level": 2, "title": "Storm spotting", "content": ""}, {"index": "33", "level": 2, "title": "Visual evidence", "content": ""}, {"index": "34", "level": 1, "title": "Extremes", "content": ""}, {"index": "35", "level": 1, "title": "Safety", "content": ""}, {"index": "36", "level": 1, "title": "Myths and misconceptions", "content": ""}, {"index": "37", "level": 1, "title": "Ongoing research", "content": ""}, {"index": "38", "level": 1, "title": "See also", "content": ""}, {"index": "39", "level": 1, "title": "References", "content": ""}, {"index": "40", "level": 1, "title": "Further reading", "content": ""}, {"index": "41", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Tornado", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:39:03.512951+11:00', '2026-01-13 00:25:12.915043+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65961, 'Teos', 'en', 'Teos or Teo was an ancient Greek city on the coast of Ionia, on a peninsula between Chytrium and Myonnesus. It was founded by Minyans from Orchomenus, Ionians and Boeotians, but the date of its foundation is unknown. Teos was one of the twelve cities which formed the Ionian League. The city was situated on a low hilly isthmus. Its ruins are located to the south of the modern town of Sığacık in the Seferihisar district of İzmir Province, Turkey.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Pausanias writes that the city was founded by Minyans from Orchomenus under the leadership of Athamas, a descendant of Athamas the son of Aeolus. Later on they were joined by Ionians and more colonists from Athens and Boeotia.&#91;1&#93; Because it was founded by Athamas, Anacreon also called it Athamantis (Ἀθαμαντίς).&#91;2&#93; Teos was a flourishing seaport with two fine harbours until Cyrus the Great invaded Lydia and Ionia (c. 546&#160;BC). The Teans found it prudent to retire overseas, to the newly founded colonies of Abdera in Thrace and Phanagoria on the Asian side of the Cimmerian Bosporus. The port was revived by Antigonus Cyclops. During the times of the Roman emperors, the town was noted for its wine, a theatre and Temple of Dionysus. These are positioned near the acropolis, which is situated on a low hill and had fortifications by the 6th century. A shipwreck near Tektaş, a small rock outcrop near Teos harbour, dates from the Classical period (around the 6th to the 4th centuries BC) and implies trading connections by sea with the eastern Aegean Islands. It was a member of the Lydian group of the Ionian League, one of the four groups defined by Herodotus, based on the particular dialects of the cities. Vitruvius notes Hermogenes of Priene as the architect of the monopteral temple of Dionysus at Teos.&#91;3&#93; ^ Cite error: The named reference paus was invoked but never defined (see the help page). ^ Strabo, Geography, 14.1.3 ^ Cite error: The named reference vitr was invoked but never defined (see the help page)."}, {"index": "2", "level": 1, "title": "The site today", "content": ""}, {"index": "3", "level": 1, "title": "Notable people", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "Further reading", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Teos", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:39:03.512951+11:00', '2026-01-13 00:25:12.915043+11:00');
