INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66109, 'De_Echoput', 'en', 'De Echoput is a restaurant and part of Hotel Gastronomique De Echoput in Hoog Soeren, Apeldoorn in the Netherlands. It is a fine dining restaurant that was awarded one or two Michelin stars in the period 1971–1997, 2002-2004 and in 2012. GaultMillau awarded the restaurant 15.0 out of 20 points.', '[{"index": "1", "level": 1, "title": "Michelin star history", "content": "Michelin star history[edit] - 1971-1984: one star&#91;1&#93;&#91;2&#93;&#91;3&#93; - 1985-1989: two stars&#91;3&#93;&#91;4&#93; - 1990-1997: one star&#91;4&#93;&#91;5&#93;&#91;6&#93; - 1998-2001: no stars&#91;6&#93;&#91;7&#93; - 2002-2004: one star&#91;7&#93; - 2005-2011: no stars&#91;7&#93; - 2012: one star&#91;8&#93; According to several sources, the restaurant was already awarded a Michelin star from 1967. The Michelin Guide does not give any evidence of this.&#91;9&#93;&#91;10&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless)