INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66153, 'Bullers_of_Buchan', 'en', 'The name Bullers of Buchan refers both to a collapsed sea cave and to the adjacent village, situated about 6 miles (9.7 km) south of Peterhead in Buchan, Aberdeenshire, Scotland.', '[{"index": "1", "level": 1, "title": "Cave", "content": ""}, {"index": "2", "level": 1, "title": "Village", "content": ""}, {"index": "3", "level": 1, "title": "Cliffs", "content": ""}, {"index": "4", "level": 1, "title": "Access", "content": ""}, {"index": "5", "level": 1, "title": "Name", "content": ""}, {"index": "6", "level": 1, "title": "History", "content": "History[edit] The local area is rich with prehistory and historical features. Somewhat inland are a number of prehistoric monuments including Catto Long Barrow,&#91;1&#93; Silver Cairn and numerous tumuli. In that same vicinity of the Laeca Burn watershed is the point d''appui of historic battles between invading Danes and indigenous Picts. The Bullers of Buchan were cited in historical literature as early as the 18th century, most notably by the literary journalist James Boswell.&#91;2&#93; The Great North of Scotland Railway opened a halt at Bullers O''Buchan in 1900 to serve the needs of visitors to the site. The station closed in 1932. ^ C. Michael Hogan, 2008 ^ James Boswell, 1774"}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "Line notes", "content": ""}, {"index": "9", "level": 1, "title": "References", "content": ""}, {"index": "10", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Bullers_of_Buchan", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:42:59.566117+11:00', '2026-01-13 00:25:12.927339+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66157, 'Ambion_Hill', 'en', 'Ambion Hill is a hill in west Leicestershire, England, south of the town of Market Bosworth and lying south of the Sutton Cheney to Shenton road and north of Dadlington and of Fenn Lanes Roman road. The Ashby Canal passes to the south of the hill.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] Map sources for Ambion Hill Bosworth Battlefield Heritage Centre .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefault,.mw-parser-output .geo-multi-punct,.mw-parser-output .geo-inline-hidden{display:none}.mw-parser-output .longitude,.mw-parser-output .latitude{white-space:nowrap}52°35′47″N 1°24′29″W&#xfeff; / &#xfeff;52.59631°N 1.40796°W&#xfeff; / 52.59631; -1.40796"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Ambion_Hill", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:42:59.566117+11:00', '2026-01-13 00:25:12.927339+11:00');
