INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66190, 'Scuola_Grande_dei_Carmini', 'en', 'The Scuola Grande dei Carmini is a confraternity building in Venice, Italy. It is located in the sestiere of Dorsoduro, before Campo dei Carmini and Campo Santa Margherita, upon which its facade looks. It stands, separated by an alley, to the northeast of the church of Santa Maria dei Carmini.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] It was the former home of the Venetian Scuola of the same name. The Scuola was founded in 1594 under Doge Pasquale Cicogna, and was the last of its kind to be recognized as a Scuola Grande in 1767 by the Council of Ten. Initially it was located in the Convent of the Church of Carmini, whose structure also faces the campo of the same name. The present scuola building was designed by Francesco Caustello and Baldassare Longhena. In 1807, the confraternity was suppressed by Napoleon''s anticlerical decrees. The Austrians allowed the Scuola to reopen, and it continues activities today, though mostly cultural activities."}, {"index": "2", "level": 1, "title": "Exterior", "content": ""}, {"index": "3", "level": 1, "title": "Interior", "content": ""}, {"index": "4", "level": 2, "title": "The Chapel of Our Lady of Mount Carmel", "content": ""}, {"index": "5", "level": 2, "title": "The stairs and the corridor", "content": ""}, {"index": "6", "level": 2, "title": "The capitular hall", "content": ""}, {"index": "7", "level": 2, "title": "Sala dell''Albergo", "content": ""}, {"index": "8", "level": 2, "title": "The rooms of the archive", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Scuola_Grande_dei_Carmini", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:42:59.566117+11:00', '2026-01-13 00:25:12.927339+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66203, 'Babele', 'en', 'Babele is the name for an area on the Bucegi Mountains plateau in Romania, within the Southern Carpathians.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Baba Dochia&#160;– Romanian mythical figure Seven Natural Wonders of Romania"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefault,.mw-parser-output .geo-multi-punct,.mw-parser-output .geo-inline-hidden{display:none}.mw-parser-output .longitude,.mw-parser-output .latitude{white-space:nowrap}45°24′24″N 25°28′18″E&#xfeff; / &#xfeff