INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66390, 'Adada', 'en', 'Adada (Korean: 아다다) is a 1987 South Korean film directed by Im Kwon-taek, based on a story by Kye Yong-mook.', '[{"index": "1", "level": 1, "title": "Plot", "content": ""}, {"index": "2", "level": 1, "title": "Cast", "content": ""}, {"index": "3", "level": 1, "title": "Awards", "content": ""}, {"index": "4", "level": 1, "title": "References", "content": ""}, {"index": "5", "level": 1, "title": "Sources", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Adada", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:52:10.075883+11:00', '2026-01-13 00:25:12.939827+11:00');
