INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66424, 'Almscliffe_Crag', 'en', 'Almscliffe Crag, or Almscliff Crag, also known as Great Almscliff Crag to distinguish it from Little Almscliff, 3 miles (5 km) north west, is a Millstone Grit outcrop at the top of a small hill near the village of North Rigton, between Leeds and Harrogate in North Yorkshire, England. The crag lies on the boundary of the civil parishes of North Rigton and Stainburn. The crag was formed due to the softer adjacent strata of shale and mudstone eroding at a faster rate than the hard wearing millstone.', '[{"index": "1", "level": 1, "title": "Rock climbing", "content": ""}, {"index": "2", "level": 1, "title": "As a film location", "content": ""}, {"index": "3", "level": 1, "title": "Folklore", "content": ""}, {"index": "4", "level": 1, "title": "Name", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Almscliffe_Crag", "text": "Wikipedia"}]'::jsonb, '2026-01-13 12:52:52.897247+11:00', '2026-01-13 00:25:12.946014+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66428, 'Eccles_Pike', 'en', 'Eccles Pike is an isolated hill three miles west of Chapel en le Frith in the Derbyshire Peak District, England. It consists of gritstone, pink in colour at the summit. While not as prominent as the surrounding hills of Cracken Edge and Combs Moss, it is popular with walkers. At 370 metres (1,210 ft) above sea level, it offers good views of Manchester to the west and the Kinder Scout plateau to the east. Combs Reservoir lies just south of the hill.', '[{"index": "1", "level": 1, "title": "Eccles Pike Fell Race", "content": "Eccles Pike Fell Race[edit] The Eccles Pike Fell Race is reputedly one of the oldest fell races in the country, dating back to the beginning of the 20th century. It is renowned for being short, tough and demanding.&#91;1&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parse