INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66512, 'Gialia_Monastery', 'en', 'The Gialia Monastery is a ruined Georgian Orthodox monastery from the medieval period. It is located in the village of Gialia, Paphos District, northwest Cyprus. The monastery is dedicated to the Virgin Mary.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] Wall painting fragments Remnants of qvevri Cistern"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "3", "level": 1, "title": "External links", "content": "External links[edit] Book: Georgian monastery of Galia on Cyprus — Archeological finds. The National Parliamentary Library of Georgia .mw-parser-output cite.citation{font-style:inher