INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66758, 'Grotta_del_Ninfeo', 'en', 'The Grotta del Ninfeo is an artificial cavity in the rock of Temenite Hill located in the Archaeological park of Neapolis in Syracuse.', '[{"index": "1", "level": 1, "title": "Terrace of Temenite Hill", "content": ""}, {"index": "2", "level": 1, "title": "Depiction by Jean Hoüel", "content": ""}, {"index": "3", "level": 1, "title": "Gallery", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Grotta_del_Ninfeo", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:03:30.698078+11:00', '2026-01-13 00:25:12.965617+11:00');
