INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66820, 'Хой-Кая', 'en', 'Хой-Кая́ — группа похожих на башни скал в Крыму, среди которых выделяется «голова Екатерины Второй» ; на скале установлен репер.', '[{"index": "1", "level": 1, "title": "Источники", "content": "Источники[править | править код] Крым. Географические названия Крымский блог"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%A5%D0%BE%D0%B9-%D0%9A%D0%B0%D1%8F", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:03:30.698078+11:00', '2026-01-13 00:25:12.965617+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66835, 'Drachenhöhle', 'en', 'Drachenhöhle or Drachenhöhle Mixnitz is a 542 m (1,778 ft) long cave with a 20 m (66 ft) wide and 12 m (39 ft) high entrance near Mixnitz, Styria, Austria, south-east of Bruck an der Mur located at an elevation of 950 m (3,120 ft) above sea level. Cave bear of the species and other bone fossils that people found during the Middle Ages were deemed to be the bones of dragons, a belief that culminated in the saga of the "Dragon slayer of Mixnitz". The cave is one of the largest caves in the Alps where bears occupied an area that stretched over a length of way over 500 m (1,600 ft), by an average width of up to 40 m (130 ft) and a height of 10 to 15 m.', '[{"index": "1", "level": 1, "title": "Excavations", "content": "Excavations[edit] Records of archaeological work were published in a monograph in 1931, that was re-edited by Othenio Abel and G. Kyrie. Excavations took place at two locations inside the cave. The around 150,000 years old sediment''s strata were divided into several layers, that among those named \"Prehistoric layer\" and \"Paleolithic fireplace\" also yielded a \"Neanderthal layer\".&#91;1&#93;&#91;2&#93; To this day the bones of more than 30,000 cave bear fossils were excavated. The site was protected in 1928 and declared a natural monument in 1949.&#91;3&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wi