INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66947, 'Kongeegen', 'en', 'Kongeegen is a renowned oak tree in Denmark. It grows in Jægerspris Nordskov near Jægerspris, on the island of Sjælland. A scientific investigation in 1965 of the tree''s rings indicated that the tree has an estimated age of 1500–2000 years, and may well be the oldest living oak in northern Europe. It probably originally grew in an open meadow, to account for its short trunk and low branching, with other taller forest trees growing up around it subsequently. Kongeegen is located in the same forest as Snoegen and Storkeegen.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of individual trees List of oldest trees"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-lis