INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66949, 'Snoegen', 'en', 'Snoegen was an ancient pedunculate oak located in Jægerspris Nordskov, near the town Jægerspris in Denmark. Snoegen is located in the same forest as Kongeegen and Storkeegen. Snoegen died in 1991 after a few seasons of decreasing foliage, and following works to erect a wooden barrier around the tree that may have damaged the root zone. The trunk still stands. Snoegen is named after the twisted trunk. The trunk had a perimeter of 8.90 meters in 1990.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of individual trees"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .geo-default,.mw-pars