INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (66952, 'Самсон', 'en', 'Samson was the last of the judges of the ancient Israelites mentioned in the Book of Judges and one of the last leaders who "judged" the twelve tribes of Israel before the institution of the monarchy. He is sometimes regarded as an Israelite version of the popular Near Eastern folk hero archetype also embodied by the Sumerian Gilgamesh and Enkidu, as well as the Greek Heracles. Samson was given superhuman powers by God in the form of extreme strength.', '[{"index": "1", "level": 1, "title": "Biblical narrative", "content": ""}, {"index": "2", "level": 2, "title": "Birth", "content": ""}, {"index": "3", "level": 2, "title": "Marriage to a Philistine", "content": ""}, {"index": "4", "level": 2, "title": "Delilah", "content": ""}, {"index": "5", "level": 2, "title": "Death", "content": ""}, {"index": "6", "level": 1, "title": "Interpretations", "content": ""}, {"index": "7", "level": 2, "title": "Archaeology", "content": ""}, {"index": "8", "level": 2, "title": "Rabbinic literature", "content": ""}, {"index": "9", "level": 2, "title": "Christian interpretations", "content": ""}, {"index": "10", "level": 2, "title": "Islamic literature", "content": ""}, {"index": "11", "level": 2, "title": "Scholarly", "content": ""}, {"index": "12", "level": 3, "title": "Comparison with other religious and mythological figures", "content": ""}, {"index": "13", "level": 3, "title": "Traditional views", "content": ""}, {"index": "14", "level": 3, "title": "Religious and moral meaning or lack of it", "content": ""}, {"index": "15", "level": 2, "title": "Death by suicide", "content": ""}, {"index": "16", "level": 3, "title": "Samson did not commit suicide", "content": ""}, {"index": "17", "level": 3, "title": "Samson''s death was a suicide attack", "content": ""}, {"index": "18", "level": 1, "title": "Cultural influences", "content": ""}, {"index": "19", "level": 2, "title": "Cultural traditions", "content": ""}, {"index": "20", "level": 2, "title": "References to Samson in media and the arts", "content": ""}, {"index": "21", "level": 2, "title": "Political and military news and commentary", "content": ""}, {"index": "22", "level": 2, "title": "Military and militant references to Samson", "content": ""}, {"index": "23", "level": 3, "title": "The Samson Option nuclear strategy", "content": ""}, {"index": "24", "level": 3, "title": "Militant suicide operations", "content": ""}, {"index": "25", "level": 3, "title": "Operation Samson", "content": ""}, {"index": "26", "level": 4, "title": "1947 Operation Samson", "content": ""}, {"index": "27", "level": 4, "title": "1967 Operation Samson", "content": ""}, {"index": "28", "level": 4, "title": "Rejected name for <i>Operation Gideon''s Chariots</i>", "content": ""}, {"index": "29", "level": 3, "title": "Military units named after Samson (Shimshon)", "content": ""}, {"index": "30", "level": 4, "title": "Samson''s Foxes", "content": ""}, {"index": "31", "level": 4, "title": "Shualey Shimshon", "content": ""}, {"index": "32", "level": 4, "title": "Samson Unit", "content": ""}, {"index": "33", "level": 4, "title": "Shimshon Battalion 92nd Infantry Battalion of the Kfir Brigade", "content": ""}, {"index": "34", "level": 3, "title": "Military hardware", "content": ""}, {"index": "35", "level": 4, "title": "Samson Remote Controlled Weapon Station", "content": ""}, {"index": "36", "level": 4, "title": "FV106 Samson", "content": ""}, {"index": "37", "level": 4, "title": "Lockheed Martin C-130J Super Hercules", "content": ""}, {"index": "38", "level": 1, "title": "Explanatory notes", "content": ""}, {"index": "39", "level": 1, "title": "References", "content": ""}, {"index": "40", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Samson", "text": "Wikipedia"}]'::jsonb, '2026-01-1