INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67001, 'Baron_1898', 'en', 'Baron 1898 is a Dive Coaster produced by the Swiss manufacturer Bolliger & Mabillard located in Efteling in Kaatsheuvel, The Netherlands. It opened on July 1, 2015. The coaster''s soundtrack was composed by René Merkelbach and performed by the Brussels Philharmonic Orchestra.', '[{"index": "1", "level": 1, "title": "Story", "content": ""}, {"index": "2", "level": 1, "title": "Personnel", "content": ""}, {"index": "3", "level": 1, "title": "Ride", "content": ""}, {"index": "4", "level": 1, "title": "Reception", "content": ""}, {"index": "5", "level": 1, "title": "Incidents", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Baron_1898", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:09:40.948973+11:00', '2026-01-13 00:25:12.978191+11:00');
