INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67110, 'Rytterknægten', 'en', 'Rytterknægten is the highest point on the Danish island of Bornholm at 162 metres (531 ft) above sea level. The bierg is situated on a wooded bedrock of gaiter formations in the middle of Almindingen forest. Aakirkeby is located about 5 kilometres (3.1 mi) to the southeast.', '[{"index": "1", "level": 1, "title": "Etymology", "content": ""}, {"index": "2", "level": 1, "title": "Geography", "content": ""}, {"index": "3", "level": 1, "title": "Kongemindet", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Rytterkn%C3%A6gten", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:13:56.847817+11:00', '2026-01-13 00:25:12.984300+11:00');
