INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67263, 'Goodwood_Racecourse', 'en', 'Goodwood Racecourse is a horse-racing track five miles north of Chichester, West Sussex, in England controlled by the family of the Duke of Richmond, whose seat is nearby Goodwood House. It hosts the annual Glorious Goodwood meeting in late July and early August, which is one of the highlights of the British flat racing calendar, and is home to three of the UK''s 36 annual Group 1 flat races, the Sussex Stakes, the Goodwood Cup and the Nassau Stakes. Although the race meeting has become known as ''Glorious Goodwood'', it is sponsored by Qatar and officially called the ''Qatar Goodwood Festival''.', '[{"index": "1", "level": 1, "title": "Notable races", "content": "Notable races[edit] Month Meeting DOW Race Name Type Grade Distance Age/sex May Spring Meeting Saturday Daisy Warwick Stakes Flat Listed 1m 4f 4yo + f May Spring Meeting Thursday Height of Fashion Stakes Flat Listed 1m 1f 192y 3yo only f May Spring Meeting Friday Cocked Hat Stakes Flat Listed 1m 3f 3yo only July–August Glorious Festival Tuesday Molecomb Stakes Flat Group 3 5f 2yo only July–August Glorious Festival Tuesday Lennox Stakes Flat Group 2 7f 3yo + July–August Glorious Festival Wednesday Vintage Stakes Flat Group 2 7f 2yo only July–August Glorious Festival Wednesday Gordon Stakes Flat Group 3 1m 4f 3yo only July–August Glorious Festival Wednesday Sussex Stakes Flat Group 1 1m 3yo + July–August Glorious Festival Thursday Richmond Stakes Flat Group 2 6f 2yo only July–August Glorious Festival Thursday Lillie Langtry Stakes Flat Group 2 1m 6f 3yo + f July–August Glorious Festival Thursday Goodwood Cup Flat Group 1 2m 3yo + July–August Glorious Festival Friday Oak Tree Stakes Flat Group 3 7f 3yo + f July–August Glorious Festival Friday King George Stakes Flat Group 2 5f 3yo + July–August Glorious Festival Friday Thoroughbred Stakes Flat Group 3 1m 3yo only July–August Glorious Festival Friday Glorious Stakes Flat Group 3 1m 4f 4yo + July–August Glorious Festival Saturday Stewards'' Cup Flat Handicap 6f 3yo + July–August Glorious Festival Saturday Nassau Stakes Flat Group 1 1m 1f 192y 3yo + f August August Meeting Sunday Celebration Mile Flat Group 2 1m 3yo + August August Meeting Sunday Prestige Stakes Flat Group 3 7f 2yo only f September Autumn Meeting Wednesday Foundation Stakes Flat Listed 1m 1f 192y 3yo + September Autumn Meeting Tuesday Stardom Stakes Flat Conditions 7f 2yo only Other races Conqueror Stakes Festival Stakes On The House Stakes Starlit Stakes Tapster Stakes"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} Works cited[edit] .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser