INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62669, '红石林国家地质公园', 'en', '红石林国家地质公园是中国湖南省湘西土家族苗族自治州古丈县红石林镇的国家地质公园。園內有罕見的紅色碳酸鹽岩石林，形成於奧陶紀，石林顏色會隨季節和天氣改變。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67496, 'Rocha_dos_Namorados', 'en', 'The Rocha dos Namorados is a large upright granite stone located in the parish of Corval, municipality of Reguengos de Monsaraz, in the Évora District of the Alentejo region of Portugal. It is sometimes considered to be a menhir or standing stone but there is no evidence of it having been placed at the site and it seems to be a natural outcrop, although it does have some dimpled, megalithic engravings, as well as a cross, which is believed to have been carved in order to Christianise what was an ancient ritual. It is considered a rare example of the veneration of stones associated with a secular, pagan fertility rite that has continued to the present.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} @media screen{html.skin-theme-clientpref-night .mw-parser-output .sister-inline-image img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sister-inline-image img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}} Media related to Reguengos de Monsaraz.mw-parser-output .preview-warning{font-style:italic;padding-left:1.6em;margin-bottom:0.5em;color:var(--color-error,red)}.mw-parser-output .preview-warning+link+.preview-warning{margin-top:-0.5em}Preview warning: Commons link does not match Wikidata – please check at Wikimedia Commons"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Rocha_dos_Namorados", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.008983+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67498, 'Empowerment', 'en', 'Empowerment is the degree of autonomy and self-determination in people and in communities. This enables them to represent their interests in a responsible and self-determined way, acting on their own authority. It is the process of becoming stronger and more confident, especially in controlling one''s life and claiming one''s rights. Empowerment as action refers both to the process of self-empowerment and to professional support of people, which enables them to overcome their sense of powerlessness and lack of influence, and to recognize and use their resources.', '[{"index": "1", "level": 1, "title": "Definitions", "content": ""}, {"index": "2", "level": 1, "title": "Process", "content": ""}, {"index": "3", "level": 2, "title": "Strategy", "content": ""}, {"index": "4", "level": 2, "title": "Criticism", "content": ""}, {"index": "5", "level": 1, "title": "In social work and community psychology", "content": ""}, {"index": "6", "level": 2, "title": "In health promotion practice and research", "content": ""}, {"index": "7", "level": 1, "title": "In economics", "content": ""}, {"index": "8", "level": 2, "title": "Consumer empowerment", "content": ""}, {"index": "9", "level": 2, "title": "Customer empowerment", "content": ""}, {"index": "10", "level": 2, "title": "Increasingly engaged corporate directors", "content": ""}, {"index": "11", "level": 1, "title": "Legal", "content": ""}, {"index": "12", "level": 1, "title": "Gender", "content": ""}, {"index": "13", "level": 1, "title": "In workplace management", "content": ""}, {"index": "14", "level": 2, "title": "Evolution", "content": ""}, {"index": "15", "level": 2, "title": "Implications for company culture", "content": ""}, {"index": "16", "level": 2, "title": "Criticisms", "content": ""}, {"index": "17", "level": 1, "title": "In artificial intelligence", "content": ""}, {"index": "18", "level": 1, "title": "\"Age of Popular Empowerment\"", "content": ""}, {"index": "19", "level": 1, "title": "See also", "content": ""}, {"index": "20", "level": 1, "title": "References", "content": ""}, {"index": "21", "level": 1, "title": "Further reading", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Empowerment", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.008983+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67503, 'Панский_дуб', 'en', 'Па́нский дуб — самое старое дерево Белгородчины, туристическая достопримечательность. Ботанический вид — дуб черешчатый. Дерево растёт у западной окраины села Яблочково Шебекинского района. Высота дуба — 35 метров, обхват — 5,5 метров, размах кроны — 25 метров. В 1968 году учёные-лесоводы определили его возраст — 500 лет. Сейчаc, соответственно, возраст дерева — 558 лет. Панский дуб включён в список памятников природы Белгородской области, с 2013 года — в список России.', '[{"index": "1", "level": 1, "title": "История", "content": "История[править | править код] Естественные леса, занимали в начале XVII века около 30&#160;% территории области&#91;1&#93;. Большинство лесов, а это были в основном дубовые, вырублены для строительства Белгородской засечной черты и городов-крепостей. На это ушли тысячи лучших дубов. И лишь один сохранился. Его пощадил и огонь кочевников, и топор русского человека. По одной из легенд, в 1709 году Пётр Первый, возвращаясь с Полтавской битвы, осматривал водяные мельницы на реке Короча, останавливался и отдыхал под тенью могучего дуба. Дерево чуть не погибло во время Великой Отечественной войны: немцы хотели его сжечь, но их планы не осуществились в связи со стремительным наступлением Красной Армии&#91;2&#93;. Во второй половине XIX века возле легендарного дуба помещиком И. Н. Гангардтом — предводителем корочанского дворянства, был заложен фруктовый сад на 106 десятинах. Сад у «500-летнего дуба» был признан лучшим в России и отмечен 6-ю золотыми медалями на выставках в Санкт-Петербурге. Сохранилось и здание школы садоводов. В 2013 году дуб получил федеральный охранный статус в рамках всероссийской программы «Деревья — памятники природы», которая осуществляется при поддержке Совета по сохранению природного наследия нации в Совете Федерации&#91;3&#93;. Сейчас дерево находится в хорошем состоянии: его регулярно осматривают представители Шебекинского лесхоза и проводят необходимые санитарно-оздоровительные процедуры. «Панский дуб», как называют его местные жители, является одной из достопримечательностей Шебекинского района. Место, где находится дерево&#160;— особо охраняемая территория регионального значения&#91;3&#93;&#91;4&#93;. Так как дерево находится между сёлами Яблочково и Дмитриевка и, хотя к Яблочково оно, безусловно, ближе — дуб иногда называют Дмитриевским. ↑ Чендев Ю. Г. Тренды развития ландшафтов и почв Центральной лесостепи во второй половине голоцена// Проблемы эволюции почв — Пущино: 2003. ↑ Передерий В. Там, где Корень… Архивная копия от 2 февраля 2014 на Wayback Machine // «Смена», 11.01.2012 ↑ 1 2 Пятисотлетний дуб в Белгородской области стал памятником природы ↑ Дуб черешчатый, анкета №&#160;231&#160;.&#32;Дата обращения: 21 августа 2013.&#32;Архивировано 16 января 2014 года."}, {"index": "2", "level": 1, "title": "См. также", "content": "См. также[править | править код] .mw-parser-output .ts-Родственные_проекты{clear:right;float:right;width:19em;box-sizing:border-box;margin:0 0 .5em 1em;padding:.4em;background:var(--background-color-neutral-subtle,#f8f9fa);border:1px solid var(--border-color-base,#a2a9b1);font-size:90%}.mw-parser-output .ts-Родственные_проекты-header{margin-bottom:.2em;padding:.2em .6em;font-size:110%}.mw-parser-output .ts-Родственные_проекты-item{display:flex;padding:.2em .6em}.mw-parser-output .ts-Родственные_проекты-image{min-width:24px;display:inline-block;margin-right:.4em;flex:none;vertical-align:top;text-align:center}.mw-parser-output .ts-Родственные_проекты-image img{vertical-align:middle}.mw-parser-output .ts-Родственные_проекты-label{align-self:center}@media(max-width:719px){.mw-parser-output .ts-Родственные_проекты{clear:none;float:none;width:auto;margin-left:0;margin-right:0}}Медиафайлы на&#160;Викискладе Список старейших деревьев Титовский бор"}, {"index": "3", "level": 1, "title": "Примечания", "content": "Примечания[править | править код]"}, {"index": "4", "level": 1, "title": "Ссылки", "content": "Ссылки[править | править код] Дуб-долгожитель (rosleshoz.gov.ru) Уникальный черешчатый Дуб (rosdrevo.ru) Знаменитый дуб в Дубовом признали национальным достоянием (youtube.com) Знаменитые деревья ЕвропыРеальныеДубы Астраханский Бартек Баублис Балта-Тиймез Богатырь Тавриды Вардана Мамиконяна Вёшенский Гранитский Грюневальда Гунали Дубовский Запорожский Ивана Франко (Коломыя) Ивана Франко (Стрый) Императорский (Берлин) Кайвский Калининградской области «Космос» Кристера Максима Железняка Немировский Орловщины Панский Пугачёва Пушкинский (Москва) Ракоци Румскулла С пирамидально-кипарисовидной кроной (Грозный) Смерти (Махно) Собеского Старожил (Киров) Стелмужский Стефана Великого Суворова Тамме-Лаури Часовня (Франция) Чувашии Янаты Дубы 6-го ноября Липы Гигантская липа в Хеде Липа Наполеона Липа Петра Могилы Липа в Ростове-на-Дону Каштаны Анны Франк Каштан Петра Могилы Каштан сотни лошадей Пятиствольный каштан Хвойные Ель Старый Тикко Тис Ллангернивский Тис Фортингэльский Другие Берёза в Смоленске Ветла Марии Вяз Ведьмак Вяз в Жизоре Маслина Геродота Орех Пузанова Орех Юрия Никулина Платан в Монсо (Париж) Платан Палласа Самшит в Алуште Тополь в Волгограде Тополь (Калмыкия) Фисташка Биберштейна Фисташка Юстиниана Дерево Цоя Шелковица Гиреев Яблоня-колония Вымышленные Белое Древо Гондора Гремучая ива Два Древа Валинора Иггдрасиль Ирминсуль Мировое древо Старая Ива Собирательные образы Дерево Герники Дуб Памяти Царь-дуб Национальное дерево Украины"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%9F%D0%B0%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D1%83%D0%B1", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.008983+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67504, 'Vicent', 'en', 'Vicent is both a surname and a given name. Notable people with the name include:', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] 78071 Vicent, main-belt asteroid Casa Vicent, historic house in Porto, Portugal Cala de Sant Vicent, holiday resort on Ibiza .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} Name listThis page or section lists people that share the same given name or the same family name. If an internal link led you here, you may wish to change that link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Vicent", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.008983+11:00');
