INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67563, 'Самар', 'en', 'Samar is an island in the Visayas group in the Philippines.', '[{"index": "1", "level": 1, "title": "People", "content": ""}, {"index": "2", "level": 1, "title": "Places", "content": ""}, {"index": "3", "level": 2, "title": "The Philippines", "content": ""}, {"index": "4", "level": 2, "title": "Israel", "content": ""}, {"index": "5", "level": 2, "title": "Ukraine", "content": ""}, {"index": "6", "level": 1, "title": "Film and television", "content": ""}, {"index": "7", "level": 1, "title": "Others", "content": ""}, {"index": "8", "level": 1, "title": "See also", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Samar_(disambiguation)", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.015196+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67575, 'Палаты_Кожевенной_слободы', 'en', 'Палаты Кожевенной слободы — палаты в Москве по адресу Кожевническая улица, дом 19, строение 6. Объект культурного наследия федерального значения.', '[{"index": "1", "level": 1, "title": "История", "content": "История[править | править код] Палаты и выполненная в советское время пристройка Кожевенная слобода в Москве сформировалась в XVI веке, палаты скорее всего относились к ней и являются старейшим сохранившимся от слободы зданием. Кирпичный двухэтажный дом стоит в глубине владения, ближе к Москве-реке. Судя по характеру архитектуры здание относится к концу XVII&#160;века, об этом свидетельствуют кубический объём дома, увенчанный четырёхскатной крышей с высокими дымниками, узкие маленькие окна. Весь объём первого этажа занимает большая палата с одним столпом (несущей колонной). Предназначение палат доподлинно неизвестно. Второй этаж мог служить для жилья, в то время как на первом могло располагаться производство, храниться товар или осуществляться управление деятельностью слободы&#91;1&#93;. С западной и южной сторон у второго этажа имелось два отдельных входа, возле них хорошо сохранились ниши для свечей-фонарей. Оформление этажа богаче: окна украшены кирпичными наличниками с колонками и треугольными многопрофильными фронтонами. Между этажами выполнен горизонтальный пояс с поребриком. Кровля выходит далеко за плоскость стен, под ней проходит трехчастный кирпичный карниз&#91;1&#93;. После того как Пётр I уничтожил слободское устройство Москвы, в здании палат разместился мытный двор (городская таможня). Рядом с палатами (в районе современного Новоспасского моста) находилась паромная переправа через Москву-реку, за пользование которой и ввоз товаров в город купцы платили налог (мыт). В XIX&#160;веке в палаты занимали различные государственные учреждения, затем они сдавались в аренду&#91;1&#93;. В 1920-х годах здание переделали в общежитие на несколько десятков человек. Были разобраны столп в центре палат и своды второго этажа, к палатам добавили двухэтажную пристройку, от которой длина дома выросла в два раза. В 1970-х годах был проект сноса дома и постройки на этом месте Центральной насосной станции, однако благодаря реставраторам палаты уцелели. Был восстановлен столп, выполнен ремонт кровли и самого дома. С 1983 года до конца 2010-х в здании располагалось издательство журнала «Знание — сила»&#91;1&#93;. В настоящее время палаты закрыты и заброшены. ↑ 1 2 3 4 Ошибка в сносках?:&#x20;Неверный тег &lt;ref&gt;; для сносок Узнай Москву не указан текст"}, {"index": "2", "level": 1, "title": "Галерея", "content": "Галерея[править | править код]"}, {"index": "3", "level": 1, "title": "Примечания", "content": "Примечания[править | править код] Ошибка в сносках?:&#x20;Тег &lt;ref&gt; с именем «Реестр», определённый в &lt;references&gt;, не используется в предшествующем тексте. Ошибка в сносках?:&#x20;Тег &lt;ref&gt; с именем «Узнай Москву», определённый в &lt;references&gt;, не используется в предшествующем тексте."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%9F%D0%B0%D0%BB%D0%B0%D1%82%D1%8B_%D0%9A%D0%BE%D0%B6%D0%B5%D0%B2%D0%B5%D0%BD%D0%BD%D0%BE%D0%B9_%D1%81%D0%BB%D0%BE%D0%B1%D0%BE%D0%B4%D1%8B", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.015196+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67581, 'Андерсенград', 'en', 'Андерсенград — детский игровой комплекс в городе Сосновый Бор, открытый в 1980 году и посвящённый 175-летию сказочника Ханса Кристиана Андерсена.', '[{"index": "1", "level": 1, "title": "История", "content": ""}, {"index": "2", "level": 1, "title": "Архитектурный ансамбль", "content": ""}, {"index": "3", "level": 1, "title": "Скульптура", "content": ""}, {"index": "4", "level": 1, "title": "Культурная программа", "content": ""}, {"index": "5", "level": 1, "title": "Реставрации", "content": ""}, {"index": "6", "level": 1, "title": "Вандализм", "content": ""}, {"index": "7", "level": 1, "title": "Литература", "content": ""}, {"index": "8", "level": 1, "title": "Примечания", "content": ""}, {"index": "9", "level": 1, "title": "Ссылки", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%90%D0%BD%D0%B4%D0%B5%D1%80%D1%81%D0%B5%D0%BD%D0%B3%D1%80%D0%B0%D0%B4", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.015196+11:00');
