INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62671, 'Pingjiang_Road', 'en', 'Pingjiang Road, historically known as Shiquan Li (Chinese:十泉里), is a street and historic district in Gusu District, northeastern Suzhou, Jiangsu, China. It is a well-preserved area and is part of the so-called Old Town of Suzhou.', '[{"index": "1", "level": 1, "title": "Overview", "content": "Overview[edit] The main street (Pingjiang Road) is located along Pingjiang He (Chinese:平江河) and is 1,606 metres (5,269&#160;ft) in length. It stretches from Ganjiang Donglu (Chinese:干将东路) in the south to Baita Road East (Chinese:白塔东路) in the northwest, near the Humble Administrator''s Garden and Suzhou Museum. The entire historic district covers an area of 0.4 square kilometres (0.15&#160;sq&#160;mi).&#91;1&#93; The city of Suzhou was known as Pingjiang during Southern Song dynasty. As a major thoroughfare of eastern Suzhou back then, the street carries on the former name of the city. It was featured in the map Pingjiang Tu (Chinese:平江图), produced in the year 1229.&#91;2&#93;&#91;3&#93; There are 51 smaller alleys intersecting the street. There are also about 3 kilometres (1.9&#160;mi) of canals within the historic district.&#91;2&#93;&#91;3&#93;&#91;4&#93; In 2009, Pingjiang Road was listed as a Zhongguo Lishi Wenhua Mingjie (Chinese:中国历史文化名街, literally: Famous historical and cultural street of China), one of the first nine streets with such title across China.&#91;5&#93; Along with Shantang Street, the area was also declared a Zhongguo Lishi Wenhua Jiequ (Chinese:中国历史文化街区, literally: Historical and cultural block of China) in 2015.&#91;6&#93; A BBC Travel article describes Pingjiang Road as less touristy than Shantang Street and states that it is \"lined with houses that embody Suzhou’s style – graceful, simple and timeless. Pingjiang Road gives an insight into the leisurely existence of the city’s residents. [It is a] centre of Suzhou''s artistic life, lined with bookshops and local opera theatres. There are also several teahouses, where people gather for performances of traditional storytelling and ballad singing\".&#91;7&#93; Couple''s Retreat Garden (Ou Yuan), a noted Classical Garden located within the historic district, is part of the UNESCO World Heritage Site Classical Gardens of Suzhou. Guanqian Street is also in walking distance. There are two national-class and 12 provincial-class protection units within the historic district. Pingjiang Road undergone a major renovation prior to the 28th Session of the World Heritage Committee which took place in Suzhou in 2004.&#91;8&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"平江路简介\". Retrieved 24 July 2016. ^ a b \"Pingjiang Road – A Historic Street in Suzhou\". Retrieved 24 July 2016. ^ a b \"平江路的历史\". Retrieved 24 July 2016. ^ \"苏州平江路 古老街巷中的新契机(图)\". Retrieved 24 July 2016. ^ \"苏州平江路：原汁原味保护，传承\"吴文化\"精髓\". Retrieved 25 July 2016. ^ \"苏州平江路、山塘街被认定为首批\"中国历史文化街区\"\". Retrieved 26 July 2016. ^ \"Suzhou: China''s Canal Capital\". Retrieved 26 November 2018. ^ \"平江历史文化街区概况\". Archived from the original on 26 August 2016. Retrieved 25 July 2016."}, {"index": "2", "level": 1, "title": "Bridges within the district", "content": ""}, {"index": "3", "level": 1, "title": "The story of Hong Jun and Sai Jinhua", "content": ""}, {"index": "4", "level": 1, "title": "Transportation", "content": ""}, {"index": "5", "level": 1, "title": "Gallery", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Pingjiang_Road", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:50:40.353031+11:00', '2026-01-13 00:25:12.703572+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67595, 'Miravet', 'en', 'Miravet is a municipality in the comarca of Ribera d''Ebre in the Province of Tarragona, Catalonia, Spain. It has a population of 703 .', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] In the Spanish Civil War of 1936-1939 it was one of the scenes of the Battle of the Ebro. The 4th November 1938, the fascists occupied Miravent and continued east of the Ebro river.Ebre in Miravet"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "3", "level": 1, "title": "External links", "content": "External links[edit] Government data pages (in Catalan) .mw-parser-output .navbox{box-sizing:border-box;border:1px sol