INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67607, 'Solitude', 'en', 'Solitude, also known as social withdrawal, is a state of seclusion or isolation, meaning lack of socialisation. Effects can be either positive or negative, depending on the situation. Short-term solitude is often valued as a time when one may work, think, or rest without disturbance. It may be desired for the sake of privacy. Long-term solitude may stem from soured relationships, loss of loved ones, deliberate choice, infectious disease, mental disorders, neurological disorders such as circadian rhythm sleep disorder, or circumstances of employment or situation.', '[{"index": "1", "level": 1, "title": "Health effects", "content": ""}, {"index": "2", "level": 1, "title": "Psychological effects", "content": ""}, {"index": "3", "level": 2, "title": "Positive effects", "content": ""}, {"index": "4", "level": 2, "title": "Negative effects", "content": ""}, {"index": "5", "level": 1, "title": "Other uses", "content": ""}, {"index": "6", "level": 2, "title": "As pleasure", "content": ""}, {"index": "7", "level": 2, "title": "As punishment", "content": ""}, {"index": "8", "level": 1, "title": "See also", "content": ""}, {"index": "9", "level": 1, "title": "References", "content": ""}, {"index": "10", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Solitude", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:24:54.268048+11:00', '2026-01-13 00:25:13.015196+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67648, 'Balnica', 'en', 'Balnica is a former village in the administrative district of Gmina Komańcza, within Sanok County, in the Subcarpathian Voivodeship (province) of south-eastern Poland, close to the border with Slovakia. It lies approximately 18 km (11 mi) south-east of Komańcza, 38 km (24 mi) south of Sanok, and 92 km (57 mi) south of the regional capital Rzeszów.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Komancza Republic (November 1918 – January 1919)"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "3", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output .side-box{m