INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67656, 'Львовский_дворец', 'en', 'Льво́вский дворец — псевдоготический дворец в посёлке Стрельна в Петродворцовом районе Санкт-Петербурга.', '[{"index": "1", "level": 1, "title": "История", "content": ""}, {"index": "2", "level": 1, "title": "Архитектура", "content": ""}, {"index": "3", "level": 1, "title": "Современное состояние", "content": ""}, {"index": "4", "level": 1, "title": "Галерея", "content": ""}, {"index": "5", "level": 1, "title": "Примечания", "content": ""}, {"index": "6", "level": 1, "title": "Ссылки", "content": ""}, {"index": "7", "level": 1, "title": "Литература", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%9B%D1%8C%D0%B2%D0%BE%D0%B2%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:31:45.027801+11:00', '2026-01-13 00:25:13.022383+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67669, 'Døndalen', 'en', 'Døndalen is a valley in the northern part of the Danish island of Bornholm. Located next to the road from Gudhjem to Tejn, it is known for its waterfall, which is Denmark''s tallest.', '[{"index": "1", "level": 1, "title": "Description", "content": "Description[edit] Døndalen, which covers an area of 37 hectares (91 acres), is one of Bornholm''s crack valleys cutting through the granite rock. The wooded area reaches inland from the coast. In springtime the valley is covered with anemones and ramsons, and the song of nightingales can sometimes be heard.&#91;1&#93; ^ \"Døndalen på Bornholm\", Danmarks Naturfond. (in Danish) Retrieved 31 October 2012."}, {"index": "2", "level": 1, "title": "Background", "content": "Background[edit] Døndalen has been wooded since the last ice age, 10,000 years ago. Over the past 7,000 years, the trees have been deciduous. There have been various archeological finds in the valley including burial sites and evidence of cremations. It is not known how a sword in a wooden sheath and gilded pearls of glass arrived there. As part of the island''s defences in the 16th century, earthworks were constructed at the bottom of the valley next to the shore. The embankments, which can still be seen today, provided protection for those using canons and rifles to deter the enemy.&#91;1&#93; ^ Cite error: The named reference naturpdf was invoked but never defined (see the help page)."}, {"index": "3", "level": 1, "title": "Landscape", "content": ""}, {"index": "4", "level": 1, "title": "Fauna and flora", "content": ""}, {"index": "5", "level": 1, "title": "Signposted walks", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/D%C3%B8ndalen", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:31:45.027801+11:00', '2026-01-13 00:25:13.022383+11:00');
