INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67674, 'Veturi', 'en', 'Veturi Sundararama Murthy, known mononymously by his surname Veturi, was an Indian poet and lyricist who is known for his works in Telugu literature and cinema. Veturi is a recipient of the National Film Award, various Nandi Awards, Filmfare Awards, and other state honors. His career in Telugu cinema spanned more than four decades.', '[{"index": "1", "level": 1, "title": "Early life", "content": ""}, {"index": "2", "level": 2, "title": "Education", "content": ""}, {"index": "3", "level": 1, "title": "Career as a journalist", "content": ""}, {"index": "4", "level": 1, "title": "Career as a lyricist", "content": ""}, {"index": "5", "level": 2, "title": "Entry into films", "content": ""}, {"index": "6", "level": 2, "title": "1970s", "content": ""}, {"index": "7", "level": 2, "title": "1980s", "content": ""}, {"index": "8", "level": 2, "title": "1990s", "content": ""}, {"index": "9", "level": 2, "title": "2000s", "content": ""}, {"index": "10", "level": 1, "title": "Awards and honors", "content": ""}, {"index": "11", "level": 2, "title": "National Awards", "content": ""}, {"index": "12", "level": 2, "title": "Filmfare Awards", "content": ""}, {"index": "13", "level": 2, "title": "Nandi Awards", "content": ""}, {"index": "14", "level": 2, "title": "Manaswini Awards", "content": ""}, {"index": "15", "level": 1, "title": "Filmography", "content": ""}, {"index": "16", "level": 2, "title": "1970s", "content": ""}, {"index": "17", "level": 2, "title": "1980s", "content": ""}, {"index": "18", "level": 2, "title": "1990s", "content": ""}, {"index": "19", "level": 2, "title": "2000s", "content": ""}, {"index": "20", "level": 1, "title": "Books", "content": ""}, {"index": "21", "level": 2, "title": "<i>Sirikaakolanu Chinnadi</i>", "content": ""}, {"index": "22", "level": 2, "title": "<i>Komma Kommako Sannaayi</i>",