INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68132, 'Lech_Coaster', 'en', 'Lech Coaster is a steel roller coaster located at Legendia in Chorzów, Poland. It was the first Bermuda Blitz coaster by Dutch manufacturer Vekoma and opened on July 1, 2017. The ride stands 40 metres (130 ft) tall, has a maximum speed of 95 kilometres per hour (59 mph), and has a track length of 908 metres (2,979 ft). The ride also features three inversions.', '[{"index": "1", "level": 1, "title": "Characteristics", "content": ""}, {"index": "2", "level": 2, "title": "Trains", "content": ""}, {"index": "3", "level": 2, "title": "Track", "content": ""}, {"index": "4", "level": 1, "title": "Ride experience", "content": ""}, {"index": "5", "level": 2, "title": "Layout", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Lech_Coaster", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:46:12.687380+11:00', '2026-01-13 00:25:13.056816+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68141, 'el_Castellet', 'en', 'El Castellet is a hamlet located in the municipality of Tremp, in Province of Lleida province, Catalonia, Spain. As of 2020, it has a population of 12.', '[{"index": "1", "level": 1, "title": "Geography", "content": "Geography[edit] El Castellet is located 111km north-northeast of Lleida."}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .asbox{position:relative;overflow:hidden}.mw-parser-output .asbox table{background:transparent}.mw-parser-output .asbox p{margin:0}.mw-parser-output .asbox p+p{margin-top:0.25em}.mw-parser-output .asbox-body{font-style:italic}.mw-parser-output .asbox-note{font-size:smaller}.mw-parser