INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68311, 'Tornado', 'en', 'A tornado, also known as a twister, is a rapidly rotating column of air that extends vertically from the surface of the Earth to the base of a cumulonimbus or cumulus cloud. Tornadoes are often visible in the form of a condensation funnel originating from the cloud base, with a cloud of rotating debris and dust close to the ground. Most tornadoes have wind speeds less than 180 kilometers per hour, are about 80 meters across, and travel several kilometers before dissipating. The most extreme tornadoes can attain wind speeds of more than 480 kilometers per hour (300 mph), can be more than 3 kilometers (2 mi) in diameter, and can stay on the ground for more than 100 km (62 mi).', '[{"index": "1", "level": 1, "title": "Rating", "content": ""}, {"index": "2", "level": 1, "title": "Etymology", "content": ""}, {"index": "3", "level": 1, "title": "Definitions", "content": ""}, {"index": "4", "level": 2, "title": "Funnel cloud", "content": ""}, {"index": "5", "level": 2, "title": "Outbreaks and families", "content": ""}, {"index": "6", "level": 1, "title": "Characteristics", "content": ""}, {"index": "7", "level": 2, "title": "Size and shape", "content": ""}, {"index": "8", "level": 2, "title": "Track length", "content": ""}, {"index": "9", "level": 2, "title": "Appearance", "content": ""}, {"index": "10", "level": 2, "title": "Rotation", "content": ""}, {"index": "11", "level": 2, "title": "Sound and seismology", "content": ""}, {"index": "12", "level": 2, "title": "Electromagnetic, lightning, and other effects", "content": ""}, {"index": "13", "level": 1, "title": "Life cycle", "content": ""}, {"index": "14", "level": 2, "title": "Supercell relationship", "content": ""}, {"index": "15", "level": 2, "title": "Formation", "content": ""}, {"index": "16", "level": 2, "title": "Maturity", "content": ""}, {"index": "17", "level": 2, "title": "Dissipation", "content": ""}, {"index": "18", "level": 1, "title": "Types", "content": ""}, {"index": "19", "level": 2, "title": "Multiple vortex", "content": ""}, {"index": "20", "level": 2, "title": "Waterspout", "content": ""}, {"index": "21", "level": 2, "title": "Landspout", "content": ""}, {"index": "22", "level": 2, "title": "Similar circulations", "content": ""}, {"index": "23", "level": 3, "title": "Gustnado", "content": ""}, {"index": "24", "level": 3, "title": "Dust devil", "content": ""}, {"index": "25", "level": 3, "title": "Fire whirls", "content": ""}, {"index": "26", "level": 3, "title": "Steam devils", "content": ""}, {"index": "27", "level": 1, "title": "Intensity and damage", "content": ""}, {"index": "28", "level": 1, "title": "Climatology", "content": ""}, {"index": "29", "level": 2, "title": "Associations with climate and climate change", "content": ""}, {"index": "30", "level": 1, "title": "Detection", "content": ""}, {"index": "31", "level": 2, "title": "Radar", "content": ""}, {"index": "32", "level": 2, "title": "Storm spotting", "content": ""}, {"index": "33", "level": 2, "title": "Visual evidence", "content": ""}, {"index": "34", "level": 1, "title": "Extremes", "content": ""}, {"index": "35", "level": 1, "title": "Safety", "content": ""}, {"index": "36", "level": 1, "title": "Myths and misconceptions", "content": ""}, {"index": "37", "level": 1, "title": "Ongoing research", "content": ""}, {"index": "38", "level": 1, "title": "See also", "content": ""}, {"index": "39", "level": 1, "title": "References", "content": ""}, {"index": "40", "level": 1, "title": "Further reading", "content": ""}, {"index": "41", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Tornado", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:51:31.243027+11:00', '2026-01-13 00:25:13.063152+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68319, 'Speakers''_Corner', 'en', 'A Speakers'' Corner is an area where free speech open-air public speaking, debate, and discussion are allowed. The original and best known is in the north-east corner of Hyde Park in London, England. Historically there were a number of other areas designated as Speakers'' Corners in other parks in London, such as Lincoln''s Inn Fields, Finsbury Park, Clapham Common, Kennington Park, and Victoria Park. Areas for Speakers'' Corners have been established elsewhere in the United Kingdom and in other countries.', '[{"index": "1", "level": 1, "title": "Hyde Park", "content": ""}, {"index": "2", "level": 2, "title": "Noted speakers", "content": ""}, {"index": "3", "level": 1, "title": "Outside London", "content": ""}, {"index": "4", "level": 2, "title": "Official", "content": ""}, {"index": "5", "level": 3, "title": "Southampton", "content": ""}, {"index": "6", "level": 3, "title": "Nottingham", "content": ""}, {"index": "7", "level": 3, "title": "Lichfield, Staffordshire", "content": ""}, {"index": "8", "level": 3, "title": "Worthing, West Sussex", "content": ""}, {"index": "9", "level": 2, "title": "Unofficial", "content": ""}, {"index": "10", "level": 3, "title": "Leeds", "content": ""}, {"index": "11", "level": 3, "title": "Newcastle", "content": ""}, {"index": "12", "level": 3, "title": "Portsmouth", "content": ""}, {"index": "13", "level": 1, "title": "Other countries", "content": ""}, {"index": "14", "level": 2, "title": "Australia", "content": ""}, {"index": "15", "level": 2, "title": "Canada", "content": ""}, {"index": "16", "level": 2, "title": "Hong Kong", "content": ""}, {"index": "17", "level": 2, "title": "Indonesia", "content": ""}, {"index": "18", "level": 2, "title": "Italy", "content": ""}, {"index": "19", "level": 2, "title": "Malaysia", "content": ""}, {"index": "20", "level": 2, "title": "Netherlands", "content": ""}, {"index": "21", "level": 2, "title": "New Zealand", "content": ""}, {"index": "22", "level": 2, "title": "Singapore", "content": ""}, {"index": "23", "level": 2, "title": "Thailand", "content": ""}, {"index": "24", "level": 2, "title": "Trinidad and Tobago", "content": ""}, {"index": "25", "level": 2, "title": "United States", "content": ""}, {"index": "26", "level": 1, "title": "Books and articles", "content": ""}, {"index": "27", "level": 1, "title": "Media references", "content": ""}, {"index": "28", "level": 1, "title": "See also", "content": ""}, {"index": "29", "level": 1, "title": "References", "content": ""}, {"index": "30", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Speakers''_Corner", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:51:31.243027+11:00', '2026-01-13 00:25:13.063152+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68323, 'British_Music_Experience', 'en', 'The British Music Experience is a permanent exhibition in the Cunard Building on Liverpool''s waterfront. It began as an exhibition, taking up more than 20,000 square feet, installed into The O2 Bubble, part of The O2 in Greenwich, London. Opened with a private concert by The View in March 2009, it featured a retrospective look at the British music industry since 1944. The museum closed on 30 April 2014 and announced it was looking for a new home. On 10 September 2015 it was confirmed that the new home for the British Music Experience would be the Cunard Building on Liverpool''s waterfront.', '[{"index": "1", "level": 1, "title": "Galleries", "content": ""}, {"index": "2", "level": 1, "title": "Artefacts and Memorabilia", "content": ""}, {"index": "3", "level": 1, "title": "Interactive Instrument Studio", "content": ""}, {"index": "4", "level": 1, "title": "Learning and public programmes", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/British_Music_Experience", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:51:31.243027+11:00', '2026-01-13 00:25:13.072441+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68334, '221B_Baker_Street', 'en', '221B Baker Street is the London address of the fictional detective Sherlock Holmes, created by author Sir Arthur Conan Doyle. In the United Kingdom, postal addresses with a number followed by a letter may indicate a separate address within a larger, often residential building. Baker Street in the late 19th century was a high-class residential district, and Holmes''s apartment would probably have been part of a Georgian terrace.', '[{"index": "1", "level": 1, "title": "Doyle''s intentions", "content": ""}, {"index": "2", "level": 1, "title": "Real 221B Baker Street addresses", "content": ""}, {"index": "3", "level": 2, "title": "Abbey National", "content": ""}, {"index": "4", "level": 2, "title": "Sherlock Holmes Museum", "content": ""}, {"index": "5", "level": 2, "title": "Address controversy", "content": ""}, {"index": "6", "level": 1, "title": "In other media", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/221B_Baker_Street", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:51:31.243027+11:00', '2026-01-13 00:25:13.072441+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68340, 'Double_Tower', 'en', 'The Double Tower is one of the 17 towers which were part of the city walls of Waterford, Munster, Ireland. It was built in the latter part of the 15th century and the early part of the 16th century. Six of the original 17 towers survive to this day; the other five being Reginald''s Tower, Beach Tower, Semi-Lunar Tower, French Tower, and Watch Tower (Waterford). The Double Tower is located on Castle Street, between the French Tower and the Watch Tower. All three towers are well-preserved, along with some parts of the old city wall between them.', '[{"index": "1", "level": 1, "title": "Layout", "content": "Layout[edit] The name Double Tower probably originates from the fact that there are two chambers inside it. One chamber contains a passageway which leads to the Benedictine Priory; the other, bigger chamber used to contain a flight of stairs leading to the upper floors and battlements.&#91;1&#93; The Benedictine Priory was the priory of St. John and was owned by the Benedictine priory of St. Peter and Paul of Bath in England. Along with the citizens of Waterford, this priory funded the construction of the towers and walls in this part of the city.&#91;2&#93; The Double Tower is oblong in plan, measuring 7m in length in the northwest-southeast direction, and 4.5m in width. Its height is 10.5m. It looks like mini-tower house, joined at either end by the city wall. However, habitation was not the primary function of this building. The city wall at either end abuts onto the exterior of the tower. This indicates that the tower was built earlier, and was originally a freestanding structure.&#91;2&#93; During the Cromwellian siege of 1649, this tower and sections of the city wall were pounded with cannon fire. The tower was not built for this type of defence, so it required bolstering by half-filling with earth to take the impact of the cannon.&#91;3&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Double Tower\". Archived from the original on 21 November 2014. ^ a b Cite error: The named reference Decies Journal was invoked but never defined (see the help page). ^ Eamon McEneaney, Discover Waterford, (O''Brien Press), 2001, p.99"}, {"index": "2", "level": 1, "title": "City wall", "content": "City wall[edit] Parts of the parapet in the section of the city wall to the southeast of the tower have survived to this day. However, at the northwest end, the original stepped crenellations can still be seen rising upwards to abut onto the tower. This feature is a rare survival on the Waterford city wall. The remains of an overhanging wall walk can still be seen running along the inside of the wall between the Double Tower and the Watch Tower. However, the battlement does not survive along the top of the city wall to the northwest of the Double Tower.&#91;1&#93; The Double Tower was built as a freestanding structure on the remains of an earlier gateway. The two adjoining sections of the city wall at either end were built later. It is likely that the section of the wall to the northwest that runs downhill from the French Tower was built first, and then the wall running southeast that goes to the Watch Tower.&#91;1&#93; All three towers are visible from Castle Street.&#91;citation needed&#93; ^ a b Cite error: The named reference Decies Journal was invoked but never defined (see the help page)."}, {"index": "3", "level": 1, "title": "See also", "content": "See also[edit] List of National Monuments in County Waterford History of Waterford"}, {"index": "4", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "5", "level": 1, "title": "External links", "content": "External links[edit] Official website National Monuments in State Care - Waterford"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Double_Tower", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:51:31.243027+11:00', '2026-01-13 00:25:13.072441+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68343, 'Т-72', 'en', 'The T-72 is a family of Soviet main battle tanks that entered production in 1973. The T-72 was a development based on the T-64 using thought and design of the previous Object 167M. About 25,000 T-72 tanks have been built, and refurbishment has enabled many to remain in service for decades. It has been widely exported and has seen service in 40 countries and in numerous conflicts. The Russian T-90 introduced in 1992 and the Chinese Type 99 are further developments of the T-72. Production and development of various modernized T-72 models continues today.', '[{"index": "1", "level": 1, "title": "Development", "content": ""}, {"index": "2", "level": 2, "title": "Development from the T-64", "content": ""}, {"index": "3", "level": 2, "title": "Object 172", "content": ""}, {"index": "4", "level": 2, "title": "T-72", "content": ""}, {"index": "5", "level": 1, "title": "Production history", "content": "Production history[edit] Two T-72B tanks at the Chebarkul training ground, Russia, April 2017 The first series production of T-72 Object 172M began in July at UKBM in Nizhny Tagil. However, due to difficulties in getting the factory organised for the change in production from T-64 to T-72, only 30 completed tanks were delivered in 1973. Troubles continued in 1974 where out of a state production quota of 440 only 220 were officially declared, with the actual number of completed tanks being close to 150. As a result, substantial investment in tooling was undertaken. Only after modernisation, could the factory begin full-scale production of the T-72. Nizhny Tagil produced the tank in various modifications until 1992. The T-72 was the most common tank used by the Warsaw Pact from the 1970s until the collapse of the Soviet Union in 1991. It was also exported to other countries, such as Finland, India, Iran, Iraq, Syria and Yugoslavia, as well as being copied elsewhere, both with and without licenses. Czech T-72M4CZ firing Licensed versions of the T-72 were made in Poland and Czechoslovakia, for Warsaw Pact consumers. The Polish-made T-72G tanks&#91;citation needed&#93; also had thinner armour compared to Soviet Army standard (410&#160;mm for turret). Before 1990, Soviet-made T-72 export versions were similarly downgraded for non-Warsaw Pact customers (mostly the Arab countries).&#91;citation needed&#93; Many parts and tools are not interchangeable between the Soviet, Polish and Czechoslovak versions, which caused logistics problems. Yugoslavia developed the T-72 into the more advanced M-84, and sold hundreds of them around the world during the 1980s. The Iraqis called their T-72 copies the \"Lion of Babylon\" (Asad Babil). These Iraqi tanks were assembled from kits sold to them by the Soviet Union as a means of evading the UN-imposed weapons embargo. More modern derivatives include the Polish PT-91 Twardy. Several countries, including Russia and Ukraine, also offer modernization packages for older T-72s. Various versions of the T-72 have been in production for decades, and the specifications for its armour have changed considerably. Original T-72 tanks had homogeneous cast steel armour incorporating spaced armour technology and were moderately well protected by the standards of the early 1970s. In 1979, the Soviets began building T-72 modification with composite armour similar to the T-64 composite armour, in the front of the turret and the front of the hull. Late in the 1980s, T-72 tanks in Soviet inventory (and many of those elsewhere in the world as well) were fitted with reactive armour tiles. TPD-K1 laser rangefinder system have appeared in T-72 tanks since 1974; earlier examples were equipped with parallax optical rangefinders, which could not be used for distances under 1,000 metres (1,100&#160;yd). Some export versions of the T-72 lacked the laser rangefinder until 1985 or sometimes only the squadron and platoon commander tanks (version K) received them. After 1985, all newly made T-72s came with reactive armour as standard, the more powerful 840&#160;bhp (630&#160;kW) V-84 engine and an upgraded design main gun, which can fire guided anti-tank missiles from the barrel. With these developments, the T-72 eventually became almost as powerful as the more expensive T-80 tank, but few of these late variants reached the economically ailing Warsaw Pact allies and foreign customers before the Soviet bloc fell apart in 1990. In the 1990s some reserve T-72B were given a minor upgrade of an uprated engine and better gun stabilisation to become the T-72BA. While not a popular upgrade, it solved a temporary supply shortage.&#91;1&#93; Since 2000, export vehicles have been offered with thermal imaging night-vision gear of French manufacture as well (though it may be more likely that they might simply use the locally manufactured ''Buran-Catherine'' system, which incorporates a French thermal imager). Depleted uranium armour-piercing ammunition for the 125&#160;mm (4.9&#160;in) gun has been manufactured in Russia in the form of the BM-32 projectile since around 1978, though it has never been deployed, and has less penetration than the later tungsten BM-42 and the newer BM-42M. In 2010, Russia started an upgrade using the enormous stocks of T-72Bs held in reserve. The rebuild tank is called T-72B3 (Ob''yekt 184-M3).&#91;2&#93; In 2018, the 3rd Central Research Institute in Moscow had tested a proof-of-concept demonstration for robotic tank mobility, and was planning to further develop it based on the T-72B3 and other platforms.&#91;3&#93; In 2022, Ukrainian intelligence sources claimed that the upgrade of the Russian T-72 fleet has slowed during the invasion of Ukraine while production of the more modern T-90s and T-14 Armatas has slowed down because of the international sanctions affecting the Russian military industry.&#91;4&#93; However, more tanks of T-72 and T-90 types were ordered in August 2022.&#91;5&#93; A new batch"}, {"index": "6", "level": 2, "title": "Models", "content": ""}, {"index": "7", "level": 2, "title": "Variants", "content": ""}, {"index": "8", "level": 1, "title": "Design characteristics", "content": ""}, {"index": "9", "level": 2, "title": "Weight", "content": ""}, {"index": "10", "level": 2, "title": "Nuclear, biological, and chemical protection", "content": ""}, {"index": "11", "level": 2, "title": "Interior", "content": ""}, {"index": "12", "level": 2, "title": "Armour", "content": ""}, {"index": "13", "level": 3, "title": "Estimated protection level", "content": ""}, {"index": "14", "level": 2, "title": "Gun", "content": ""}, {"index": "15", "level": 2, "title": "Autoloader", "content": ""}, {"index": "16", "level": 1, "title": "Operators and service", "content": ""}, {"index": "17", "level": 2, "title": "Syria", "content": ""}, {"index": "18", "level": 2, "title": "Iraq", "content": ""}, {"index": "19", "level": 2, "title": "Chechen wars", "content": ""}, {"index": "20", "level": 2, "title": "Russo-Georgian War", "content": ""}, {"index": "21", "level": 2, "title": "Russo-Ukrainian War", "content": ""}, {"index": "22", "level": 3, "title": "War in Donbas", "content": ""}, {"index": "23", "level": 3, "title": "Russian invasion of Ukraine", "content": ""}, {"index": "24", "level": 2, "title": "Combat history", "content": "Combat history[edit] .mw-parser-output .ambox{border:1px solid #a2a9b1;border-left:10px solid #36c;background-color:#fbfbfb;box-sizing:border-box}.mw-parser-output .ambox+link+.ambox,.mw-parser-output .ambox+link+style+.ambox,.mw-parser-output .ambox+link+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+style+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+link+.ambox{margin-top:-1px}html body.mediawiki .mw-parser-output .ambox.mbox-small-left{margin:4px 1em 4px 0;overflow:hidden;width:238px;border-collapse:collapse;font-size:88%;line-height:1.25em}.mw-parser-output .ambox-speedy{border-left:10px solid #b32424;background-color:#fee7e6}.mw-parser-output .ambox-delete{border-left:10px solid #b32424}.mw-parser-output .ambox-content{border-left:10px solid #f28500}.mw-parser-output .ambox-style{border-left:10px solid #fc3}.mw-parser-output .ambox-move{border-left:10px solid #9932cc}.mw-parser-output .ambox-protection{border-left:10px solid #a2a9b1}.mw-parser-output .ambox .mbox-text{border:none;padding:0.25em 0.5em;width:100%}.mw-parser-output .ambox .mbox-image{border:none;padding:2px 0 2px 0.5em;text-align:center}.mw-parser-output .ambox .mbox-imageright{border:none;padding:2px 0.5em 2px 0;text-align:center}.mw-parser-output .ambox .mbox-empty-cell{border:none;padding:0;width:1px}.mw-parser-output .ambox .mbox-image-div{width:52px}@media(min-width:720px){.mw-parser-output .ambox{margin:0 10%}}@media print{body.ns-0 .mw-parser-output .ambox{display:none!important}}This section needs additional citations for verification. Please help improve this article by adding citations to reliable sources&#32;in this section. Unsourced material may be challenged and removed. (February 2010) (Learn how and when to remove this message) Iraqi T-72 in 2006 Iraqi ''Saddam'' main battle tank destroyed in a Coalition attack during Operation Desert Storm 1980–1988: Iran–Iraq War (Iraq) 1982: Lebanon (Syria) 1987–1990: Sri Lankan Civil War (India)&#91;1&#93; 1988–1994: First Nagorno-Karabakh War (Armenia and Azerbaijan) 1988–1993: Georgian Civil War (Georgia) 1990–1991: First Persian Gulf War (Iraq and Kuwait) 1990–2002: Sierra Leone Civil War (Executive Outcomes)&#91;2&#93; 1991–2001: Yugoslav Wars (Yugoslavia) 1991: Ten-Day War (Yugoslavia) 1991–1995 Croatian War of Independence (Yugoslavia, Krajina Serbs, Croatia and Republika Srpska) 1998: Kosovo War (Yugoslavia) 2001: 2001 Macedonia conflict (Macedonia) 1991–2002: Algerian Civil War (Algeria) 1991: 1991 Iraqi uprisings (Iraq) 1991: August Coup (Soviet Union) 1992–1997: Civil war in Tajikistan (Russia and Tajikistan) 1994: Rwanda Civil War (Uganda) 1994–1996: First Chechen War (Russia and Chechnya (limited)) First known case of using tank-launched missiles, which effectively destroy targets at 4&#160;km range.&#91;3&#93; 1999–2009: Second Chechen War (Russia) 2003: Invasion of Iraq (Iraq) 2008: Russo-Georgian War (Russia and Georgia) 2011–2024: Syrian Civil War Government forces using T-72 tanks. Opposition forces using captured government''s tanks. 2011: 2011 Libyan civil war (Gaddafi Government and Anti-Gaddafi forces) 2013–2020: South Sudanese Civil War 2014–present: Russo-Ukrainian War (Ukraine, Russia and pro-Russian separatists) 2014: 2014 Pro-Russian unrest in Ukraine (Ukraine, pro-Russian separatists)&#91;citation needed&#93; 2014: Annexation of Crimea (Russia)&#91;4&#93; 2014–2022: War in Donbas&#91;5&#93;&#91;6&#93; 2022–present: Russian invasion of Ukraine&#91;7&#93; (Russia and Ukraine) 2014–2017: War in Iraq (2013–2017) (Iraq)&#91;8&#93; 2015: Boko Haram insurgency (Nigeria)&#91;9&#93; 2016: 2016 Nagorno-Karabakh clashes (Armenia and Azerbaijan) 2020: Second Nagorno-Karabakh war (Armenia and Azerbaijan) 2020–2021: 2020–2021 China–India skirmishes (India)&#91;10&#93; 2020–2022: Tigray War (Ethiopia and Tigray Defense Forces) 2022: 2022 Kyrgyzstan–Tajikistan clashes (Tajikistan) 2023: Sudanese civil war (2023–present) (Sudanese government forces)&#91;11&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parse"}, {"index": "25", "level": 1, "title": "See also", "content": ""}, {"index": "26", "level": 1, "title": "Notes", "content": ""}, {"index": "27", "level": 1, "title": "Sources", "content": ""}, {"index": "28", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/T-72", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:51:31.243027+11:00', '2026-01-13 00:25:13.072441+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68346, 'Усадьба_Охотниковых', 'en', 'Городская усадьба Охотниковых, городская усадьба Степановых — усадьба в Москве по адресу улица Пречистенка, дом 32/1. Объект культурного наследия федерального значения. Усадебный комплекс включает в себя главный дом, выходящий фасадом на улицу Пречистенка, фрагмент оригинальной усадебной ограды и замкнутый неогороженный внутренний двор, по периметру которого стоят два флигеля и два уникальных по своей архитектуре в масштабах Москвы служебных корпуса. Усадьба наиболее известна тем, что до революции в ней размещалась Поливановская гимназия.', '[{"index": "1", "level": 1, "title": "История", "content": "История[править | править код] На этом месте стояла усадьба Талызиных, которая была уничтожена пожаром 1812 года. Новая усадьба гвардии корнета Павла Яковлевича Охотникова была выстроена в стиле классицизма. Главный дом усадьбы располагается по красной линии улицы, в плане Т-образный. Работы по его возведению шли с 1817 по 1820 год, согласно некоторым источникам проект разработал архитектор Ф.&#160;К.&#160;Соколов. Парадный фасад дома украшает стоящий на цоколе восьмиколонный портик, который завершает треугольный фронтон с лепниной&#91;1&#93;. Тяжёлые замковые камни над окнами первого этажа, венчающий карниз и тосканский ордер портика придают зданию строгий торжественный вид, тонкая лепнина фронтона смягчает это впечатление&#91;2&#93;. По сторонам дома были выполнены арочные проезды во двор, в котором располагаются флигели и служебные постройки, имелась домовая церковь. Интерьеры дома были богато украшены, в советское время художник Евгений Лансере создал на их основе декорации для постановки комедии Грибоедова «Горе от ума» в Малом театре&#91;1&#93;. С 1879 по 1915 год усадьбой владели потомственные почётные граждане купцы Пеговы. В 1882 году главный дом усадьбы арендует гимназия Поливанова. Эту знаменитую на всю Москву частную гимназию окончили поэты Сергей Соловьёв, Валерий Брюсов, Андрей Белый, Максимилиан Волошин, Леонид Радин (автор песни «Смело товарищи в ногу»), шахматист Алёхин (в память об Алёхине на фасаде установлена мемориальная доска). На первом этаже располагалась гардеробная, служебно-хозяйственные помещения и учебные кабинеты. На втором&#160;— квартира Поливанова, классы, двусветный рекреационный зал с мраморными колоннами, за ними размещались гимнастические снаряды и учительская. Третий этаж заняли дортуары (общие спальни воспитанников), столовая для пансионеров и ещё две учебные комнаты для учеников 1-3-х классов. Для устройства классов помещения второго этажа подверглись перепланировке. В то же время парадный вход был украшен чугунной лестницей тонкой работы. В конце XIX века ведущие во двор арочные проезды были заложены&#91;1&#93;. В 1915 году усадьба переходит во владение к домовладелице и предпринимательнице Вере Ивановне Фирсановой, новая хозяйка заказывает архитектору А.&#160;И.&#160;Таманяну перестройку дома. Во время работ были изменены интерьеры второго этажа и фасады. Рекреационный зал вновь становится концертным, в нём устраивается эстрада в виде греческого портика. Пространство между окнами второго этажа украшают кариатиды и росписи работы художников А.&#160;Е.&#160;Яковлева и В.&#160;И.&#160;Шухаева. Таманян также строит каменную ограду, от которой до настоящего времени сохранилась только половина ворот&#91;1&#93;. В 1921 году усадьбу занимает Государственная Академия художественных наук (ГАХН). Полукруглые корпуса конюшен во дворе в 1930-х годах получили второй деревянный этаж и превратились в жилые здания. В 1963 году была проведена реставрация главного дома. По планам там должен был открыться магазин книг по искусству и художественный салон. В настоящее время здесь располагаются Детская художественная школа №&#160;1 им. В.&#160;А.&#160;Серова и Детская музыкальная школа №&#160;11 им. В.&#160;И.&#160;Мурадели&#91;1&#93;. В 2010-е годы фасад здания снова отреставрирован, укреплён исторический балкон, проведена реставрация уцелевшего фрагмента ограды. Внутри основного здания сохранилась старинная чугунная лестница и старый концертный зал (в нём ещё при Поливанове ставил свои спектакли известный на всю Москву «Шекспировский кружок»). Флигели-циркумференции, изначально построенные в качестве конюшен, в эпоху гимназии являлись спортивным залом, ныне их занимают помещения художественных и скульптурных мастерских. Усадьба Охотниковых Главный дом в 2008 году Портик Бывшие конюшни во дворе Панорама внутреннего двора. ↑ 1 2 3 4 5 Ошибка в сносках?:&#x20;Неверный тег &lt;ref&gt;; для сносок Узнай Москву не указан текст ↑ Москва: Энциклопедия, 1997, с.&#160;608."}, {"index": "2", "level": 1, "title": "Литература", "content": "Литература[править | править код] Москва: Энциклопедия&#160;/ гл. ред. С. О. Шмидт; сост.: М. И. Андреев, В. М. Карев.&#160;— М.&#160;: Большая российская энциклопедия, 1997.&#160;— 976&#160;с.&#160;: ил.&#160;— 100&#160;000 экз.&#160;— ISBN 5-85270-277-3."}, {"index": "3", "level": 1, "title": "Ссылки", "content": "Ссылки[править | править код] Городская усадьба Степановых (с циркумференцией) На карте."}, {"index": "4", "level": 1, "title": "Примечания", "content": "Примечания[править | править код] Ошибка в сносках?:&#x20;Тег &lt;ref&gt; с именем «Реестр», определённый в &lt;references&gt;, не используется в предшествующем тексте. Ошибка в сносках?:&#x20;Тег &lt;ref&gt; с именем «Узнай Москву», определённый в &lt;references&gt;, не используется в предшествующем тексте."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%A3%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0_%D0%9E%D1%85%D0%BE%D1%82%D0%BD%D0%B8%D0%BA%D0%BE%D0%B2%D1%8B%D1%85", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:51:31.243027+11:00', '2026-01-13 00:25:13.072441+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68370, 'Market_house', 'en', 'A market house or market hall is a covered space historically used as a marketplace to exchange goods and services such as provisions or livestock, sometimes combined with spaces for public or civic functions on the upper floors and often with a jail or lockup in the cellar or basement floor. Market houses usually included an arcade to protect traders and their goods from the elements while maintaining private access to most of the building.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] Carpentry of the market hall of Lesmont (Aube, France) Geographical distribution of still existing European market-halls as of 2010 Market House in Providence, Rhode Island, U.S."}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] General store Market (place) Market hall and Market hall (disambiguation) Market town Market square Moot hall Market halls in Berlin Market houses in Northern Ireland Market houses in the Republic of Ireland Stock exchange Tholsel (Ireland) and Tolbooth (Scotland)"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Market_house", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:54:06.236502+11:00', '2026-01-13 00:25:13.072441+11:00');
