INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62688, 'マツダミュージアム', 'en', 'マツダミュージアム は、自動車会社のマツダが運営する自動車に関する企業博物館である。', '[{"index": "1", "level": 1, "title": "概要", "content": ""}, {"index": "2", "level": 1, "title": "入場", "content": ""}, {"index": "3", "level": 1, "title": "ギャラリー", "content": ""}, {"index": "4", "level": 2, "title": "車両", "content": ""}, {"index": "5", "level": 2, "title": "エンジン", "content": ""}, {"index": "6", "level": 1, "title": "特別開館イベント", "content": ""}, {"index": "7", "level": 1, "title": "関連項目", "content": ""}, {"index": "8", "level": 1, "title": "外部リンク", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ja.wikipedia.org/wiki/%E3%83%9E%E3%83%84%E3%83%80%E3%83%9F%E3%83%A5%E3%83%BC%E3%82%B8%E3%82%A2%E3%83%A0", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:51:38.818981+11:00', '2026-01-13 00:25:12.703572+11:00');
