INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68462, 'Glenshee_Ski_Centre', 'en', 'Glenshee Ski Centre is an alpine snowsports area in the Scottish Highlands. It is located above the Cairnwell Pass at the head of Glen Shee on either side of the A93 road between Blairgowrie and Braemar. Glenshee is Britain''s largest alpine snowsports area and is referred to as the ''Scottish Three Glens''. in reference to Les Trois Vallées. The ski area covers 2,000 acres (8.1 km2).', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] Official site Archived 17 December 2008 at the Wayback Machine Snow report on Winterhighland Archived 27 July 2007 at the Wayback Machine"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Glenshee_Ski_Centre", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:54:06.236502+11:00', '2026-01-13 00:25:13.078054+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68485, 'River_Don_Engine', 'en', 'The River Don Engine is a 1904-built steam engine used for hot rolling steel armour plate. It is a 3-cylinder simple engine of 40 inches (1.0 m) diameter, 48 inches (1.2 m) stroke. At its operating steam pressure of 160psi, it developed 12,000 horsepower (8.9 MW), and was able to reverse from full speed in 2 seconds. The rapid reverse was an essential feature of an engine used for rolling, as delays would result in cooling of the workpiece. This engine was one of four built to the same design, one going overseas to the Japanese Government, one to John Brown''s Atlas plant, one to William Beardmore of Glasgow and one which stayed in Sheffield at Cammell''s mill. It is claimed to be one of the most powerful steam engines ever built, and the most powerful remaining in Europe.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] New Kelham Island Museum Blog Kelham Island Museum page .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefault,.mw-parser-output .geo-multi-punct,.mw-parser-output .geo-inline-hidden{display:none}.mw-parser-output .longitude,.mw-parser-output .latitude{white-space:nowrap}53°23′22″N 1°28′20″W&#xfeff; / &#xfeff;53.389503°N 1.472345°W&#xfeff; / 53.389503; -1.472345 .mw-parser-output .asbox{position:relative;overflow:hidden}.mw-parser-output .asbox table{background:transparent}.mw-parser-output .asbox p{margin:0}.mw-parser-output .asbox p+p{margin-top:0.25em}.mw-parser-output .asbox-body{font-style:italic}.mw-parser-output .asbox-note{font-size:smaller}.mw-parser-output .asbox .navbar{position:absolute;top:-0.75em;right:1em;display:none}.mw-parser-output :not(p):not(.asbox)+style+.asbox,.mw-parser-output :not(p):not(.asbox)+link+.asbox{margin-top:3em}This article about a Yorkshire building or structure is a stub. You can help Wikipedia by expanding it..mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,.mw-parser-output .hlist dl ol,.mw-parser-output .hlist dl ul,.mw-parser-output .hlist ol dl,.mw-parser-output .hlist ol ol,.mw-parser-output .hlist ol ul,.mw-parser-output .hlist ul dl,.mw-parser-output .hlist ul ol,.mw-parser-output .hlist ul ul{display:inline}.mw-parser-output .hlist .mw-e