INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (65977, 'L''auberge_Rouge_de_Peyrebelle', 'en', NULL, NULL, '[{"ref": "ref2", "url": null, "text": "Historical records and archives"}, {"ref": "ref3", "url": "https://whc.unesco.org", "text": "UNESCO World Heritage documentation"}, {"ref": "ref1", "url": "https://example.com/tourism", "text": "Official tourism website"}]'::jsonb, '2026-01-14 21:11:02.746391+11:00', '2026-01-13 00:25:12.915043+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68778, 'Adlerstein', 'en', 'The Adlerstein is a 676-metre-high summit in the Saxon Ore Mountains near Lengefeld. At the top there is a historic triangulation station which was part of the Royal Saxon triangulation network.', '[{"index": "1", "level": 1, "title": "Location and area", "content": "Location and area[edit] The Adlerstein lies in the Central Ore Mountains not far from the B 101 federal road that runs from Heinzebank to Pockau where there is a junction with the Lengefeld Road not far away. Immediately at the foot of the mountain is the well-known Lengefeld Lime Works (Kalkwerk Lengefeld). The Adlerstein and the nearby peak of the Lauterbacher Knochen complement one another as good viewing points, albeit partly obscured by trees in places."}, {"index": "2", "level": 1, "title": "Views", "content": "Views[edit] The other places that may be seen from the Adlerstein include the Sayda and Brand Heights, Waldkirchen, Marienberg, Dittersdorfer Höhe and Pöhlberg in Germany, and the Jelení hora (Haßberg), Hora Svaté Kateřiny (Katharinaberg) and the Čihadlo (Lauschhübei) in the Czech Republic."}, {"index": "3", "level": 1, "title": "Sources", "content": "Sources[edit] Das mittlere Zschopaugebiet. Edition no. 1 Akademie-Verlag Berlin, Berlin 1977 (Werte unserer Heimat. Vol. 28). p. 200."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Adlerstein", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:07:15.242296+11:00', '2026-01-13 00:25:13.097236+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68809, 'Borgo_San_Giovanni', 'en', 'Borgo San Giovanni is a comune (municipality) in the Province of Lodi in the Italian region Lombardy, located about 30 kilometres (19 mi) southeast of Milan and about 8 kilometres (5 mi) southwest of Lodi.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,