INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68908, 'Great_North_Road', 'en', 'Great North Road may refer to:', '[{"index": "1", "level": 1, "title": "Roads", "content": "Roads[edit] Great North Road (Great Britain), a historical coaching route partly used by the A1 road in the United Kingdom Great North Road (Ancestral Puebloans), a road used by the Ancestral Puebloans of the American Southwest, part of the Chacoan road system Great North Road, Gibraltar, a lorry sized tunnel Great North Road (New South Wales), a historical road in Australia leading from Sydney to the Hunter Valley Great North Road (Mount Manning to Wollombi Section) Great North Road, Auckland, a road in Auckland Great North Road, Zambia, a road running north from Lusaka Great North Road (Ontario), a 19th-century road from Parry Sound to Nipissing, see Magnetawan Cape to Cairo Road, an historically planned route through Africa Cariboo Road, an historical route in British Columbia, Canada New Zealand State Highway 1, a road near Kamo in New Zealand"}, {"index": "2", "level": 1, "title": "Other", "content": "Other[edit] Great North Road (book), a science fiction novel by Peter F Hamilton, 2012"}, {"index": "3", "level": 1, "title": "See also", "content": "See also[edit] North Road (disambiguation) Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Great North Road.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Great_North_Road", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:10:41.283283+11:00', '2026-01-13 00:25:13.103408+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68915, 'Acco_super_bulldozer', 'en', 'The Acco Super Bulldozer is the largest and most powerful tracked bulldozer ever made. It was built in Portogruaro in northern Italy by the Umberto Acco company. The Acco super bulldozer was constructed mainly of Caterpillar parts; however, many other components were specially adapted. The dozer blade, for example, is bigger than anything Caterpillar has ever made. This bulldozer has a gross weight of 183 tonnes and is powered by two 675 hp (503 kW) Caterpillar engines placed horizontally opposed, which deliver a total combined output of 1,350 hp (1,010 kW). The super bulldozer has a blade that is 7 metres (23 ft) wide and 3 metres (9.8 ft) high, whilе the total length of the bulldozer is over 12 metres (39 ft), from the tip of the blade to the ripper on the rear. The ripper alone is about 3 metres (9.8 ft) tall, being powered by huge hydraulic rams.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Acco_super_bulldozer", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:10:41.283283+11:00', '2026-01-13 00:25:13.103408+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68921, 'Куртяево', 'en', 'Куртя́ево — урочище в Приморском районе Архангельской области, на реке Верховка в 35 км от Северодвинска. Урочище Куртяево является памятником природы регионального значения. Площадь урочища — 150 га. Примечательно минеральными источниками и церковью Святого Алексия. Находится на месте потухшего вулкана.', '[{"index": "1", "level": 1, "title": "История урочища", "content": ""}, {"index": "2", "level": 1, "title": "История храма", "content": ""}, {"index": "3", "level": 1, "title": "Часовня", "content": ""}, {"index": "4", "level": 1, "title": "Легенды о происхождении храма", "content": ""}, {"index": "5", "level": 1, "title": "Источник минеральной воды", "content": ""}, {"index": "6", "level": 1, "title": "Комментарий", "content": ""}, {"index": "7", "level": 1, "title": "Примечания", "content": ""}, {"index": "8", "level": 1, "title": "Ссылки", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%9A%D1%83%D1%80%D1%82%D1%8F%D0%B5%D0%B2%D0%BE", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:10:41.283283+11:00', '2026-01-13 00:25:13.103408+11:00');
