INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62701, '서산버드랜드', 'en', '서산버드랜드(Seosan Birdland)는 천수만을 체계적으로 보전, 관리하고, 생태 관광의 활성화에 주력하기 위해 충청남도 서산시에 조성된 생태공원이다. 서산버드랜드 내에는 철새의 박제 등을 전시하는 철새박물관이 있다. 철새박물관에는 천수만에 서식하는 큰기러기, 가창오리, 노랑부리저어새, 큰고니 등 200여 종의 철새 표본과 전시자료, 영상자료, 새소리 등이 있다.', '[{"index": "1", "level": 1, "title": "시설", "content": ""}, {"index": "2", "level": 2, "title": "철새박물관", "content": ""}, {"index": "3", "level": 2, "title": "4D영상관", "content": ""}, {"index": "4", "level": 2, "title": "둥지전망대", "content": ""}, {"index": "5", "level": 2, "title": "자생식물원", "content": ""}, {"index": "6", "level": 1, "title": "각주", "content": ""}, {"index": "7", "level": 1, "title": "외부 링크", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ko.wikipedia.org/wiki/%EC%84%9C%EC%82%B0%EB%B2%84%EB%93%9C%EB%9E%9C%EB%93%9C", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:51:57.961182+11:00', '2026-01-13 00:25:12.703572+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (68956, 'Randolph''s_Leap', 'en', 'Randolph''s Leap is an SSSI and area of countryside in Moray, Scotland. The area surrounds the River Findhorn and is named after the point at the river where the sheer rock banks are closest.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-pars