INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62705, '泰宁尚书第建筑群', 'en', '泰宁尚书第建筑群位于中华人民共和国福建省三明市泰宁县尚书街，由尚书第和世德堂两组民居建筑组成。泰宁尚书第于1988年被列为第三批全国重点文物保护单位，世德堂于2001年公布第五批全国重点文物保护单位时与泰宁尚书第合并称为“泰宁尚书第建筑群”。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69186, 'Stocks', 'en', 'Stocks are feet restraining devices that were used as a form of corporal punishment and public humiliation. The use of stocks is seen as early as Ancient Greece, where they are described as being in use in Solon''s law code. The law describing its use is cited by the orator Lysias: "''He shall have his or her foot confined in the stocks for five days, if the court shall make such addition to the sentence.'' The ''stocks'' there mentioned, Theomnestus, are what we now call ''confinement in the wood''".', '[{"index": "1", "level": 1, "title": "Form and applications", "content": ""}, {"index": "2", "level": 1, "title": "Modern use", "content": ""}, {"index": "3", "level": 2, "title": "United States", "content": ""}, {"index": "4", "level": 2, "title": "United Kingdom", "content": ""}, {"index": "5", "level": 2, "title": "Colombia", "content": ""}, {"index": "6", "level": 1, "title": "Examples", "content": ""}, {"index": "7", "level": 2, "title": "England", "content": ""}, {"index": "8", "level": 2, "title": "Northern Ireland", "content": ""}, {"index": "9", "level": 1, "title": "See also", "content": ""}, {"index": "10", "level": 1, "title": "References", "content": ""}, {"index": "11", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Stocks", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:19:46.069208+11:00', '2026-01-13 00:25:13.122005+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69201, 'Star_Wars_Hyperspace_Mountain', 'en', 'Star Wars: Hyperspace Mountain is an indoor/outdoor steel roller coaster in Discoveryland at Disneyland Paris. Originally themed around Jules Verne''s classic 1865 novel From the Earth to the Moon, the attraction first opened on June 1, 1995, three years after the park''s debut in an attempt to draw more guests to the financially unstable European resort. Unlike other Space Mountain attractions at Disney theme parks, the installation at Disneyland Paris had a steampunk-detailed appearance with a Columbiad Cannon and a plate-and-rivet exterior under its previous theme. It is the only Space Mountain to feature inversions, a launch, a section of track that exits and re-enters the interior, and a synchronized on-Board audio track. It is by far the largest Space Mountain installation at any Disney theme park.', '[{"index": "1", "level": 1, "title": "Original concept", "content": ""}, {"index": "2", "level": 1, "title": "Attraction", "content": ""}, {"index": "3", "level": 2, "title": "De la Terre à la Lune/<i>From the Earth to the Moon</i> (1995–2005)", "content": ""}, {"index": "4", "level": 2, "title": "<i>Space Mountain: Mission 2</i> (2005–2017)", "content": ""}, {"index": "5", "level": 2, "title": "<i>Star Wars: Hyperspace Mountain</i> (2017–present)", "content": ""}, {"index": "6", "level": 1, "title": "Public reception", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "Further reading", "content": ""}, {"index": "10", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Star_Wars_Hyperspace_Mountain", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:20:08.327149+11:00', '2026-01-13 00:25:13.122005+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69219, 'Villa_Durazzo-Pallavicini', 'en', 'The Villa Durazzo-Pallavicini is a villa with notable 19th-century park in the English romantic style and a small botanical garden. The villa now houses the Museo di Archeologia Ligure, and is located at Via Pallavicini 13, immediately next to the railway station in Pegli, a suburb of Genoa, Italy. The park and botanical garden are open daily except mondays.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Villa Gandolfi Pallavicini, Bologna Villas of Genoa"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] Villa Pallavicini: Parco Romantico di Pegli, Genova Città Inaspettata, Sagep Libri &amp; Comunicazione Srl, Genoa, 2002. .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}ISBN&#160;88-7058-864-5. A.Valenti Durazzo \"I Durazzo da schiavi a dogi della Repubblica di Genova\", 2004. A.Valenti Durazzo \"Il Fratello del Doge. Giacomo Durazzo un illuminista alla Corte degli Asburgo tra Mozart, Casanova e Gluck\", 2012."}, {"index": "3", "level": 1, "title": "External links", "content": "External links[edit] Museum of Ligurian Archaeology"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Villa_Durazzo-Pallavicini", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:20:08.327149+11:00', '2026-01-13 00:25:13.122005+11:00');
