INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69300, 'Т-34-85', 'en', 'Т-34-85 — войсковое обозначение последней и самой массовой модификации советского среднего танка Т-34 с орудием калибра 85 мм. Принят на вооружение РККА Постановлением ГКО № 5021 от 23 января 1944 года.', '[{"index": "1", "level": 1, "title": "История создания", "content": ""}, {"index": "2", "level": 2, "title": "Эффект наклона брони", "content": ""}, {"index": "3", "level": 2, "title": "Создание новой башни", "content": ""}, {"index": "4", "level": 1, "title": "Серийное производство", "content": ""}, {"index": "5", "level": 2, "title": "Первое полугодие 1944 года", "content": ""}, {"index": "6", "level": 2, "title": "1946 год", "content": ""}, {"index": "7", "level": 2, "title": "Конструктивные особенности танков выпуска военного времени", "content": ""}, {"index": "8", "level": 2, "title": "Лицензионное производство на заводах Польши и Чехословакии.", "content": ""}, {"index": "9", "level": 1, "title": "Техническое описание танка Т-34-85", "content": ""}, {"index": "10", "level": 2, "title": "Корпус танка Т-34-85", "content": ""}, {"index": "11", "level": 3, "title": "Компоновка корпуса", "content": ""}, {"index": "12", "level": 3, "title": "Конструкция корпуса", "content": ""}, {"index": "13", "level": 2, "title": "Орудийная башня танка Т-34-85", "content": ""}, {"index": "14", "level": 3, "title": "Конструкция башни с пушкой С-53 (ЗИС-С-53)", "content": ""}, {"index": "15", "level": 3, "title": "Компоновка башни с пушкой С-53 (ЗИС-С-53)", "content": ""}, {"index": "16", "level": 2, "title": "Вооружение", "content": ""}, {"index": "17", "level": 2, "title": "Средства наблюдения и связи", "content": ""}, {"index": "18", "level": 2, "title": "Электрооборудование", "content": ""}, {"index": "19", "level": 2, "title": "Двигатель и трансмиссия", "content": ""}, {"index": "20", "level": 2, "title": "Хо