INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69526, 'Marymere_Falls', 'en', 'Marymere Falls is located in Olympic National Park near Lake Crescent in Washington, United States. The falls are accessed by a 0.9 mile, well-maintained, dirt trail through an old-growth lowland forest consisting of fir, cedar, hemlock, alder trees and 2 wooden bridges. Falls creek descends from Aurora Ridge and tumbles over Marymere Falls and then flows into Barnes Creek. It has a height of 90.5 feet (27.6 m). The falls is one of the more popular attractions in the area, due to ease of access and proximity to U.S. Highway 101.', '[{"index": "1", "level": 1, "title": "External links", "content": "External links[edit] U.S. Geological Survey Geographic Names Information System: Marymere Falls .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,.mw-parser-output .hlist dl ol,.mw-parser-output .hlist dl ul,.mw-parser-output .hlist ol dl,.mw-parser-output .hlist ol ol,.mw-parser-output .hlist ol ul,.mw-parser-output .hlist ul dl,.mw-parser-output .hlist ul ol,.mw-parser-output .hlist ul ul{display:inline}.mw-parser-output .hlist .mw-empty-li{display:none}.mw-parser-output .hlist dt::after{content:\": \"}.mw-parser-output .hlist dd::after,.mw-parser-output .hlist li::after{content:\"\\a0 · \";font-weight:bold}.mw-parser-output .hlist dd:last-child::after,.mw-parser-output .hlist dt:last-child::after,.mw-parser-output .hlist li:last-child::after{content:none}.mw-parser-output .hlist dd dd:first-child::before,.mw-parser-output .hlist dd dt:first-child::before,.mw-parser-output .h