INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69567, 'York_Redoubt', 'en', 'York Redoubt is a redoubt situated on a bluff overlooking the entrance to Halifax Harbour at Ferguson''s Cove, Nova Scotia, Canada, originally constructed in 1793. It was designated a National Historic Site of Canada in 1962.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] An anti-submarine net running between York Redoubt and McNab''s Island in 1942 York Redoubt was a key element in the defence of Halifax Harbour in the 19th and 20th centuries, and saw many additions to its fortifications. It was a command centre for the local harbour defences in World War II, which included observation posts, a defensive minefield and a new gun battery below the fort at Sleepy Cove covering the anti-submarine net which stretched across the harbour''s entrance from Fort McNab on McNabs Island. York Redoubt remained in military use until 1956. Buildings in the redoubt complex include what remains of the Duke of York''s Martello tower, built in 1798; other fortifications from around 1800 and 1900; and advanced fortifications and artillery from World War II. York Redoubt has many examples of rifled muzzle loader cannon from the 1870s period. An open-air collection of unmounted cannon within the fort has several pieces of artillery of various periods, including a large 9.62-inch breech loader that had been mounted at the Sandwich Point battery, part of the York Redoubt complex. Structures at the water''s edge at Sleepy Cove battery, now closed to the public, include three search light batteries, two concrete lookout towers and two gun emplacements which originally held two 12-pounder guns, but were later replaced with 6-pounder guns. On 28 June 1985, Canada Post issued \"York Redoubt, N.S.\", one of the twenty stamps in the \"Forts Across Canada Series\" (1983 &amp; 1985).&#91;1&#93; ^ Canada Post issued ''York Redoubt, N.S.''&#91;permanent dead link&#93;"}, {"index": "2", "level": 1, "title": "Sandwich Point Battery", "content": ""}, {"index": "3", "level": 1, "title": "Transportation", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "External links", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/York_Redoubt", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:33:54.667020+11:00', '2026-01-13 00:25:13.147799+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69568, 'Cataract_Falls_Covered_Bridge', 'en', 'The Cataract Falls Covered Bridge is a covered bridge that spans Mill Creek in Lieber State Recreation Area, Owen County, Indiana. Built in 1876 by the Smith Bridge company of Toledo, Ohio, it was at one time one of the most famous and photographed covered bridges in the United States. It is the only remaining one in Owen County.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Cataract Falls (Indiana) List of bridges documented by the Historic American Engineering Record in Indiana"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "3", "level": 1, "title": "External links", 