INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69582, 'Phantom_Falls', 'en', 'Phantom Falls or Coal Canyon Falls is a waterfall at Coal Canyon near Oroville, California, within the North Table Mountain Ecological Reserve. The waterfall is 166 feet (51 m) high and runs off the edge of Coal Canyon, in front of a grotto. A small pool at the bottom is home to a California newt subspecies, the Coastal Range newt. As a seasonal waterfall, Phantom Falls runs only during the rainy months, late autumn to early spring. It is named Phantom Falls because it disappears during the dry season.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of waterfalls List of waterfalls in California"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower