INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69609, 'Casey_Jr._Circus_Train', 'en', 'The Casey Jr. Circus Train is the name of a ridable railroad attraction found at Disneyland and a powered roller coaster attraction found at Disneyland Park (Paris). It is based on the train from Dumbo. This tour is similar to the one given on the slower paced Storybook Land Canal Boats, but does not incorporate narration.', '[{"index": "1", "level": 1, "title": "Description", "content": "Description[edit] Casey Jr. at Disneyland Paris .mw-parser-output .RMbox{box-shadow:0 2px 2px 0 rgba(0,0,0,.14),0 1px 5px 0 rgba(0,0,0,.12),0 3px 1px -2px rgba(0,0,0,.2)}.mw-parser-output .RMinline{float:none;width:100%;margin:0;border:none}.mw-parser-output table.routemap{padding:0;border:0;border-collapse:collapse;white-space:nowrap;line-height:1.2;margin:auto}.mw-parser-output table.routemap .RMcollapse{margin:0;border-collapse:collapse;vertical-align:middle}.mw-parser-output table.routemap .RMreplace{margin:0;border-collapse:collapse;vertical-align:middle;position:absolute;bottom:0}.mw-parser-output table.routemap .RMsi{display:inline;font-size:90%}.mw-parser-output table.routemap .RMir{padding:0!important}.mw-parser-output table.routemap .RMl1{padding:0 3px!important;text-align:left}.mw-parser-output table.routemap .RMr1{padding:0 3px!important;text-align:right}.mw-parser-output table.routemap .RMl{padding:0!important;text-align:right}.mw-parser-output table.routemap .RMr{padding:0!important;text-align:left}.mw-parser-output table.routemap .RMl4{padding:0 3px 0 0!important;text-align:left}.mw-parser-output table.routemap .RMr4{padding:0 0 0 3px!important;text-align:right}.mw-parser-output table.routemap>tbody>tr{line-height:1}.mw-parser-output table.routemap>tbody>tr>td,.mw-parser-output table.RMcollapse>tbody>tr>td,.mw-parser-output table.RMreplace>tbody>tr>td{padding:0;width:auto;vertical-align