INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69630, 'Las_Pozas', 'en', 'Las Pozas is a surrealistic group of structures created by Edward James, more than 2,000 feet (610 m) above sea level, in a subtropical rainforest in the Sierra Gorda mountains of Mexico. It includes more than 80 acres (32 ha) of natural waterfalls and pools interlaced with towering surrealist sculptures in concrete.', '[{"index": "1", "level": 1, "title": "Location and conception", "content": ""}, {"index": "2", "level": 1, "title": "Construction", "content": ""}, {"index": "3", "level": 1, "title": "Surrealism", "content": ""}, {"index": "4", "level": 1, "title": "Design and creation", "content": ""}, {"index": "5", "level": 1, "title": "Ownership", "content": ""}, {"index": "6", "level": 1, "title": "Tourist attraction", "content": ""}, {"index": "7", "level": 1, "title": "Gallery", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Las_Pozas", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:36:26.868791+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69637, 'General_Grant_Tree', 'en', 'The General Grant Tree is the largest giant sequoia in the General Grant Grove section of Kings Canyon National Park in California, and the second largest giant sequoia tree in the world after the General Sherman Tree. Once thought to be well over 2,000 years old, recent estimates suggest the General Grant Tree is closer to 1,650 years old. The tree also features the third largest footprint of any living giant sequoia, measuring 107.6 ft (32.8 m) in circumference at ground level.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The tree is decorated as the \"Nation''s Christmas Tree\" The tree was named in 1867 after Ulysses S. Grant, Union Army general and the 18th President of the United States (1869–1877). President Calvin Coolidge proclaimed it the \"Nation''s Christmas Tree\" on April 28, 1926. Due in large part to its huge base, the General Grant Tree was thought to be the largest tree in the world prior to 1931, when the first precise measurements indicated that the General Sherman Tree was slightly larger. On March 29, 1956, President Dwight D. Eisenhower declared the tree a \"National Shrine\", a memorial to those who died in war. It is the only living object to be so declared.&#91;1&#93; In September 2003, the General Grant Tree moved up one place in the giant sequoia size rankings when the Washington Tree lost its crown and the hollow upper half of its trunk after a fire caused by a lightning strike. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em cent