INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62721, '富田村诚敬堂', 'en', '富田村诚敬堂位于中国江西省吉安市青原区富田镇，包括诚敬堂在内共23处文物建筑2013年被列为第七批全国重点文物保护单位。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69675, 'Legoland_Discovery_Centre', 'en', 'Legoland Discovery Centre is an indoor family attraction chain operated by British leisure group Merlin Entertainments. Featuring models and attractions inspired by the Lego building toys, the Discovery Centres are smaller and indoor versions of the Legoland theme parks located around the world.', '[{"index": "1", "level": 1, "title": "Attractions", "content": ""}, {"index": "2", "level": 1, "title": "Reception", "content": ""}, {"index": "3", "level": 1, "title": "Locations", "content": ""}, {"index": "4", "level": 2, "title": "Asia", "content": ""}, {"index": "5", "level": 2, "title": "Europe", "content": ""}, {"index": "6", "level": 2, "title": "North America", "content": ""}, {"index": "7", "level": 2, "title": "Australia", "content": ""}, {"index": "8", "level": 1, "title": "Future locations", "content": ""}, {"index": "9", "level": 1, "title": "Notes", "content": ""}, {"index": "10", "level": 1, "title": "References", "content": ""}, {"index": "11", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Legoland_Discovery_Centre", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:17.175459+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69676, 'Harvard_Square', 'en', 'Harvard Square is a triangular plaza at the intersection of Massachusetts Avenue, Brattle Street and John F. Kennedy Street near the center of Cambridge, Massachusetts, United States. The term "Harvard Square" is also used to delineate the business district and Harvard University surrounding that intersection, which is the historic center of Cambridge. Adjacent to Harvard Yard, the historic heart of Harvard University, the Square functions as a commercial center for Harvard students, as well as residents of western Cambridge, the western and northern neighborhoods and the inner suburbs of Boston. The Square is served by Harvard station, a major MBTA Red Line subway station and a bus transportation hub.', '[{"index": "1", "level": 1, "title": "Location", "content": ""}, {"index": "2", "level": 2, "title": "Nearby places", "content": ""}, {"index": "3", "level": 2, "title": "Other features", "content": ""}, {"index": "4", "level": 1, "title": "History", "content": "History[edit] .mw-parser-output .ambox{border:1px solid #a2a9b1;border-left:10px solid #36c;background-color:#fbfbfb;box-sizing:border-box}.mw-parser-output .ambox+link+.ambox,.mw-parser-output .ambox+link+style+.ambox,.mw-parser-output .ambox+link+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+style+.ambox,.mw-parser-output .ambox+.mw-empty-elt+link+link+.ambox{margin-top:-1px}html body.mediawiki .mw-parser-output .ambox.mbox-small-left{margin:4px 1em 4px 0;overflow:hidden;width:238px;border-collapse:collapse;font-size:88%;line-height:1.25em}.mw-parser-output .ambox-speedy{border-left:10px solid #b32424;background-color:#fee7e6}.mw-parser-output .ambox-delete{border-left:10px solid #b32424}.mw-parser-output .ambox-content{border-left:10px solid #f28500}.mw-parser-output .ambox-style{border-left:10px solid #fc3}.mw-parser-output .ambox-move{border-left:10px solid #9932cc}.mw-parser-output .ambox-protection{border-left:10px solid #a2a9b1}.mw-parser-output .ambox .mbox-text{border:none;padding:0.25em 0.5em;width:100%}.mw-parser-output .ambox .mbox-image{border:none;padding:2px 0 2px 0.5em;text-align:center}.mw-parser-output .ambox .mbox-imageright{border:none;padding:2px 0.5em 2px 0;text-align:center}.mw-parser-output .ambox .mbox-empty-cell{border:none;padding:0;width:1px}.mw-parser-output .ambox .mbox-image-div{width:52px}@media(min-width:720px){.mw-parser-output .ambox{margin:0 10%}}@media print{body.ns-0 .mw-parser-output .ambox{display:none!important}}This section needs expansion. You can help by expanding it. (April 2015) 1873 Map of Harvard Square Although today a commercial center, the Square had notable residents in earlier periods, including the colonial poet Anne Bradstreet. Transformation[edit] Harvard Square from above in 1921, looking west. Harvard University''s Widener Library is right of center Discussions of how the Square has changed in recent years usually center on the gentrification of the Harvard Square neighborhood and Cambridge in general. The Square also used to be a neighborhood shopping center, including a grocery store (Sages) and a Woolworth''s five and ten. Although a hardware store (Dickson Hardware at 26 Brattle Street) survived until 2021 amid chain drug stores and bank branches, the Square is mainly a regional rather than neighborhood shopping destination, serving students and commuters.[1] In 1981 and 1987 the Harvard Square Theater was converted into a multiplex cinema; it later became part of the Loews Cineplex Entertainment chain and then closed on July 8, 2012.&#91;1&#93; During the late 1990s, some locally run businesses with long-time shopfronts on the Square&#8212;including the unusual Tasty Diner, a tiny sandwich shop open long hours, and the Wursthaus, a German restaurant with an extensive beer menu&#8212;closed to make way for national chains. Elsie''s Lunch, a long-popular deli, also closed; what remained of its small corner storefront space facing Lowell House on Mount Auburn Street is now occupied by an ATM. Another long-time restaurant, Leo''s Place, closed in December 2013, after 64 years in business, when the landlord of the property terminated their lease.&#91;2&#93;The Out of Town News newsstand, which opened in 1955, occupied the Harvard Square subway kiosk from 1984 to 2019.&#91;3&#93;The student co-op, the Harvard/MIT Cooperative Society (\"The Coop\"), founded in 1882, is now managed by Barnes &amp; Noble, though it is still overseen by a board elected by its membership of Harvard and MIT students and staff. Schoenhof''s Foreign Books is owned by the French Éditions Gallimard. Major bookstores Paperback Booksmith, Reading International, and Barilari Books had closed by the end of the 1990s.&#91;4&#93; WordsWorth Books at 30 Brattle Street closed in 2004, after 29 years as a fixture in the Square.&#91;5&#93; In the same year, the famous Grolier Poetry Bookshop announced that it would be sold (although it survived under new management). Globe Corner Bookstore converted to an exclusively online business, serving its last walk-in customer on July 4, 2011. Following national trends, the former Harvard Trust Company has been absorbed into the national Bank of America through a series of mergers. Several establishments remain as longstanding, locally-run businesses with unique styles. Examples include Leavitt &amp; Peirce tobacconists (est. 1883), Laflamme Barber Shop (est. 1898), Harvard Book Store (est. 1932), Cardullo''s Gourmet Shoppe (est. 1950), Charlie''s Kitchen (est. 1951), the Brattle Theater (est. 1953), the Hong Kong Chinese restaurant (est. 1954), Club Passim (est. 1958), Café Pamplona (est. 1959), Mr. Bartley''s Burger Cottage (est. 1960), Million Year Picnic comics (est. 1970), Algiers Coffee House (est. 1970), and Grendel''s Den (est. 1971). ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:tar"}, {"index": "5", "level": 2, "title": "Transformation", "content": ""}, {"index": "6", "level": 1, "title": "In film and other media", "content": ""}, {"index": "7", "level": 2, "title": "\"Car Talk Plaza\"", "content": ""}, {"index": "8", "level": 1, "title": "See also", "content": ""}, {"index": "9", "level": 1, "title": "References", "content": ""}, {"index": "10", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Harvard_Square", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:17.175459+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69682, 'Tower_Fall', 'en', 'Tower Fall is a waterfall on Tower Creek in the northeastern region of Yellowstone National Park, in the U.S. state of Wyoming. Approximately 1,000 yards (910 m) upstream from the creek''s confluence with the Yellowstone River, the fall plunges 132 feet (40 m). Its name comes from the rock pinnacles at the top of the fall. Tower Creek and Tower Fall are located approximately three miles south of Roosevelt Junction on the Tower-Canyon road.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] On September 15–16, 1869, members of the Cook–Folsom–Peterson Expedition spent a whole day in the Tower Fall area before crossing the river and traveling up the East Fork of the Yellowstone (Lamar River).&#91;1&#93; In August 1870, the Washburn-Langford-Doane Expedition camped near and explored the Tower Fall area for several days en route to Yellowstone Lake.&#91;2&#93; In his 1871 report to Secretary of War Gustavus C. Doane, a member of the expedition described Tower Falls thus: .mw-parser-output .templatequote{overflow:hidden;margin:1em 0;padding:0 32px}.mw-parser-output .templatequotecite{line-height:1.5em;text-align:left;margin-top:0}@media(min-width:500px){.mw-parser-output .templatequotecite{padding-left:1.6em}}The great curiosity of the locality, however, is the Tower Fall of Hot Spring Creek, where that stream is precipitated, in one unbroken body, from an amygdaloid ledge, a sheer descent of 115 feet, into a deep gorge, joining the Yellowstone a few hundred yards below. At the crest of the fall the stream has cut its way through amygdaloid masses, leaving tall spires of rock from 50 to 100 feet in height, and worn in every conceivable shape. These are very friable, crumbling under slight pressure; several of them stand like sentinels on the very brink of the fall. A view from the summit of one of these spires is exceedingly beautiful; the clear icy stream plunges from a brink 100 feet beneath to the bottom of the chasm, over 200 feet below, and thence rushes through the narrow gorge, tumbling over boulders and tree trunks fallen in the channel. The sides of the chasm are worn away into caverns lined with variously-tinted mosses, nourished by clouds of spray which rise from the cataract; while above, and to the left, a spur from the great plateau rises above all, with a perpendicular front of 400 feet. The fall is accessible either at the brink or foot, and fine views can be obtained from either side of the cañon. In appearance, they strongly resemble those of the Minnehaha, but are several times as high, and run at least eight times the volume of water. In the basin we found a large petrified log imbedded in the débris. Nothing can be more chastely beautiful than this lovely cascade, hidden away in the dim light of overshadowing rocks and woods, its very voice hushed to a low murmur, unheard at the distance of a few hundred yards. Thousands might pass by within a half mile and not dream of its existence; but once seen, it passes to the list of most pleasant memories. In the afternoon the remainder of the party arrived, having lost the trail on the previous day.—&#8202;Gustavus C. Doane&#91;3&#93; The fall was named by Samuel Hauser, a member of the Washburn party. Hauser made this notation in his diary on August 27, 1870: Campt [sic] near the most beautiful falls-I ever saw-I named them Tower Falls-from the towers &amp; pinnicle[sic] that overhang them height 115 feet Aug 28-Didnt [sic] move camp Cenery [sic] too beautiful I measured these falls-found them 115-the pinacal [sic] cover top Then 200ft Eight different spires crown from the falls-From below the view is splendid.—&#8202;Samuel Hauser&#91;4&#93; The fall was renamed Tower Fall (singular) by the U.S. Geological Survey in 1928.&#91;5&#93; A well-known painting by Thomas Moran in 1871 helped persuade Congress to set aside Yellowstone as the world''s first national park in 1872.&#91;6&#93; Images of Tower Fall[edit] Sketch of Tower Fall by Private Charles Moore, 1870 Illustration, 1871&#91;7&#93; Tower Fall by William Henry Jackson, 1871 Tower Creek, by Thomas Moran, 1871 Tower Fall and Sulphur Mountain, Thomas Moran, 1875 Tower Fall, 1894 by Frank Jay Haynes Tower Fall, 2003 Tower Falls of Yellowstone Thomas Moran ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-su"}, {"index": "2", "level": 2, "title": "Images of Tower Fall", "content": "Images of Tower Fall[edit] Sketch of Tower Fall by Private Charles Moore, 1870 Illustration, 1871&#91;1&#93; Tower Fall by William Henry Jackson, 1871 Tower Creek, by Thomas Moran, 1871 Tower Fall and Sulphur Mountain, Thomas Moran, 1875 Tower Fall, 1894 by Frank Jay Haynes Tower Fall, 2003 Tower Falls of Yellowstone Thomas Moran ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-ou