INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69691, 'Hillary_House_and_Koffler_Museum_of_Medicine', 'en', 'Hillary House, the Koffler Museum of Medicine, is a house built in the Gothic Revival style, now in use as a museum. Built in 1862, Hillary House in Aurora, Ontario, is recognized by the National Historic Sites and Monuments Board as one of the best examples of Gothic Revival architecture in Canada. The building contains a collection of medical instruments, books, papers, household furnishings, and equipment dating from the early nineteenth to the late twentieth century. It has been owned by the Aurora Historical Society since 1981 and is open to the public as Hillary House, the Koffler Museum of Medicine.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Four doctors have lived in Hillary House with their families. They worked from home; operating their medical practice out of the dispensary and consulting room located in the front of the house. The doctors also spent a significant amount of time travelling to the homes of their patients via horse and buggy, serving Aurora and the surrounding area. Each doctor became an important part of the fabric of the community, and the Hillary family descendants would live in the home for over 100 years. 1862 – 69: Hillary House is built for Dr. Water Bayne Geikie, b. 1830 in Scotland, d. 1917. Lived in the house with his wife Miriam Woodhouse (m.1854), and his 4 children. 1869 – 76: Dr. Frederick William Strange, Surgeon Lieutenant-Colonel to the Royal Regiment of Canadian Infantry (b. 1844 in England, d. 1897). Lived in the house with his wife, Esther Rose, and daughter who died at age 3. 1876 – 1894: Robert William Hillary (b. 1832 in Ireland, d. 1894). Lived in the house with his wife Annie Fry (d. 1904) and their 7 children. 1894: Robert Michael Hillary acquired property from the mortgage holders. Married Edith Mussen 1895 and lived in house with their 9 children.&#91;1&#93; Nora Hillary, daughter of Robert Michael, would live in the home until 1993. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Aurora Historical Society. \"Chronology of Residents\". Retrieved March 4, 2013."}, {"index": "2", "level": 1, "title": "Architecture", "content": ""}, {"index": "3", "level": 1, "title": "Museum of Medicine", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "Notes", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hillary_House_and_Koffler_Museum_of_Medicine", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69693, 'Tightwad_Hill', 'en', 'Tightwad Hill is the popular name for Charter Hill, the hill rising to the east of California Memorial Stadium at the University of California, Berkeley in Berkeley, California, U.S.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Tightwad Hill is so named as it affords a free view of the stadium''s field, allowing fans of the Golden Bears to see the game for free.&#91;1&#93;&#91;2&#93; The hill usually has its occupants, even when the stadium sports empty seats. Tightwad Hill is part of Charter Hill, the area behind campus that also encompasses the Big \"C\", a large concrete letter \"C\" in the hillside. Tightwad Hill rises steeply about 100 feet above the east rim of the stadium, to a relatively flat area where spectators perch. Created when Memorial Stadium was built in 1923, Tightwad Hill was created from the dirt removed during the excavation of lower Strawberry Canyon. The first time fans were seen on the hill for Cal games was on November 24, 1923, during the inaugural game at California Memorial Stadium, which Cal won by a final score of 9–0, beating Stanford for the fifth straight year and securing their fourth straight undefeated season. Due to the stadium being sold out for the game, fans and students made their way up to the hill that had been created above the east rim of the stadium. Since then, U.C. Berkeley students, staff, faculty, and the public have enjoyed fall days on the hill, cheering for the Golden Bears and enjoying the view of the U.C. campus, downtown Berkeley, and the central San Francisco Bay. There are and have been many unique features on the hill over the years. Some of those items and areas include or included: A bench that was built in a tree over 20 years ago. Another tree fell into it during the winter of 2013/2014 and, along with other trees affected by old age and storms, the bench was cut down the week prior to the 2014 home opener. Parts of the bench, though, have been saved for future use somewhere in the main seating area of the Hill. Trash cans and recycling bins to help keep the hill looking spotless following games&#91;citation needed&#93; Terraces formed into the steep hillside to facilitate seating \"The Tightwad 50 Club\", which is the seating area below where the Tightwad Hill sign once hung from \"The Pit\", which is an area filled with broken glass below the lowest seating area on the main part of the Hill A bench that was once below The 50 Club, which was in place from 2004 to 2008. It was followed by an improved version that was used for one season in 2014 before it was destroyed by drunk frat boys during the following offseason In 2006, the Regents of the University of California began considering a major renovation of Memorial Stadium. One plan proposed the construction of a new seating structure, the so-called \"Eastside Seating Structure\" on the promenade on the east side of the stadium. If this were to be built, it could block views of the field from Tightwad Hill, possibly eliminating this unusual and colorful tradition. An organization called \"Save Tightwad Hill\" sued the university, claiming that the Environmental Impact Report for the stadium project did not adequately analyze the impacts of the planned improvements on historic resources and scenic views. The group eventually settled with the university. Under the terms of the agreement the university agreed in concept to preserve Tightwad Hill as an important Cal football tradition, and to include representatives of Tightwad Hill in the design process for east side improvements. Tightwad Hill became the sponsor of The Bear Raid podcast on November 15, 2020, the same date as the debut of the show. The long-term goal of the podcast, currently hosted by three members of The Hill (two of which are current and former \"Governors of Tightwad\") is to cover all of the Cal athletic programs. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1"}, {"index": "2", "level": 1, "title": "California Victory Cannon", "content": "California Victory Cannon[edit] The Victory Cannon at an October 2008 game against UCLA. To the right of the fans on the hill is the platform for the California Victory Cannon. Constructed in 2004 to serve as a replacement for the old wooden cannon platform, the concrete and stone structure was paid for through a 2003 donation campaign spearheaded by current and former UC Cannoneers, the keepers and operators of the cannon. This permanent structure debuted during the 2004 season as the new perch for the Victory Cannon. At every home game, rain or shine, the cannon is loaded and shot at each of the football team''s run-outs, whenever Cal scores a touchdown, and when a Cal victory goes final. The resulting boom is heard throughout the stadium and the surrounding area, and has come to be known as \"Oski''s Mighty Thunder.\" Starting at the Big Game of 1963, the California Victory Cannon was traditionally brought by members of the UC Rally Committee to be fired inside the stadium. When the old Pac-8 Conference banned cannons from stadiums in 1972, all other Pac-8 schools abandoned their cannons; Cal, however, maintained the tradition as the hill behind the stadium was ruled to be outside the zone governed by the ban. Since 1972, the Victory Cannon has been fired from outside of Memorial Stadium to the delight of fans on and off Tightwad Hill.&#91;1&#93; The cannon has only once run out of ammunition, in a 1991 home game against Pacific where Cal scored 12 touchdowns. In addition to being fired at all Cal home games, the cannon has traveled to bowl games, such as the Holiday and Copper Bowls, as well as to away games against Washington and Indiana, even having a stand-in from the Australian town of Wagga Wagga brought to Cal''s victory over the Hawaii Rainbow Warriors at the College Football Sydney Cup, the opening game of the 2016 season, in Australia''s national stadium ANZ Stadium. ^ Cal fans get free ride on Tightwad Hill, Greg Beacham, Associated Press, October 18, 2006"}, {"index": "3", "level": 1, "title": "Notes", "content": "Notes[edit]"}, {"index": "4", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Tightwad Hill. Tightwad Hill''s official Facebook page Tightwad Hill''s official Twitter page The Bear Raid presented by Tightwad Hill - Fan produced Cal themed podcast that debut on 11/15/2020 &amp; hosted by members of Tightwad Hill Cal Alum''s Goal-line Stand for View from Tightwad Hill - by Rick DelVecchio, San Francisco Chronicle, November 3, 2006 The Vagabonds of Tightwad Hill Have the Best View in Sports - by Coby McDonald, Cal Alumni Association, October 19, 2017 A refuge of normalcy amid a pandemic? Try Tightwad Hill during the Big Game - by Evan Webeck, Bay Area News Group, November 28, 2020 .mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output .hlist.inline dl,.mw-parser-output .hlist.inline ol,.mw-parser-output .hlist.inline ul,.mw-parser-output .hlist dl dl,.mw-parser-output .hlist dl ol,.mw-parser-output .hlist dl ul,.mw-parser-output .hlist ol dl,.mw-parser-output .hlist ol ol,.mw-parser-output .hlist ol ul,.mw-parser-output .hlist ul dl,.mw-parser-output .hlist ul ol,.mw-parser-output .hlist ul ul{display:inline}.mw-parser-output .hlist .mw-empty-li{display:none}.mw-parser-output .hlist dt::after{content:\": \"}.mw-parser-output .hlist dd::after,.mw-parser-output .hlist li::after{content:\"\\a0 · \";font-weight:bold}.mw-parser-output .hlist dd:last-child::after,.mw-parser-output .hlist dt:last-child::after,.mw-parser-output .hlist li:last-child::after{content:none}.mw-parser-output .hlist dd dd:first-child::before,.mw-parser-output .hlist dd dt:first-child::before,.mw-parser-output .hlist dd li:first-child::before,.mw-parser-output .hlist dt dd:first-child::before,.mw-parser-output .hlist dt dt:first-child::before,.mw-parser-output .hlist dt li:first-child::before,.mw-parser-output .hlist li dd:first-child::before,.mw-parser-output .hlist li dt:first-child::before,.mw-parser-output .hlist li li:first-child::before{content:\" (\";font-weight:normal}.mw-parser-output .hlist dd dd:last-child::after,.mw-parser-output .hlist dd dt:last-child::after,.mw-parser-output .hlist dd li:last-child::after,.mw-parser-output .hlist dt dd:last-child::after,.mw-parser-output .hlist dt dt:last-child::after,.mw-parser-output .hlist dt li:last-child::after,.mw-parser-output .hlist li dd:last-child::after,.mw-parser-output .hlist li dt:last-child::after,.mw-parser-output .hlist li li:last-child::after{content:\")\";font-weight:normal}.mw-parser-output .hlist ol{counter-reset:listitem}.mw-parser-output .hlist ol>li{counter-increment:listitem}.mw-parser-output .hlist ol>li::before{content:\" \"counter(listitem)\"\\a0 \"}.mw-parser-output .hlist dd ol>li:first-child::before,.mw-parser-output .hlist dt ol>li:first-child::before,.mw-parser-output .hlist li ol>li:first-child::before{content:\" (\"counter(listitem)\"\\a0 \"}.mw-parser-output .navbox{box-sizing:border-box;border:1px solid #a2a9b1;width:100%;clear:both;font-size:88%;text-align:center;padding:1px;margin:1em auto 0}.mw-parser-output .navbox .navbox{margin-top:0}.mw-parser-output .navbox+.navbox,.mw-parser-output .navbox+.navbox-styles+.navbox{margin-top:-1px}.mw-parser-output .navbox-inner,.mw-parser-output .navbox-subgroup{width:100%}.mw-parser-output .navbox-group,.mw-parser-output .navbox-title,.mw-parser-output"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Tightwad_Hill", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69694, 'Pico_Diego_de_Ocampo', 'en', 'Pico Diego de Ocampo is the highest point in the Cordillera Septentrional in Santiago Province, Dominican Republic.', '[{"index": "1", "level": 1, "title": "Etymology", "content": "Etymology[edit] This peak was named after Diego de Ocampo, a 16th-century rebel slave leader who hid away in the mountains, pillaged and sabotaged plantations in Concepción de la Vega, San Juan de la Maguana, Azua de Compostela and Bahoruco. He made a truce with the Spanish authorities, but rebelled again soon after. Later on he was captured and executed by Spanish troops, according to Governor Cerrato and the Oidor Grajeada in 1546."}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Pico_Diego_de_Ocampo", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69695, 'Lion_Country_Safari', 'en', 'Lion Country Safari is a drive-through safari park and walk-through amusement park located on over 600 acres in Loxahatchee, in Palm Beach County, Florida. Founded in 1967, it claims to be the first ''cageless zoo'' in the United States.', '[{"index": "1", "level": 1, "title": "Background", "content": "Background[edit] Developed by a group of entrepreneurs, Lion Country Safari became a place where families could experience an African safari. Due to its year round climate, South Florida proved to be an ideal location for the park.&#91;1&#93; In the beginning, the park had its own 2&#160;ft (610&#160;mm) narrow gauge railroad, the Everglade Express. The architects of Lion Country Safari based the design of the property on Jack Murphy Stadium. This attraction was eventually closed and the Crown Metal Products 4-4-0 locomotive was put on static display. Later, the locomotive was donated to the Gold Coast Railroad Museum in Miami before finally being bought and fully restored by the Veterans Memorial Railroad, located in Bristol, Florida''s Veterans Memorial Park. It runs on that railroad to this day.&#91;2&#93;&#91;3&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Lion Country Safari History | Lion Country Safari\". Retrieved May 22, 2020. ^ \"Steam Locomotive Information\". www.steamlocomotive.info. Retrieved August 22, 2021. ^ \"Surviving Steam Locomotives in Florida\". Archived from the original on February 14, 2017. Retrieved August 22, 2021."}, {"index": "2", "level": 1, "title": "Exhibits", "content": ""}, {"index": "3", "level": 2, "title": "Animal species", "content": ""}, {"index": "4", "level": 1, "title": "In popular culture", "content": ""}, {"index": "5", "level": 1, "title": "Notes", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Lion_Country_Safari", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69696, 'Tree_That_Owns_Itself', 'en', 'The Tree That Owns Itself is a white oak tree that, according to legend, has legal ownership of itself and of all land within eight feet (2.4 m) of its base. Also known as the Jackson Oak, the tree is at the corner of South Finley and Dearing Streets in Athens, Georgia, US. The original tree, thought to have started life between the mid-16th and late 18th century, fell in 1942, but a new tree was grown from one of its acorns and planted in the same location. The current tree is sometimes referred to as the Son of the Tree That Owns Itself. Both trees have appeared in numerous national publications, and the site is a local landmark.', '[{"index": "1", "level": 1, "title": "Legend", "content": ""}, {"index": "2", "level": 1, "title": "History", "content": "History[edit] Plaque at the site, weathered by exposure. The stone faintly details a passage from William H. Jackson''s deed to the tree. The original Tree That Owns Itself is estimated to have started life at some time between the mid-16th and late 18th centuries.&#91;1&#93;&#91;2&#93; The tree was considered by some to be both the biggest tree in Athens and the most famous tree in the United States.&#91;3&#93;&#91;4&#93; The tree predated the transformation of the area into a residential neighborhood beginning in the mid-19th century. The residence adjacent to the tree, known as Dominie House, was built at the corner of Milledge Avenue and Waddell Street in 1883, and was moved to its present location about twenty years later.&#91;4&#93; By 1906, erosion had become apparent at the base of the tree. George Foster Peabody paid to have new soil, a commemorative tablet, and a chain barricade supported by eight granite posts installed around the tree. Despite these efforts, the tree reportedly suffered heavy damage during an ice storm in 1907. Although attempts were made at preservation, rot had already set in, and the tree was permanently weakened.&#91;citation needed&#93; The original oak fell on the evening of October 9, 1942, following a long period of decline. Its poor condition had been known for years, and within days of its collapse, a move was underway to replace the fallen tree with a \"son\" grown from one of its acorns.&#91;5&#93; One account suggests that the tree had actually died several years before its collapse, the victim of root rot.&#91;3&#93; The tree was over 100 feet (30&#160;m) tall, and was estimated to be between 150 and 400 years old when it fell.&#91;1&#93;&#91;2&#93; It has been reported elsewhere that the tree fell on December 1, 1942, succumbing not to old age and disease but rather to a violent windstorm that ravaged much of north Georgia that evening, causing widespread damage and killing several people.&#91;6&#93; While it is possible that some portion of the tree had remained standing for several weeks, meeting a dramatic end at the hands of a killer storm, only the earlier date is supported by newspaper accounts. It is not known why the tree was not dated by counting its rings, unless the tree’s core was rotten out, fairly likely given its age and the way its death has often been described, thereby destroying many if not all of its rings before it ever fell.&#91;citation needed&#93; ^ a b .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Dorsey, Derrick. \"Mighty oak enjoys golden years\". Excursia. Archived from the original on April 1, 2004. Retrieved April 7, 2007. ^ a b \"The Tree That Owns Itself\". Lets Go. Archived from the original on May 9, 2007. Retrieved April 7, 2007. ^ a b \"Stripling of an oak bravely sets out as heir to ''tree that owns itself''\". Athens Banner-Herald. December 5, 1946. pp.&#160;1, 5. ^ a b Thomas, Frances Taliaferro (1999). Historic Dearing Street. "}, {"index": "3", "level": 1, "title": "Son of The Tree That Owns Itself", "content": ""}, {"index": "4", "level": 1, "title": "Tablets", "content": ""}, {"index": "5", "level": 1, "title": "Similar trees", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "Notes", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "Further reading", "content": ""}, {"index": "10", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Tree_That_Owns_Itself", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69698, 'Cumberland_House_Provincial_Park', 'en', 'Cumberland House Provincial Park is a located on Cumberland Island at Cumberland House in the Canadian province of Saskatchewan. The site is the location of the first inland Hudson''s Bay Company post in Saskatchewan and the oldest village in the province. A powder magazine shed built in 1886 and artifacts from the HBC Northcote steamship are the remaining historic elements on the site.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Established in 1774, Cumberland House was an important stop for the transport of goods and passengers by steamship along the Saskatchewan River on routes between Grand Rapids, Manitoba on Lake Winnipeg and Edmonton and Medicine Hat to the west. It also served as a stop for smaller steamships that operated between the Pas and Prince Albert, Saskatchewan. Due to the arrival of the railway, steamship travel came to an end and the Northcote was beached at Cumberland House in 1886. It also served as an important transit point for copper ore from Flin Flon until the railway arrived in Flin Flon in 1925. Cumberland House was also an important administration and distribution centre as the Hudson''s Bay Company until 1821 when the Hudson Bay Company and the North West Company merged and Norway House became the new inland headquarters."}, {"index": "2", "level": 1, "title": "See also", "content": "See also[edit] List of protected areas of Saskatchewan List of National Historic Sites of Canada in Saskatchewan Tourism in Saskatchewan"}, {"index": "3", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser