INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69701, 'Ariel''s_Grotto', 'en', 'Ariel''s Grotto is a meet-and-greet area at several Disney parks, as well as a former restaurant in Disney California Adventure based on Disney Animation''s 1989 film The Little Mermaid.', '[{"index": "1", "level": 1, "title": "Disneyland", "content": ""}, {"index": "2", "level": 1, "title": "Magic Kingdom", "content": ""}, {"index": "3", "level": 1, "title": "Disney California Adventure", "content": ""}, {"index": "4", "level": 1, "title": "Tokyo DisneySea", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Ariel''s_Grotto", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69703, 'Fort_Fork', 'en', 'Fort Fork a North West Company (NWC) trading post on the Peace River, established in 1792. From 1 November 1792 to 9 May 1793, Alexander Mackenzie wintered there prior to his expedition to the Pacific Ocean. The fort was used until the NWC merged with the XY Company in 1805, after which it was replaced by Fort Dunvegan, further upstream.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} Cite error: A list-defined reference named \"DCBAlexanderMackenzie\" is not used in the content (see the help page). .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefault,.mw