INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69705, 'Westinghouse_Time_Capsules', 'en', 'The Westinghouse Time Capsules are two time capsules prepared by the Westinghouse Electric & Manufacturing Company. One was made in 1939 and the other in 1965. They are filled with contemporary articles used in the twentieth century way of life in the United States. The items are intended for people of the 7th millennium to receive for historical significance.', '[{"index": "1", "level": 1, "title": "Background", "content": "Background[edit] Westinghouse Electric &amp; Manufacturing Company prepared time capsules for two world''s fairs. They are both buried 50 feet below Flushing Meadows–Corona Park, the site of the fairs. Time Capsule I was created for the 1939 New York World''s Fair and Time Capsule II was created for the 1964 New York World''s Fair. The second capsule is placed ten feet north of the first capsule. The capsules are filled with physical objects of that time period of social and scientific interest. They are to be opened at the same time in the year 6939.&#91;1&#93; New York publicist George Edward Pendray was editor for Literary Digest when in 1936 he interviewed Thornwell Jacobs, organizer of Oglethorpe University''s millennia-spanning time crypt of objects preserved for the people of 8113 AD. He then published an article about this in his October magazine. Westinghouse then took this concept and started developing in 1938 their Time Capsule of Cupaloy for the 1939 New York World''s Fair.&#91;2&#93;&#91;3&#93; ^ Westinghouse 1938, p.&#160;6. ^ Jarvis 2015, p.&#160;155. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Ed Wintermantel (October 26, 1953). \"Archaeologists of Future may find aid to research in today''s Time Capsules\". The Kansas City Times. Kansas City, Missouri. p.&#160;24 &#8211; via Newspapers.com ."}, {"index": "2", "level": 1, "title": "Construction", "content": ""}, {"index": "3", "level": 1, "title": "Capsule contents", "content": ""}, {"index": "4", "level": 2, "title": "1939 Time Capsule I", "content": ""}, {"index": "5", "level": 2, "title": "1965 Time Capsule II", "content": ""}, {"index": "6", "level": 1, "title": "Book of Record", "content": ""}, {"index": "7", "level": 1, "title": "Location of the two time capsules", "content": ""}, {"index": "8", "level": 1, "title": "Messages", "content": ""}, {"index": "9", "level": 1, "title": "Inscription on the time capsules", "content": ""}, {"index": "10", "level": 1, "title": "Future languages", "content": ""}, {"index": "11", "level": 1, "title": "See also", "content": ""}, {"index": "12", "level": 1, "title": "References", "content": ""}, {"index": "13", "level": 1, "title": "Sources", "content": ""}, {"index": "14", "level": 1, "title": "Further reading", "content": ""}, {"index": "15", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Westinghouse_Time_Capsules", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69706, 'Palatki_Heritage_Site', 'en', 'The Palatki Heritage Site is an archaeological site and park located in the Coconino National Forest, near Sedona, in Arizona, United States at approximately 34°54′56″N 111°54′08″W. In the Hopi language Palatki means ''red house''.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Cliff dwellings The Palatki site has a set of ancient cliff dwellings in the red sandstone cliffs, built from 1100 to 1400 CE by the Sinagua people of the Ancestral Puebloans. The cliff dwellings were built under south-facing overhangs for shelter and winter sun. The Sinagua people planted crops and made pottery in the area.&#91;1&#93; Palatki and Honanki, another nearby archaeological site, had the largest cliff dwellings in the Red Rock formation area from 1150 to 1300&#160;CE.&#91;2&#93; Palatki consists of two separate pueblos, suggesting two family or kin groups may have lived here, one in each pueblo. The circular shield-like pictographs above the eastern pueblo have been interpreted by some archaeologists as being a kin or clan symbol.&#91;3&#93; Rock art There are pictographs and petroglyphs at the Palatki site, including some that predate the cliff dwellings. Many of the pictographs on the rock walls are from the Sinagua. However, those created by peoples of the Archaic period in North America include some of the more abstract pictograph symbols and drawings that are 3,000 to 6,000 years old, and some of the petroglyphs, estimated to be 5,000 to 6,000 years old.&#91;1&#93; Archaeology Visitation to the site for over a century has caused degradation of the archaeological elements. It was begun by 19th century Euro-American settlers, with little archaeological awareness for the area. Photographs from the early 1900s show that an estimated 70 to 90 percent of the original structures have disappeared since then. ^ a b .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Palatki Heritage Site – Indian Ruins and Pictographs, Sedona AZ\". Retrieved 27 October 2016. ^ \"Coconino National Forest – Palatki Heritage Site\". Retrieved 27 October 2016. ^ Palatki and Honanki Ruins Archived 2011-04-11 at the Wayback Machine, handout by US Forest Service. This article incorporates public domain text from this and other US government documents."}, {"index": "2", "level": 1, "title": "Access", "content": "Access[edit] The Palatki Heritage Site is open to visitors seven days a week from 9:30am to 3:00pm. The site is accessible by guided tours only, with the last tour at 2:00 PM. Reserve a tour at Recreation.gov. There are two trails in the park, one to view the Sinagua cliff dwellings, and a second to view the pictographs and petroglyphs.&#91;1&#93; The tour includes both sites, for a total distance of 1 mile. The trails are not handicapped accessible.&#91;1&#93; Purchase of a Red Rock Parking Pass is also needed for park entry.&#91;2&#93; ^ a b .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"Palatki Indian Ruins – Sedona, Arizona\". Retrieved 27 October 2016. ^ \"Coconino National Forest – Palatki Heritage Site\". Retrieved 27 October 2016."}, {"index": "3", "level": 1, "title": "Gallery", "content": "Gallery[edit] .mw-parser-output .wide-image-normbg,.mw-parser-output .thumbimage.wide-image-normbg{background:var(--background-color-neutral-subtle,#f8f9fa);color:inherit}.mw-parser-output .wide-image-nobg,.mw-parser-output .thumbimage.wide-image-nobg{background:transparent;color:inherit} Rock formations at Palatki Heritage Site Sinagua cliff dwellings Cave pictographs Cave pictograph detailing the position of the sun at summer and winter solstices relative to the rock formations"}, {"index": "4", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "5", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width: