INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69709, 'Fantasmic!', 'en', 'Fantasmic! is a nighttime show at Disneyland and Disney’s Hollywood Studios. The show formerly operated at Tokyo DisneySea. It features fireworks, characters, live actors, water effects, pyrotechnics, lasers, music, audio-animatronics, searchlights, decorated boat floats and mist screen projections. The narrative of Fantasmic! is a voyage through Mickey Mouse’s imagination that culminates in a battle against the Disney Villains.', '[{"index": "1", "level": 1, "title": "Disneyland version", "content": ""}, {"index": "2", "level": 2, "title": "Synopsis (since 2024)", "content": ""}, {"index": "3", "level": 3, "title": "Development", "content": ""}, {"index": "4", "level": 3, "title": "Refurbishments", "content": ""}, {"index": "5", "level": 2, "title": "2023 fire incident", "content": ""}, {"index": "6", "level": 1, "title": "Disney''s Hollywood Studios version", "content": ""}, {"index": "7", "level": 2, "title": "Synopsis (since 2022)", "content": ""}, {"index": "8", "level": 2, "title": "Hollywood Hills Amphitheater", "content": ""}, {"index": "9", "level": 3, "title": "Refurbishments", "content": ""}, {"index": "10", "level": 2, "title": "Alternate show: \"<i>Taste of Fantasmic!</i>\"", "content": ""}, {"index": "11", "level": 1, "title": "Tokyo DisneySea version", "content": ""}, {"index": "12", "level": 1, "title": "Future/Potential Paris version", "content": ""}, {"index": "13", "level": 1, "title": "Related shows", "content": ""}, {"index": "14", "level": 1, "title": "Soundtrack", "content": ""}, {"index": "15", "level": 1, "title": "Voice cast", "content": ""}, {"index": "16", "level": 1, "title": "See also", "content": ""}, {"index": "17", "level": 1, "title": "References", "content": ""}, {"index": "18", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Fantasmic!", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:38:36.275099+11:00', '2026-01-13 00:25:13.154341+11:00');
