INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69747, 'Marengo_Cave', 'en', 'Marengo Cave is a privately owned cave located in Marengo, Indiana. One of only four show caves in Indiana, public tours of the cave have been given since 1883. Tours commenced just days after the cave''s discovery by two school children. The cave was designated as a National Natural Landmark in 1984.', '[{"index": "1", "level": 1, "title": "Discovery", "content": ""}, {"index": "2", "level": 2, "title": "State''s story", "content": ""}, {"index": "3", "level": 2, "title": "County''s story", "content": ""}, {"index": "4", "level": 2, "title": "Story as told by cave staff", "content": ""}, {"index": "5", "level": 1, "title": "Recent news", "content": ""}, {"index": "6", "level": 1, "title": "Other show caves in Indiana", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Marengo_Cave", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:40:21.128947+11:00', '2026-01-13 00:25:13.160767+11:00');
