INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69749, 'Eternal_Flame_Falls', 'en', 'The Eternal Flame Falls is a small waterfall located in the Shale Creek Preserve, a section of Chestnut Ridge Park in Western New York. A small grotto at the waterfall''s base emits natural gas, which can be lit to produce a small flame. This flame is visible nearly year round, although it can be extinguished and must occasionally be re-lit.', '[{"index": "1", "level": 1, "title": "Recent developments", "content": ""}, {"index": "2", "level": 1, "title": "Composition and source of gas", "content": ""}, {"index": "3", "level": 1, "title": "Gallery", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Eternal_Flame_Falls", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:40:21.128947+11:00', '2026-01-13 00:25:13.160767+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69751, 'Skyline_Caverns', 'en', 'Skyline Caverns is a series of geologic caves and a tourist attraction located in Warren County, Virginia, one mile (1.6 km) south of Front Royal. The caverns were discovered by Walter S. Amos, a retired geologist and mineralogist from Winchester, Virginia, on December 17, 1937. Skyline Caverns is open year-round, offering guided tours through the caverns.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] Walter Scott Amos at Skyline Caverns surrounded by workers, 1939 Walter S. Amos was contracted by several private and government agencies to search for caves and caverns to open in conjunction with Skyline Drive. During his search, he came across a sinkhole that was located approximately where the parking lot is currently situated. Normally, sinkholes are formed by the collapsing of a cavern roof, which takes the ground above with it. When he saw there was no water in the sinkhole, which meant there had to be a drain nearby, he believed he had discovered a cavern. Knowing this, Amos began to search the edges for some opening to the possible cave system below. He found this opening on the lip of the sinkhole by noticing a small colony of camel crickets (which only live in damp, dark areas by nature) under a small ledge. Upon digging out the first \"room\" of the caverns, he came into a large system of connected rooms, most of which were navigable and cleared from all obstructions. Ninety percent of the caverns were naturally accessible and other than the entrance area, only ten percent needed to be dug out. However, the cavern floor was lined with approximately 14 inches (360&#160;mm) of mud and clay, which had to be cleared before the caverns could be opened to the public on April 13, 1939. The use of scientific analysis makes the discovery of Skyline Caverns extremely unusual.&#91;1&#93; The caverns are estimated to be approximately 50 to 60 million years old.&#91;1&#93; ^ a b .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"History\". Skyline Caverns. Retrieved December 27, 2016."}, {"index": "2", "level": 1, "title": "Anthodites", "content": "Anthodites[edit] Anthodite During the clearing of this mud, Amos and his men discovered another area in the caverns that had been blocked for many years, by a large amount of mud. Upon clearing the newly discovered area, the geologist discovered anthodites. Anthodites are an unusual form of crystal, or perfect six-sided crystalline structures made of pure calcite. These crystals are protected by Virginia State Law and are kept behind closed doors that a tour guide must open for the public to view them."}, {"index": "3", "level": 1, "title": "Commercial operation", "content": "Commercial operation[edit] Jefferson Medical College Hospital School of Nursing students wearing Skyline Caverns beanies c.1951 Today, guided tours (as opposed to self-guided tours) are given year-round, including on Christmas Day. Tours depart every 15 to 20 minutes, lasting approximately one hour and cover about .mw-parser-output .frac{white-space:nowrap}.mw-parser-output .frac .num,.mw-parser-output .frac .den{font-size:80%;line-height:0;vertical-align:super}.mw-parser-output .frac .den{vertical-align:sub}.mw-parser-output .sr-only{border:0;clip:rect(0,0,0,0);clip-path:polygon(0px 0px,0px 0px,0px 0px);height:1px;margin:-1px;overflow:hidden;padding:0;position:absolute;width:1px}1+1&#8260;8 miles (1.8&#160;km) of walking, and reaching a depth of 260 feet (79&#160;m) below ground. Tours cover about twenty percent of the caverns; the remaining eighty percent is inaccessible to tourists. Cavern formations visible on the tour include stalactites, stalagmites, columns, \"flow-stone\", anthodites, and aragonites. Skyline Caverns also features five flowing streams, three of which are visible on the tour. Additional attractions include a miniature train ride and mirror maze.&#91;1&#93;&#91;2&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weig