INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69777, 'Sulphur_Mountain_Cosmic_Ray_Station', 'en', 'Sulphur Mountain Cosmic Ray Station, a National Historic Site of Canada found atop Sulphur Mountain in Banff National Park, commemorates Canada''s participation in the International Geophysical Year, during 1957 to 1958. Canada constructed nine sites to study cosmic rays, but this site in particular was the most important due to its higher elevation. The National Research Council constructed a laboratory at the site in the winter of 1956–57. The building was not visible from the Banff townsite as a condition of its construction.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of astronomical observatories"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-ou