INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69790, 'Takakkaw_Falls', 'en', 'Takakkaw Falls is a waterfall in Yoho National Park, near Field, British Columbia, in Canada. The falls have a total height of 373 metres (1,224 ft), making them the second tallest waterfall in Canada. The main drop of the waterfall has a height of 254 metres (833 ft).', '[{"index": "1", "level": 1, "title": "Height", "content": "Height[edit] Various sources place the total vertical height of Takakkaw Falls between 302&#160;m (991&#160;ft) and 373&#160;m (1,224&#160;ft).&#91;1&#93;&#91;2&#93; The waterfall was formerly thought to be the tallest in Canada, but a survey in 1985 found that it is actually shorter than Della Falls on Vancouver Island.&#91;1&#93; The results of that survey also concluded that the main drop of the falls is 254 metres (833&#160;ft) high.&#91;1&#93; ^ a b c Cite error: The named reference eb was invoked but never defined (see the help page). ^ Cite error: The named reference wwd was invoked but never defined (see the help page)."}, {"index": "2", "level": 1, "title": "Gallery", "content": "Gallery[edit] Takakkaw Falls pictured in 1952 Takakkaw Falls from Iceline Trail The falls pictured in June 2016 Crepuscular rays through mist from Takakkaw Falls Daly Glacier and Takakkaw Falls from the Iceline Trail, July 16, 2005 A rainbow over Takakkaw Falls."}, {"index": "3", "level": 1, "title": "See also", "content": "See also[edit] List of waterfalls List of waterfalls in British Columbia List of waterfalls of Canada Yoho National Park Wapta Falls Della Falls"}, {"index": "4", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-colum