INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69863, 'West_Coast_Airlines_Flight_956', 'en', 'West Coast Airlines Flight 956 was a scheduled commercial flight in the western United States which crashed on October 1, 1966, approximately 5.5 miles (9 km) south of Wemme, Oregon, southeast of Portland. Thirteen passengers and five crew members were aboard, but none survived. In its first week of service, the aircraft was destroyed by the impact and subsequent fire.', '[{"index": "1", "level": 1, "title": "Timeline", "content": ""}, {"index": "2", "level": 1, "title": "Accident", "content": ""}, {"index": "3", "level": 1, "title": "Wreckage", "content": ""}, {"index": "4", "level": 1, "title": "Aircraft information", "content": ""}, {"index": "5", "level": 1, "title": "Crew", "content": ""}, {"index": "6", "level": 1, "title": "Findings", "content": ""}, {"index": "7", "level": 1, "title": "Memorial", "content": ""}, {"index": "8", "level": 1, "title": "See also", "content": ""}, {"index": "9", "level": 1, "title": "References", "content": ""}, {"index": "10", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/West_Coast_Airlines_Flight_956", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:44:59.553925+11:00', '2026-01-13 00:25:13.167116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69867, 'Texas_Star', 'en', 'Texas Star is a Ferris wheel at Fair Park in Dallas, Texas, where it operates during the annual State Fair of Texas as its most popular ride.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Texas Star. .mw-parser-outpu