INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69874, 'Helvetia_Village_Historic_District', 'en', 'Helvetia Village Historic District is a national historic district located at Helvetia, Randolph County, West Virginia. It encompasses 26 contributing buildings in the village center. Some of the buildings date to the original settlement period in 1869–1870, when they were built of log construction. Later 19th-century and early-20th century buildings are of frame construction, with a number in the Carpenter Gothic style. Notable buildings include The Church (1882), Huber Inn, Post Office and Store / house (1920s), the log Swiss Museum, Star Band Hall, Cheese Haus, an original cabin (1870), Helvetia Community Hall (1939), and Rudolph''s Carpenter Shop.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.m