INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69878, 'Methuselah', 'en', 'Methuselah was a biblical patriarch and a figure in Judaism, Christianity, and Islam. He is claimed to have lived the longest life, dying at 969 years of age. According to the Book of Genesis, Methuselah was the son of Enoch, the father of Lamech, and the grandfather of Noah. Elsewhere in the Bible, Methuselah is mentioned in genealogies in 1 Chronicles and the Gospel of Luke.', '[{"index": "1", "level": 1, "title": "In the Bible", "content": ""}, {"index": "2", "level": 1, "title": "In other religious texts", "content": ""}, {"index": "3", "level": 2, "title": "Judaism", "content": ""}, {"index": "4", "level": 2, "title": "Islam", "content": ""}, {"index": "5", "level": 2, "title": "Mormonism", "content": ""}, {"index": "6", "level": 1, "title": "Interpretations", "content": ""}, {"index": "7", "level": 2, "title": "Literal", "content": ""}, {"index": "8", "level": 2, "title": "Mistranslation", "content": ""}, {"index": "9", "level": 2, "title": "Myth", "content": ""}, {"index": "10", "level": 2, "title": "Symbolic", "content": ""}, {"index": "11", "level": 1, "title": "Cultural influence", "content": ""}, {"index": "12", "level": 2, "title": "Biblical character", "content": ""}, {"index": "13", "level": 2, "title": "Plants and animals", "content": ""}, {"index": "14", "level": 2, "title": "Science", "content": ""}, {"index": "15", "level": 2, "title": "Fictional characters", "content": ""}, {"index": "16", "level": 1, "title": "Gallery", "content": ""}, {"index": "17", "level": 1, "title": "Family tree", "content": ""}, {"index": "18", "level": 1, "title": "See also", "content": ""}, {"index": "19", "level": 1, "title": "References", "content": ""}, {"index": "20", "level": 1, "title": "Bibliography", "content": ""}, {"index": "21", "level": 1, "title": "External links", "content": ""}]'::jsonb,