INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62727, '鲁迅故居', 'en', '鲁迅生前在许多地方都居住过。比如在北京，鲁迅在1919年买下了八道湾11号院的一套大院子，与弟弟周作人、周建人，和母亲鲁瑞及妻子朱安同住。1923年，因为兄弟纠纷鲁迅搬出八道弯，暂住在砖塔胡同，后来又搬到阜内宫门口的西三条（现为鲁迅纪念馆）。现在许多故居已经归为平静，为普通人所使用，有的已经被拆除，也有些地方建起鲁迅纪念馆来缅怀这位先人。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69881, 'Wilderness_Tours', 'en', 'Wilderness Tours (WT) is a commercial whitewater rafting/kayaking and outdoor training center. It was founded in 1975 when Joe E. Kowalski and five others took rafts down and navigated the section of river known as Rocher-Fendu. Wilderness Tours is based in eastern Ontario near Ottawa, the capital city of Canada, on the Ottawa River. WT operates a variety of whitewater rafting and kayaking trips.', '[{"index": "1", "level": 1, "title": "Ottawa City Rafting", "content": ""}, {"index": "2", "level": 1, "title": "Ottawa Kayak School", "content": ""}, {"index": "3", "level": 1, "title": "River Run Rafting", "content": ""}, {"index": "4", "level": 1, "title": "Music festivals", "content": ""}, {"index": "5", "level": 2, "title": "LogJam Fest", "content": ""}, {"index": "6", "level": 2, "title": "Kitchissippi Fest", "content": ""}, {"index": "7", "level": 1, "title": "World Freestyle Kayak Championships", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Wilderness_Tours", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:44:59.553925+11:00', '2026-01-13 00:25:13.167116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69886, 'Polish_Fest', 'en', 'Polish Fest is an annual ethnic festival held at the Henry Maier Festival Park in Milwaukee, Wisconsin, and was established in 1982. One of the largest Polish festivals in the United States, it attracts Polish Americans from all over Wisconsin and nearby Chicago, who come to celebrate Polish culture through music, food and entertainment.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] By 1905, Polish Milwaukeeans were the community''s second-largest ethnic group, second only to the Germans.&#91;1&#93; The community built a permanent center for social and cultural promotion, and the Polish Center of Wisconsin was opened in Franklin, Wisconsin, in August 2000.&#91;2&#93; Since 1999, Polish Fest has featured the Chopin Youth Piano Competition for non-professional pianists in two age divisions: the Junior Division for ages 14 and under and the Senior Division for ages 15 to 18.&#91;3&#93; Since no Polish Fest was held in 2020 caused by the COVID-19 pandemic, the 39th was deferred to 2021, before being cancelled a second consecutive year. In 2022, the 39th Polish Fest was held from June 10 to June 12.&#91;4&#93; ^ Gurda, John, \"A local historian''s family album,\" The Milwaukee Journal, 7 Aug. 1994, p. J3. ^ History. Polish Center of Wisconsin. ^ The Chopin Youth Piano Competition. Polish Fest. ^ Polish Fest returns to Milwaukee''s Summerfest grounds"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "3", "level": 1, "title": "External links", "content": "External links[edit] Polish Fest Polish Center of Wisconsin The Polish Women''s Cultural Club of Milwaukee"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Polish_Fest", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:44:59.553925+11:00', '2026-01-13 00:25:13.167116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69887, 'Milwaukee_Irish_Fest', 'en', 'Milwaukee Irish Fest is a yearly Irish-American festival held at Henry Maier Festival Park, on Lake Michigan, United States, every third weekend in August. Over 130,000 people attend the Fest each year to watch nearly 250 acts on 17 stages. The four-day festival started in 1981, founded by Edward J. Ward. Irish Fest is the largest of the ethnic festivals held at the Summerfest grounds which report attendance, and holds claim to the largest celebration of Irish Culture in the world.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman}"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] Official Milwaukee Irish Fest website Official Milwaukee Irish Fest Mobile website"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Milwaukee_Irish_Fest", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:44:59.553925+11:00', '2026-01-13 00:25:13.167116+11:00');
