INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69902, 'Hornet', 'en', 'Hornets are wasps of the genus Vespa in the subfamily Vespinae. They are the largest of the eusocial wasps, with some species reaching 5.5 cm (2.2 in) in length. They are similar in appearance to their close relatives the yellowjackets, but are distinguished from other vespine wasps by the relatively large top margin of the head. Worldwide, 22 species of Vespa are recognized. Most species only occur in the tropics of Asia, though the European hornet is widely distributed throughout Europe, Russia, North America, and north-eastern Asia. Wasps of the genus Dolichovespula native to North America are commonly called hornets, but are actually yellowjackets.', '[{"index": "1", "level": 1, "title": "Classification", "content": ""}, {"index": "2", "level": 1, "title": "Distribution", "content": ""}, {"index": "3", "level": 1, "title": "Stings", "content": ""}, {"index": "4", "level": 1, "title": "Attack pheromone", "content": ""}, {"index": "5", "level": 1, "title": "Life cycle", "content": ""}, {"index": "6", "level": 1, "title": "Diet and feeding", "content": ""}, {"index": "7", "level": 1, "title": "Predatory strategies", "content": ""}, {"index": "8", "level": 1, "title": "Species", "content": ""}, {"index": "9", "level": 1, "title": "As food and medicine", "content": ""}, {"index": "10", "level": 1, "title": "Gallery", "content": ""}, {"index": "11", "level": 1, "title": "References", "content": ""}, {"index": "12", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hornet", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:45:58.188265+11:00', '2026-01-13 00:25:13.167116+11:00');
