INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62730, '155_mm_gun_M1', 'en', 'The 155 mm gun M1 was a 155 millimeter caliber field gun developed and used by the United States military. Nicknamed "Long Tom", it was produced in M1 and M2  variants, later known as the M59. Developed to replace the Canon de 155mm GPF, the gun was deployed as a heavy field weapon during World War II and the Korean War, and also classed as secondary armament for seacoast defense. The gun could fire a 100 lb (45 kg) shell to a maximum range of 14 mi (23 km), with an estimated accuracy life of 1,500 rounds.', '[{"index": "1", "level": 1, "title": "Development", "content": ""}, {"index": "2", "level": 2, "title": "155 mm gun M1", "content": ""}, {"index": "3", "level": 2, "title": "Carriage M1", "content": ""}, {"index": "4", "level": 1, "title": "Specifications", "content": ""}, {"index": "5", "level": 1, "title": "Service", "content": ""}, {"index": "6", "level": 1, "title": "Variants", "content": ""}, {"index": "7", "level": 1, "title": "Ammunition", "content": ""}, {"index": "8", "level": 1, "title": "Operators", "content": ""}, {"index": "9", "level": 1, "title": "Existing examples", "content": ""}, {"index": "10", "level": 2, "title": "Pakistan", "content": ""}, {"index": "11", "level": 2, "title": "Austria", "content": ""}, {"index": "12", "level": 2, "title": "Australia", "content": ""}, {"index": "13", "level": 2, "title": "Canada", "content": ""}, {"index": "14", "level": 2, "title": "Germany", "content": ""}, {"index": "15", "level": 2, "title": "Israel", "content": ""}, {"index": "16", "level": 2, "title": "Japan", "content": ""}, {"index": "17", "level": 2, "title": "Netherlands", "content": ""}, {"index": "18", "level": 2, "title": "Slovenia", "content": ""}, {"index": "19", "level": 2, "title": "United Kingdom", "content": ""}, {"index": "20", "level": 2, "title": "United States", 