INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69905, 'Tantrum', 'en', 'A tantrum, conniption, angry outburst, temper tantrum, lash out, meltdown, fit of anger, or hissy fit is an emotional outburst, usually associated with those in emotional distress. It is typically characterized by stubbornness, crying, screaming, violence, defiance, angry ranting, a resistance to attempts at pacification, and in some cases, hitting or bullying and other physically violent behavior. Physical control may be lost; the person may be unable to remain still; and even if the "goal" of the person is met, they may not be calmed. Throwing a temper tantrum may lead to a child getting detention or being suspended from school for older school age children, and could result in a timeout or grounding, complete with room or corner time, at home. A tantrum may be expressed in a tirade: a protracted, angry speech.', '[{"index": "1", "level": 1, "title": "In early childhood", "content": ""}, {"index": "2", "level": 1, "title": "Intellectual and developmental disorders", "content": ""}, {"index": "3", "level": 1, "title": "Aberrations", "content": ""}, {"index": "4", "level": 1, "title": "In later life", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Tantrum", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:46:18.166289+11:00', '2026-01-13 00:25:13.167116+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69910, 'Tallheo_Hot_Springs', 'en', 'Tallheo Hot Springs is a hot spring located on the west shore of South Bentinck Arm, an inlet on the Central Coast of British Columbia, Canada, located southwest of the community of Bella Coola. The hot springs, which are known as  Ix7piixm in the Nuxalk language, are located opposite Bensins Island, the only island in South Bentinck Arm.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Taleomey River List of hot springs"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefa