INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69940, 'Ozone_Falls', 'en', 'Ozone Falls is a waterfall located in Cumberland County, Tennessee in the Ozone Falls State Natural Area and Cumberland Trail State Park. Ozone Falls is situated along Fall Creek, which drains a short section of the Cumberland Plateau between the Crab Orchard Mountains to the west and Walden Ridge to the east. The creek flows down from its source high in the Crab Orchard Mountains for a mile or so before steadying briefly as it enters the community of Ozone. Fall Creek enters the state natural area just after it passes under U.S. Route 70, which runs perpendicular to it. The creek spills over Ozone Falls a few hundred meters south of US-70. The trailhead is located along US-70.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] List of waterfalls"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme