INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69941, 'Thunder_Canyon', 'en', 'Thunder Canyon is a river rapids ride located at three Six Flags amusement parks and were installed when the parks were owned by Cedar Fair, Cedar Point in Sandusky, Ohio, Dorney Park & Wildwater Kingdom in Allentown, Pennsylvania and Valleyfair in Shakopee, Minnesota. All of the rides include water falls and water shoots.', '[{"index": "1", "level": 1, "title": "Information", "content": ""}, {"index": "2", "level": 2, "title": "Cedar Point", "content": ""}, {"index": "3", "level": 2, "title": "Dorney Park &amp; Wildwater Kingdom", "content": ""}, {"index": "4", "level": 2, "title": "Valleyfair", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Thunder_Canyon", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:47:25.474568+11:00', '2026-01-13 00:25:13.173081+11:00');
