INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62742, '袁滋题记摩崖石刻', 'en', '袁滋题记摩崖石刻位于盐津县豆沙镇石门村，处于由蜀入滇古道上。刻于唐贞元十年（794年）。高0.44米，宽0.36米，距地面高约1.7米。阴刻楷书8行122字。末行篆书“袁滋题”3字。记御史中丞袁滋及其他官员奉命持节册异牟寻为南诏王之事。1965年列为云南省重点文物保护单位，1988年公布为全国重点文物保护单位。现已建亭保护。
