INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62752, 'Lodhi_Art_District', 'en', 'Lodhi Art District is India’s first open-air public art district, located in Lodhi Colony, New Delhi. It features large-scale murals and street art created by artists from India and around the world. Developed as part of an initiative by the St+art India Foundation.', '[{"index": "1", "level": 1, "title": "History and Development", "content": "History and Development[edit] The Lodhi Art District&#91;1&#93; was conceptualized and brought to life between 2015 and 2016. The project aimed to revitalize the walls of Lodhi Colony''s residential and administrative buildings, which are owned by the Central Public Works Department (CPWD). The project was made possible through partnerships with governmental bodies, embassies, and corporate sponsors. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-pars