INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62760, '直波碉楼', 'en', '直波碉楼位于中国四川省阿坝藏族羌族自治州马尔康县松岗镇直波村，1991年4月16日公佈為四川省第三批文物保護單位，2001年6月25日列為第五批全國重點文物保護單位。
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62815, '开河寺石窟', 'en', '开河寺石窟，位于山西省阳泉市平定县岩会乡乱流村西魁头山，是中华人民共和国全国重点文物保护单位之一。
