INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62774, '永和網溪別墅', 'en', '永和網溪別墅，是位於臺灣新北市永和區、新店溪畔的宅第，為畫家楊三郎父親楊仲佐所建，是日治時期知名的賞菊地點，之後作楊三郎住所與畫室，原先因道路拓寬時規劃拆除，1998年獲得保留，列市定古蹟。
