INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62779, 'Дом_купца_Филиппова', 'en', 'Дом купца Филиппова — здание в Алма-Ате, построенное по заказу купца города Верного — Н. И. Филиппова.', '[{"index": "1", "level": 1, "title": "История", "content": "История[править | править код] Здание было построено в 1901 году для купца Филиппова архитектором С. К. Тропаревским. После революции здание было национализировано. В мае 1919 года в доме проходил Первый слет акынов Семиречья с участием Жамбыла Жабаева и других известных исполнителей-песенников. В память об этом событии на здании установлена мемориальная доска&#91;1&#93;. В советское время в здании располагался областной отдел по делам национальностей. После обретения независимости в здании располагался Культурно-образовательный центр посольства Турции. В настоящее время в здании расположено НИПФ РГП «Казреставрация»&#91;2&#93;. ↑ Энциклопедия Алматы. Дом купца Филиппова&#160;.&#32;Дата обращения: 22 июня 2017.&#32;Архивировано из оригинала 22 июня 2017 года. ↑ Управление культуры г. Алматы. Жилой дом (бывший дом купца Н.И.Филиппова)&#160;.&#32;Дата обращения: 30 января 2019.&#32;Архивировано 3 февраля 2019 года."}, {"index": "2", "level": 1, "title": "Архитектура", "content": "Архитектура[править | править код] Дом купца Филиппова прямоугольное в плане, двухэтажное деревянное здание, на высоком кирпичном цоколе. Вход в здание подчеркнут массивным гранитным крыльцом с двускатным навесом, на фигурных железных кронштейнах. Углы здания акцентированы профилированными, с цветовым акцентом желобков, пилястрами. В декоре фасадов использованы междуэтажные тяги, пояски, венчающих сложный карниз. Со стороны дворового фасада находится открытая веранда. Внутренние помещения здания неоднократно перестраивалась, поэтому изначальная коридорная планировочная система дома не сохранилась&#91;1&#93;. ↑ Ошибка в сносках?:&#x20;Неверный тег &lt;ref&gt;; для сносок ala не указан текст"}, {"index": "3", "level": 1, "title": "Статус памятника", "content": "Статус памятника[править | править код] 10 ноября 2010 года был утверждён новый Государственный список памятников истории и культуры местного значения города Алматы, одновременно с которым все предыдущие решения по этому поводу были признаны утратившими силу&#91;1&#93;. В этом Постановлении был сохранён статус памятника местного значения здания дома купца Филиппова. Границы охранных зон были утверждены в 2014 году&#91;2&#93;. 11 июля 2025 года был включён в Государственный список памятников истории и культуры республиканского значения&#91;3&#93;. ↑ Постановление Акимата города Алматы от 10 ноября 2010 года N 4/840 «Об утверждении Государственного списка памятников истории и культуры местного значения города Алматы»&#160;.&#32;Дата обращения: 30 января 2019.&#32;Архивировано 27 января 2019 года. ↑ Решение ХХХI сессии маслихата города Алматы V созыва от 10 сентября 2014 года N 261 «Об утверждении границ охранных зон, зон регулирования застройки и зон охраняемого природного ландшафта объектов историко-культурного наследия города Алматы»&#160;.&#32;Дата обращения: 30 января 2019.&#32;Архивировано 27 ноября 2020 года. ↑ Приказ Министра культуры и информации Республики Казахстан от 11 июля 2025 года № 318-НҚ «Об утверждении Государственного списка памятников истории и культуры республиканского значения»&#160;.&#32;Дата обращения: 1 января 2026."}, {"index": "4", "level": 1, "title": "Примечания", "content": "Примечания[править | править код] Памятники истории и культуры местного значения Алма-АтыКурганы Курганный некрополь Боролдай Курган у Западного кладбища Курган Ботанического сада Поселение Бутакты Стоянка Кимасар Сооружения XIX века Верненская крепость Церковь Казанской Богоматери Дом учёного-лесовода Э. О. Баума Верненский детский приют Дом аксакала С. А. Сейдалина Дом братьев Бреусовых Сооружения 1900-х&#160;— 1940-х годов Дом купца Радченко Дом садовода Татаринова Дом врача Л.Н. Фидлера Дом купца Филиппова Дом учёного С.Ж. Асфендиярова Бывшее здание женской гимназии Свято-Никольский собор Дом общественных собраний Верненская обсерватория Дом купца И. Габдулвалиева Дом-музей А. Байтурсынова Дом связи Здание Казахского Сельскохозяйственного института Бывшее здание Министерства хлебопродуктов Железнодорожный вокзал Алматы-2 Бывшее здание Дома культуры Здание Республиканского комитета народного контроля Здание Алматинской консерватории им. Курмангазы Здание Казгеологии Здание Министерства сельского хозяйства Здание Министерства финансов Бывшее здание Городской клинической больницы Бывшее здание гостиницы «Иссык» Здание Алматинского Государственного медицинского института Здание Казахского института иностранных языков Здание аэропорта (1936) Сооружения 1950-х&#160;— 1980-х годов Жилой дом «Дом учёных» Здание женского педагогического института Здание Хирургической клиники Зооветеринарного института Здание Союза писателей Казахстана Здание Казпотребсоюза Центральный стадион Бывшее здание филармоний им. Жамбыла Бывшее здание Казахского театра драмы им. М. Ауэзова Селезащитная плотина Здание гостиницы «Алма-Ата» Кинотеатр «Арман» Здание Русского театра драмы им. Лермонтова Здание Дворца бракосочетания Здание Казахского Государственного цирка Дом дружбы Бывший Музей-квартира писателя С. Муканова Здание Высотной гостиницы «Казахстан» Туристическая гостиница «Алатау» Дом офицеров Здание Государственного Академического театра драмы им. М. Ауэзова Бывший Дворец культуры АХБК Здание гостиницы «Отрар» Лечебно-оздоровительный комплекс «Арасан» Алматинский дворец школьников Гостиница «Достык» Телевизионная башня Центральный Государственный музей Республики Казахстан Комплекс санатория «Алатау» Алматинский ипподром Автовокзал «Сайран» Сооружения 1990-х&#160;и позднее Центральная мечеть Памятники Монумент Независимости Воинам-афганцам Памятник Канышу Сатпаеву Т. Шевченко Т. Бокину Г. Муратбаеву И. Панфилову Г. Мусрепову А. Кастееву Д. Джабаеву Мемориальный комплекс «Аллея бюстов» Надгробные памятники Могила Раимбек батыра Исключённые Здание аэропорта (1973) Дом генерал-губернатора Железнодорожный вокзал Алматы-1 Здание музыкальной школы им. А. Кашаубаева Здание уйгурского театра музыкальной комедии Храм «Всех скорбящих Радосте» Городской аэровокзал Бывшая гостиница «Жетысу» Ансамбль площади Республики Республиканский Дом политпросвещения"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%94%D0%BE%D0%BC_%D0%BA%D1%83%D0%BF%D1%86%D0%B0_%D0%A4%D0%B8%D0%BB%D0%B8%D0%BF%D0%BF%D0%BE%D0%B2%D0%B0", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:55:16.764955+11:00', '2026-01-13 00:25:12.710673+11:00');
