INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62782, 'Дом_купца_Габдулвалиева', 'en', 'Жилой дом купца Габдулвалиева — историческое здание в Алма-Ате верненского периода.', '[{"index": "1", "level": 1, "title": "История", "content": "История[править | править код] Здание было построено в 1909 году архитектором Зенковым по заказу купца Исхака Габдулвалиева. В Верном семья Габдулвалиевых владела домами и складами, расположенными на улицах Училищная, Сергиопольская, Гостинодворская, Таранчинская и других. Одним из таких зданий был Торговый дом «И. Габдулвалиев с сыновьями»&#91;1&#93;. После революции жилой дом был национализирован, а после переноса столицы Казахской ССР из Кызыл-Орды в Алма-Ату в здании разместился Народный комиссариат финансов. В настоящее время в здании расположен «Архстройпроект»&#91;2&#93;. ↑ Рассвет торговли&#160;.&#32;Дата обращения: 12 февраля 2019.&#32;Архивировано 12 февраля 2019 года. ↑ Достопримечательности г. Алматы. Дом купца И. Габдулвалиева&#160;.&#32;Дата обращения: 12 февраля 2019.&#32;Архивировано 9 мая 2016 года."}, {"index": "2", "level": 1, "title": "Архитектура", "content": "Архитектура[править | править код] Памятник зодчества начала XX века города Верного, построенный в стиле «модерна». Это прямоугольное в плане, двухэтажное здание. Главные оси выявлены расположением куполов и парапетных стен. Фасады имеют чёткое горизонтальное и вертикальное членения. Окна прямоугольной формы обведены профилированными штукатурными наличниками с полочками. Профилированный карниз, парапетные стены криволинейных очертаний и столбики парапета, увенчанные шарами, насыщены деревянным, резным растительным орнаментом&#91;1&#93;. ↑ Управление культуры г. Алматы. Жилой дом. Бывший дом купца Исхака Габдулвалиева.&#160;&#32;Дата обращения: 12 февраля 2019.&#32;Архивировано 12 февраля 2019 года."}, {"index": "3", "level": 1, "title": "Статус памятника", "content": "Статус памятника[править | править код] 10 ноября 2010 года был утверждён новый Государственный список памятников истории и культуры местного значения города Алматы, одновременно с которым все предыдущие решения по этому поводу были признаны утратившими силу&#91;1&#93;. В этом Постановлении был сохранён статус памятника местного значения жилому дому купца Габдулвалиева. Границы охранных зон были утверждены в 2014 году&#91;2&#93;. ↑ Постановление Акимата города Алматы от 10 ноября 2010 года N 4/840 «Об утверждении Государственного списка памятников истории и культуры местного значения города Алматы»&#160;.&#32;Дата обращения: 12 февраля 2019.&#32;Архивировано 27 января 2019 года. ↑ Решение ХХХI сессии маслихата города Алматы V созыва от 10 сентября 2014 года N 261 «Об утверждении границ охранных зон, зон регулирования застройки и зон охраняемого природного ландшафта объектов историко-культурного наследия города Алматы»&#160;.&#32;Дата обращения: 12 февраля 2019.&#32;Архивировано 27 ноября 2020 года."}, {"index": "4", "level": 1, "title": "Примечания", "content": "Примечания[править | править код] Памятники истории и культуры местного значения Алма-АтыКурганы Курганный некрополь Боролдай Курган у Западного кладбища Курган Ботанического сада Поселение Бутакты Стоянка Кимасар Сооружения XIX века Верненская крепость Церковь Казанской Богоматери Дом учёного-лесовода Э. О. Баума Верненский детский приют Дом аксакала С. А. Сейдалина Дом братьев Бреусовых Сооружения 1900-х&#160;— 1940-х годов Дом купца Радченко Дом садовода Татаринова Дом врача Л.Н. Фидлера Дом купца Филиппова Дом учёного С.Ж. Асфендиярова Бывшее здание женской гимназии Свято-Никольский собор Дом общественных собраний Верненская обсерватория Дом купца И. Габдулвалиева Дом-музей А. Байтурсынова Дом связи Здание Казахского Сельскохозяйственного института Бывшее здание Министерства хлебопродуктов Железнодорожный вокзал Алматы-2 Бывшее здание Дома культуры Здание Республиканского комитета народного контроля Здание Алматинской консерватории им. Курмангазы Здание Казгеологии Здание Министерства сельского хозяйства Здание Министерства финансов Бывшее здание Городской клинической больницы Бывшее здание гостиницы «Иссык» Здание Алматинского Государственного медицинского института Здание Казахского института иностранных языков Здание аэропорта (1936) Сооружения 1950-х&#160;— 1980-х годов Жилой дом «Дом учёных» Здание женского педагогического института Здание Хирургической клиники Зооветеринарного института Здание Союза писателей Казахстана Здание Казпотребсоюза Центральный стадион Бывшее здание филармоний им. Жамбыла Бывшее здание Казахского театра драмы им. М. Ауэзова Селезащитная плотина Здание гостиницы «Алма-Ата» Кинотеатр «Арман» Здание Русского театра драмы им. Лермонтова Здание Дворца бракосочетания Здание Казахского Государственного цирка Дом дружбы Бывший Музей-квартира писателя С. Муканова Здание Высотной гостиницы «Казахстан» Туристическая гостиница «Алатау» Дом офицеров Здание Государственного Академического театра драмы им. М. Ауэзова Бывший Дворец культуры АХБК Здание гостиницы «Отрар» Лечебно-оздоровительный комплекс «Арасан» Алматинский дворец школьников Гостиница «Достык» Телевизионная башня Центральный Государственный музей Республики Казахстан Комплекс санатория «Алатау» Алматинский ипподром Автовокзал «Сайран» Сооружения 1990-х&#160;и позднее Центральная мечеть Памятники Монумент Независимости Воинам-афганцам Памятник Канышу Сатпаеву Т. Шевченко Т. Бокину Г. Муратбаеву И. Панфилову Г. Мусрепову А. Кастееву Д. Джабаеву Мемориальный комплекс «Аллея бюстов» Надгробные памятники Могила Раимбек батыра Исключённые Здание аэропорта (1973) Дом генерал-губернатора Железнодорожный вокзал Алматы-1 Здание музыкальной школы им. А. Кашаубаева Здание уйгурского театра музыкальной комедии Храм «Всех скорбящих Радосте» Городской аэровокзал Бывшая гостиница «Жетысу» Ансамбль площади Республики Республиканский Дом политпросвещения"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://ru.wikipedia.org/wiki/%D0%94%D0%BE%D0%BC_%D0%BA%D1%83%D0%BF%D1%86%D0%B0_%D0%93%D0%B0%D0%B1%D0%B4%D1%83%D0%BB%D0%B2%D0%B0%D0%BB%D0%B8%D0%B5%D0%B2%D0%B0", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:55:16.764955+11:00', '2026-01-13 00:25:12.710673+11:00');
