INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62791, '利玛窦', 'en', 'Matteo Ricci was an Italian Jesuit priest and one of the founding figures of the Jesuit China missions. He created the Kunyu Wanguo Quantu, a 1602 map of the world written in Chinese characters. In 2022, the Apostolic See declared its recognition of Ricci''s heroic virtues, thereby bestowing upon him the honorific of Venerable.', '[{"index": "1", "level": 1, "title": "Early life", "content": ""}, {"index": "2", "level": 1, "title": "Ricci in China", "content": ""}, {"index": "3", "level": 1, "title": "Ricci''s approach to Chinese culture", "content": ""}, {"index": "4", "level": 1, "title": "Cause of canonization", "content": ""}, {"index": "5", "level": 1, "title": "Commemoration", "content": ""}, {"index": "6", "level": 1, "title": "Works", "content": ""}, {"index": "7", "level": 2, "title": "<i>The True Meaning of the Lord of Heaven</i>", "content": ""}, {"index": "8", "level": 2, "title": "Other works", "content": ""}, {"index": "9", "level": 1, "title": "See also", "content": ""}, {"index": "10", "level": 1, "title": "References", "content": ""}, {"index": "11", "level": 2, "title": "Citations", "content": ""}, {"index": "12", "level": 2, "title": "Sources", "content": ""}, {"index": "13", "level": 1, "title": "Further reading", "content": ""}, {"index": "14", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Matteo_Ricci", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:56:34.242526+11:00', '2026-01-13 00:25:12.710673+11:00');
