INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62792, '汤若望', 'en', 'Johann Adam Schall von Bell was a German Jesuit, astronomer and instrument-maker. He spent most of his life as a missionary in China and became an adviser to the Shunzhi Emperor of the Qing dynasty.', '[{"index": "1", "level": 1, "title": "Life", "content": ""}, {"index": "2", "level": 1, "title": "Dispute", "content": ""}, {"index": "3", "level": 1, "title": "Encounter with Prince Sohyeon", "content": ""}, {"index": "4", "level": 1, "title": "Continued cultural relevance in China", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 2, "title": "Citations", "content": ""}, {"index": "8", "level": 2, "title": "Bibliography", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Johann_Adam_Schall_von_Bell", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:56:34.242526+11:00', '2026-01-13 00:25:12.710673+11:00');
