INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62797, '盛氏花厅', 'en', '盛氏花厅又名停舻，位于中国浙江省宁波市海曙区郁家巷1号、5号。盛氏花厅初为清林廷鳌所建的藏书楼，后经转手辟为盛炳纬退休回乡后的书房。1981年12月，盛氏花厅被公布为海曙区文物保护单位。
