INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62806, '沈钧儒故居', 'en', '沈钧儒故居位于中国浙江省嘉兴市南湖区建设街道环城南路南帮岸3号，为沈钧儒于1908-1919年在嘉兴的住所，1997年8月至1998年3月落架大修，1998年6月作为纪念馆对外开放，馆名由江泽民题写。2019年10月16日，由中华人民共和国国务院公布为第八批全国重点文物保护单位。
