INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62816, 'Núi_Thủng', 'en', 'Núi Thủng là một ngọn núi nhỏ ở Cao Bằng, nằm trong Công viên địa chất Non nước Cao Bằng. Ngọn núi này có một cái hang lớn tên là Phia Lông xuyên qua thân núi, khiến cho ánh sáng Mặt trời khi chiếu vào núi từ bên kia có thể thấy được khi nhìn ở vị trí đối diện. Do đó, nó còn được gọi là núi Mắt Thần. Trong tiếng Tày, tên núi Phja Piót nghĩa là "cái núi bị thủng một lỗ, dùi xuyên qua như để gió lùa thông thống bên nọ sang bên kia".', '[{"index": "1", "level": 1, "title": "Mô tả", "content": ""}, {"index": "2", "level": 1, "title": "Lịch sử", "content": ""}, {"index": "3", "level": 1, "title": "Dân cư", "content": ""}, {"index": "4", "level": 1, "title": "Các núi thủng khác", "content": ""}, {"index": "5", "level": 1, "title": "Chú thích", "content": ""}, {"index": "6", "level": 2, "title": "Sách", "content": ""}, {"index": "7", "level": 1, "title": "Liên kết ngoài", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://vi.wikipedia.org/wiki/N%C3%BAi_Th%E1%BB%A7ng", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:57:37.344204+11:00', '2026-01-13 00:25:12.710673+11:00');
