INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62844, 'Dent_de_Crolles', 'en', 'The Dent de Crolles is a karstic mountain of the Chartreuse Mountains range, 17 kilometres north east of Grenoble, Isère, France. The mountain has a characteristic "tooth-like" profile; the French word dent means "tooth". de Crolles is derived from the town of Crolles, located next to the peak. The Dent de Crolles is easily recognizable from the Isère Valley (Grésivaudan) near Grenoble.', '[{"index": "1", "level": 1, "title": "Geography", "content": ""}, {"index": "2", "level": 1, "title": "Cave system", "content": ""}, {"index": "3", "level": 1, "title": "Gallery", "content": ""}, {"index": "4", "level": 1, "title": "Bibliography (in French)", "content": ""}, {"index": "5", "level": 1, "title": "Bibliography (in English)", "content": ""}, {"index": "6", "level": 1, "title": "References (in French)", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Dent_de_Crolles", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:59:40.985126+11:00', '2026-01-13 00:25:12.717117+11:00');
