INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62845, 'Feldberg', 'en', 'Feldberg may refer to:', '[{"index": "1", "level": 1, "title": "Places", "content": "Places[edit] Feldberg, Baden-Württemberg, a municipality and village, Germany Feldberg, a village and part of Müllheim, Baden-Württemberg, Germany Feldberg, a village and part of Feldberger Seenlandschaft, Mecklenburg-Vorpommern, Germany Feldberg, a settlement and part of Ebbs, Austria"}, {"index": "2", "level": 1, "title": "Mountains and hills", "content": "Mountains and hills[edit] Feldberg (Kaiser) (1,813 m), a mountain in the Kaiser Mountains, Tyrol, Austria Feldberg (Black Forest) (1,493 m), the highest mountain in the Black Forest of Germany Feldberg Pass Großer Feldberg (879 m), highest mountain of the Taunus, Hesse, Germany Kleiner Feldberg (826 m), second highest mountain of the Taunus, Hesse, Germany Feldberg (Hessian Rhön) (815.2 m), a mountain in Hesse, Germany Feldberg (Bavarian Rhön) (570.2 m), a hill in Bavaria, Germany Feldberg (Olpe) (556.2 m), hill in the county of Olpe, North Rhine-Westphalia, Germany"}, {"index": "3", "level": 1, "title": "Surname", "content": "Surname[edit] David Feldberg (born 1977), American professional disc golfer Girts Feldbergs (born 1993), Latvian swimmer Meyer Feldberg (born 1942), dean of Columbia Business School from 1989 to 2004 Ojārs Arvīds Feldbergs (born 1947), Latvian sculptor Wilhelm Feldberg (1900–1993), German-British-Jewish physiologist and biologist"}, {"index": "4", "level": 1, "title": "Other uses", "content": "Other uses[edit] 10666 Feldberg, an asteroid Feldberg (band), an Icelandic band Feldberg Foundation, an Anglo-German scientific exchange Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Feldberg.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Feldberg", "text": "Wikipedia"}]'::jsonb, '2026-01-13 10:59:40.985126+11:00', '2026-01-13 00:25:12.717117+11:00');
