INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62898, 'Römer', 'en', 'The Römer is a medieval building in the Altstadt of Frankfurt am Main, Germany, and one of the city''s most important landmarks. The Römer is located opposite the Old St. Nicholas Church and has been the city hall (Rathaus) of Frankfurt for over 600 years. The Römer merchant family sold it together with a second building, the Goldener Schwan, to the city council on 11 March 1405 and it was converted for use as the city hall. The Haus Römer is actually the middle building of a set of three located in the Römerberg plaza.', '[{"index": "1", "level": 1, "title": "Extensions", "content": ""}, {"index": "2", "level": 1, "title": "Architecture", "content": ""}, {"index": "3", "level": 2, "title": "Façade", "content": ""}, {"index": "4", "level": 2, "title": "Rooms", "content": ""}, {"index": "5", "level": 3, "title": "<i>Römerhalle</i> and <i>Schwanenhalle</i>", "content": ""}, {"index": "6", "level": 3, "title": "<i>Kaisersaal</i>", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 2, "title": "Sources", "content": ""}, {"index": "10", "level": 1, "title": "Further reading", "content": ""}, {"index": "11", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/R%C3%B6mer", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:00:55.241154+11:00', '2026-01-13 00:25:12.717117+11:00');
