INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62900, 'Powerscourt_Waterfall', 'en', 'Powerscourt Waterfall is the second highest waterfall in Ireland at 121 metres (397 ft) high, it is located at the base of Glensoulan on the River Dargle near Enniskerry, County Wicklow.', '[{"index": "1", "level": 1, "title": "Geography", "content": ""}, {"index": "2", "level": 1, "title": "Geology", "content": ""}, {"index": "3", "level": 1, "title": "Access", "content": ""}, {"index": "4", "level": 1, "title": "Notable events", "content": ""}, {"index": "5", "level": 1, "title": "Filming location", "content": ""}, {"index": "6", "level": 1, "title": "Gallery", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Powerscourt_Waterfall", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:00:55.241154+11:00', '2026-01-13 00:25:12.717117+11:00');
