INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62924, 'Bonifacio', 'en', 'Bonifacio may refer to:', '[{"index": "1", "level": 1, "title": "Places", "content": "Places[edit] Bonifacio, Corse-du-Sud, a town in Corsica, France Strait of Bonifacio, separating Corsica from Sardinia Bonifacio, Misamis Occidental, a municipality in the Philippines Bonifacio Global City, a central business district in Metro Manila, Philippines Fort Bonifacio, an army camp in Metro Manila, Philippines Liwasang Bonifacio, a public square in Manila, Philippines Andres Bonifacio Avenue, a major road in Quezon City, Philippines Bonifacio Drive, a major road in Manila, Philippines"}, {"index": "2", "level": 1, "title": "Other uses", "content": "Other uses[edit] Bonifacio (name), including a list of people with the name Bonifacio Transport Corporation, an intercity bus company in the Philippines Bonifacio: Ang Unang Pangulo, a 2014 Philippine historical drama film"}, {"index": "3", "level": 1, "title": "See also", "content": "See also[edit] San Bonifacio, Verona, Italy, a commune São Bonifácio, Santa Catarina, Brazil, a municipality Boniface (name) Saint Boniface (disambiguation) Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Bonifacio.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Bonifacio", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:03:02.410210+11:00', '2026-01-13 00:25:12.723024+11:00');
