INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62939, 'Hundertwasserhaus', 'en', 'The Hundertwasserhaus is an apartment house in Vienna, Austria, completed in 1985, after the idea and concept of Austrian artist Friedensreich Hundertwasser.', '[{"index": "1", "level": 1, "title": "Outline", "content": ""}, {"index": "2", "level": 1, "title": "Hundertwasser and architecture", "content": ""}, {"index": "3", "level": 1, "title": "Conflict and cooperation", "content": ""}, {"index": "4", "level": 1, "title": "Court decision", "content": ""}, {"index": "5", "level": 1, "title": "Pictures", "content": ""}, {"index": "6", "level": 1, "title": "Notes", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "Bibliography", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hundertwasserhaus", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:03:35.937633+11:00', '2026-01-13 00:25:12.723024+11:00');
