INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62960, 'General_Post_Office', 'en', 'The General Post Office (GPO) was the state postal system and telecommunications carrier of the United Kingdom until 1969. Established in England in the 17th century, the GPO was a state monopoly covering the dispatch of items from a specific sender to a specific receiver ; it was overseen by a Government minister, the Postmaster General. Over time its remit was extended to Scotland and Ireland, and across parts of the British Empire.', '[{"index": "1", "level": 1, "title": "Early postal services", "content": ""}, {"index": "2", "level": 2, "title": "The Elizabethan post network", "content": ""}, {"index": "3", "level": 3, "title": "Foreign postage", "content": ""}, {"index": "4", "level": 1, "title": "The General Post", "content": ""}, {"index": "5", "level": 2, "title": "Legislation and oversight", "content": ""}, {"index": "6", "level": 2, "title": "Distribution and delivery", "content": ""}, {"index": "7", "level": 2, "title": "Packet boats and ship letters", "content": ""}, {"index": "8", "level": 2, "title": "The London Penny Post", "content": ""}, {"index": "9", "level": 2, "title": "Expansion at home and abroad", "content": ""}, {"index": "10", "level": 3, "title": "Ralph Allen and the cross-posts", "content": ""}, {"index": "11", "level": 3, "title": "Direct delivery", "content": ""}, {"index": "12", "level": 2, "title": "New modes of transport", "content": ""}, {"index": "13", "level": 3, "title": "Road", "content": ""}, {"index": "14", "level": 3, "title": "Rail", "content": ""}, {"index": "15", "level": 3, "title": "Maritime", "content": ""}, {"index": "16", "level": 2, "title": "Uniform Penny Postage", "content": ""}, {"index": "17", "level": 1, "title": "Financial services", "content": ""}, {"index": "18", "level": 2, "title": "The Money Order Office", "content": ""}, {"inde