INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62972, 'Polesden_Lacey', 'en', 'Polesden Lacey is an Edwardian house and estate, located on the North Downs at Great Bookham, near Dorking, Surrey, England. It is owned and run by the National Trust and is one of the Trust''s most popular properties.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The name ''Polesden'' is thought to be Old English. The first house was built here by 1336. Anthony Rous bought the estate in 1630 and rebuilt the medieval house.&#91;1&#93; The house was owned by the Rous family until 1723, when the estate was purchased by the economist and politician Arthur Moore. An octagonal pavilion was added to the south front at this time.&#91;2&#93; In 1747 Sir Francis Geary, 1st Baronet purchased the estate, and subsequently spent his retirement there. Richard Brinsley Sheridan, the poet and playwright, came to live there in 1797 and began work to improve the building.&#91;3&#93; However this effort was counter-productive and in 1818 Joseph Bonsor, a stationer and bookseller, bought the estate. He commissioned Thomas Cubitt to build an entirely new house in 1821–23, creating the core of the house seen today.&#91;2&#93; Bonsor died in 1835, and the house passed to his son who, in 1853, sold the estate to Sir Walter Farquhar, 3rd Baronet, who held it until his death in 1902.&#91;4&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Currie, CK (2000). \"Polesden Lacey and Ranmore Common estates, near Dorking: an archaeological and historical survey\" (PDF). Surrey Archaeological Collections. 87: 49–84. doi:10.5284/1069268. ^ a b Akeroyd, Simon; Bevan, Vicky (2015). Polesden Lacey, Surrey&#160;: a souvenir guide. Swindon, Wilts: National Trust. pp.&#160;2–3, 6–7. ISBN&#160;978-1-84359-492-5. OCLC&#160;925365106. ^ \"History of Polesden Lacey\". National Trust. Archived from the original on 4 March 2010. Retrieved 27 February 2010. ^ \"POLESDEN LACEY, Non Civil Parish - 1000300 | Historic England\". historicengland.org.uk. Retrieved 12 July 2022."}, {"index": "2", "level": 1, "title": "Early 20th-century", "content": ""}, {"index": "3", "level": 2, "title": "Royal honeymoon at Polesden Lacey in 1923", "content": ""}, {"index": "4", "level": 1, "title": "National Trust ownership (1942 – present)", "content": ""}, {"index": "5", "level": 1, "title": "Estate", "content": ""}, {"index": "6", "level": 1, "title": "In popular culture", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Polesden_Lacey", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:03:53.390708+11:00', '2026-01-13 00:25:12.723024+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62973, 'Erbeskopf', 'en', 'The Erbeskopf is a mountain in the Hunsrück range in central Germany. At a height of 816 metres (2,677 ft), it is the highest point in the state of Rhineland-Palatinate, as well as the highest point of German territory on the western bank of the Rhine. It lies within the Saar-Hunsrück Nature Park.', '[{"index": "1", "level": 1, "title": "Geography", "content": ""}, {"index": "2", "level": 2, "title": "Location", "content": ""}, {"index": "3", "level": 2, "title": "Elevation", "content": ""}, {"index": "4", "level": 1, "title": "History", "content": "History[edit] During a military exercise in 1892, sappers built a wooden observation tower on the mountain. In 1894, the Society for the Moselle, Hochwald and Hunsrück (today the Hunsrück Club) decided to construct a stone Emperor William Tower at the summit. This 24-metre-high tower was opened in 1901, 111 steps leading up to a viewing platform. In 1933 a kiosk was built at the entrance to the tower and a weather station installed at the top. In late August 1939 the tower was closed to civilians, three more storeys were added, military signals equipment was installed and it acted as the communication centre for a radio relay link from Berlin to the Atlantic coast. The weather station was upgraded. US troops occupied the Erbeskopf on 17 March 1945. They expanded its military facilities considerably and observed all military air traffic well into the territory of the Soviet Union. Three large radar towers and the Erwin Bunker with the wartime headquarters for Central Europe (AFCENT) supported NATO strategy as a multinational command post during the Cold War. The Emperor William Tower was blown up on 18 August 1961 because it obstructed the all-round military radar picture. In 1971 the 11-metre-high, wooden Erbeskopf Observation Tower or \"Erbeskopf Tower\" (Erbeskopfturm) was built outside the out-of-bounds area. The tower is of wooden design with three platforms. Although its views are now restricted by trees, in places there are good views as far as the Eifel. In the wake of the political easing of tension between NATO and the so-called Eastern Bloc states the significance of the listening equipment and electronic alarm systems on the Erbeskopf waned rapidly. Half a century after the end of the Second World War, American troops withdrew and the radar site continued in operation by the Bundeswehr.&#91;1&#93; Until August 2004 the summit plateau was a heavily fenced-off, military out-of-bounds area. Since the removal of the barbed wire, most of the summit is now open to the public again. For centuries the Erbeskopf was crowned by a grove of mighty beech trees at the summit. In former times it was also called the Heiliger Hain (\"Holy Copse\"), although it is not recorded whether it had been a heathen site or Christian shrine. After the Emperor William Tower was blown up and widescale clearing took place, there were only a few remnants to give a poor impression of the original ancient trees. ^ Cite error: The named reference MMaier was invoked but never defined (see the help page)."}, {"index": "5", "level": 1, "title": "Today", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Erbeskopf", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:05:00.105345+11:00', '2026-01-13 00:25:12.723024+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62974, 'Chamberlain_Clock', 'en', 'The Chamberlain Clock is an Edwardian, cast-iron, clock tower in the Jewellery Quarter of Birmingham, England. It was erected in 1903 to mark Joseph Chamberlain''s tour of South Africa between 26 December 1902 and 25 February 1903, after the end of the Second Boer War. The clock was unveiled during Chamberlain''s lifetime, in January 1904 by Mary Crowninshield Endicott, Joseph Chamberlain''s third wife.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Chamberlain Clock. .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle-lower-roman .references{list-style-type:lower-roman} .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefault,.mw-parser-output .geo-multi-punct,.mw-parser-output .geo-inline-hidden{display:none}.mw-parser-output .longitude,.mw-parser-output .latitude{white-space:nowrap}52°29′13″N 1°54′45″W&#xfeff; / &#xfeff;52.487009°N 1.912578°W&#xfeff; / 52.487009; -1.912578"}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Chamberlain_Clock", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:05:00.105345+11:00', '2026-01-13 00:25:12.723024+11:00');
