INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62983, 'Caldas_de_Monchique', 'en', 'Caldas de Monchique is a spa town in the Monchique Mountains in the Algarve region of Portugal. It has been famous since Roman times for its waters, which supposedly have healing properties. It was also used as a seasonal retreat for Portuguese royalty. It has recently gained more international recognition, particularly for health tourism, but also for its landscape and architecture.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] General view A resting place in the town Old house Town A dirt path Detail of an old house A view of the main part of town A park in Caldas de Monchique .mw-parser-output .geo-default,.mw-parser-output .geo-dms,.mw-parser-output .geo-dec{display:inline}.mw-parser-output .geo-nondefault,.mw-parser-output .geo-multi-punct,.mw-parser-output .geo-inline-hidden{display:none}.mw-parser-output .longitude,.mw-parser-output .latitude{white-space:nowrap}37°17′N 8°33′W&#xfeff; / &#xfeff;37.283°N 8.550°W&#xfeff; / 37.283; -8.550 .mw-parser-output .asbox{position:relative;overflow:hidden}.mw-parser-output .asbox table{background:transparent}.mw-parser-output .asbox p{margin:0}.mw-parser-output .asbox p+p{margin-top:0.25em}.mw-parser-output .asbox-body{font-style:italic}.mw-parser-output .asbox-note{font-size:smaller}.mw-parser-output .asbox .navbar{position:absolute;top:-0.75em;right:1em;display:none}.mw-parser-output :not(p):not(.asbox)+style+.asbox,.mw-parser-output :not(p):not(.asbox)+link+.asbox{margin-top:3em}This Faro location article is a stub. You can help Wikipedia by expanding it..mw-parser-output .hlist dl,.mw-parser-output .hlist ol,.mw-parser-output .hlist ul{margin:0;padding:0}.mw-parser-output .hlist dd,.mw-parser-output .hlist dt,.mw-parser-output .hlist li{margin:0;display:inline}.mw-parser-output .hlist.inline,.mw-parser-output 