INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (62990, 'Durdle_Door', 'en', 'Durdle Door is a natural limestone arch on the Jurassic Coast near Lulworth in Dorset, England. It is privately owned by the Weld family, who own the Lulworth Estate, but it is also open to the public.', '[{"index": "1", "level": 1, "title": "Geology", "content": ""}, {"index": "2", "level": 1, "title": "Etymology", "content": ""}, {"index": "3", "level": 1, "title": "In literature and popular culture", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "Further reading", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Durdle_Door", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:05:21.272568+11:00', '2026-01-13 00:25:12.723024+11:00');
