INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63003, 'Rock_of_Gibraltar', 'en', 'The Rock of Gibraltar is a monolithic limestone mountain 426 m (1,398 ft) high dominating the western entrance to the Mediterranean Sea. It is situated near the end of a narrow 9-kilometre-long (5.6 mi) promontory stretching due south into the Mediterranean Sea and is located within the British territory of Gibraltar. The rock is 27 km northeast of Tarifa, Spain, the southwestern tip of Europe on the Iberian Peninsula. The rock serves as a fortress and contains a labyrinthine network of man-made tunnels known as the Tunnels of Gibraltar. Most of the Rock''s upper area comprises a nature reserve which is home to about 300 Barbary macaques. It is a major tourist attraction.', '[{"index": "1", "level": 1, "title": "Geology", "content": ""}, {"index": "2", "level": 1, "title": "Eastern face", "content": ""}, {"index": "3", "level": 1, "title": "Fortification", "content": ""}, {"index": "4", "level": 2, "title": "Moorish castle", "content": ""}, {"index": "5", "level": 2, "title": "Galleries", "content": ""}, {"index": "6", "level": 2, "title": "Second world war onwards", "content": ""}, {"index": "7", "level": 2, "title": "Sayings", "content": ""}, {"index": "8", "level": 1, "title": "Nature reserve", "content": ""}, {"index": "9", "level": 2, "title": "Flora and fauna", "content": ""}, {"index": "10", "level": 3, "title": "Birds", "content": ""}, {"index": "11", "level": 1, "title": "See also", "content": ""}, {"index": "12", "level": 1, "title": "References", "content": ""}, {"index": "13", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Rock_of_Gibraltar", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:05:21.272568+11:00', '2026-01-13 00:25:12.723024+11:00');
