INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (67097, 'Camden_Market', 'en', 'The Camden markets are a number of adjoining large retail markets, often collectively referred to as Camden Market or Camden Lock, located in the historic former Pickfords stables, in Camden Town, London. It is situated north of the Hampstead Road Lock of the Regent''s Canal. Famed for their cosmopolitan image, products sold on the stalls include crafts, clothing, books, bric-a-brac, and fast food. It is the fourth-most popular visitor attraction in London, attracting approximately 250,000 people each week.', '[{"index": "1", "level": 1, "title": "The markets", "content": ""}, {"index": "2", "level": 2, "title": "Camden Lock Market", "content": ""}, {"index": "3", "level": 3, "title": "2017 fire", "content": ""}, {"index": "4", "level": 2, "title": "Stables Market", "content": ""}, {"index": "5", "level": 2, "title": "Hawley Wharf, previously Canal Market and Camden Lock Village", "content": ""}, {"index": "6", "level": 2, "title": "Buck Street Market", "content": ""}, {"index": "7", "level": 2, "title": "Electric Ballroom", "content": ""}, {"index": "8", "level": 2, "title": "Inverness Street Market", "content": ""}, {"index": "9", "level": 1, "title": "Ownership", "content": ""}, {"index": "10", "level": 1, "title": "CDNX radio", "content": ""}, {"index": "11", "level": 1, "title": "See also", "content": ""}, {"index": "12", "level": 1, "title": "References", "content": ""}, {"index": "13", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Camden_Market", "text": "Wikipedia"}]'::jsonb, '2026-01-13 13:13:56.847817+11:00', '2026-01-13 00:25:12.984300+11:00');
