INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63026, 'Yorkshire_Sculpture_Park', 'en', 'The Yorkshire Sculpture Park (YSP) is an art gallery, with both open-air and indoor exhibition spaces, in West Bretton, Wakefield, in West Yorkshire, England. It shows work by British and international artists, including Henry Moore and Barbara Hepworth. The sculpture park occupies the 500-acre (200-hectare) parkland of Bretton Hall.', '[{"index": "1", "level": 1, "title": "History", "content": "History[edit] The Yorkshire Sculpture Park, opened in 1977,&#91;1&#93;&#91;2&#93; was the UK''s first sculpture park based on the temporary open air exhibitions organised in London parks from the 1940s to 1970s by the Arts Council and London County Council (and later Greater London Council). The ''gallery without walls'' has a changing exhibition programme, rather than permanent display as seen in other UK sculpture parks such as Grizedale Forest. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless