INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63039, 'Barbarine', 'en', 'The Barbarine is the best-known free-standing rock formation in the German part of the Elbe Sandstone Mountains. It is a rock pinnacle, 42.7 metres (140 ft) high, and is the symbol of Saxon Switzerland. It was first climbed on 19 September 1905.', '[{"index": "1", "level": 1, "title": "Location", "content": ""}, {"index": "2", "level": 1, "title": "Development for sport climbing", "content": ""}, {"index": "3", "level": 1, "title": "The legend of the Barbarine", "content": ""}, {"index": "4", "level": 1, "title": "Gallery", "content": ""}, {"index": "5", "level": 1, "title": "See also", "content": ""}, {"index": "6", "level": 1, "title": "References", "content": ""}, {"index": "7", "level": 1, "title": "Sources", "content": ""}, {"index": "8", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Barbarine", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:07:12.291139+11:00', '2026-01-13 00:25:12.729109+11:00');
