INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63116, 'Llanuwchllyn', 'en', 'Llanuwchllyn is a village and community in Gwynedd, Wales, near the southern end of Llyn Tegid. It is one of the most sparsely populated communities in Wales.', '[{"index": "1", "level": 1, "title": "Demographics", "content": ""}, {"index": "2", "level": 2, "title": "Welsh language", "content": ""}, {"index": "3", "level": 2, "title": "Ethnicity", "content": ""}, {"index": "4", "level": 1, "title": "Governance", "content": ""}, {"index": "5", "level": 1, "title": "Notable people", "content": ""}, {"index": "6", "level": 1, "title": "Notes", "content": ""}, {"index": "7", "level": 1, "title": "References", "content": ""}, {"index": "8", "level": 1, "title": "Further reading", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Llanuwchllyn", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:09:36.353498+11:00', '2026-01-13 00:25:12.729109+11:00');
