INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63140, 'Lindenhof', 'en', 'Lindenhof, lit. ''Tilia Courtyard'', in the old town of Zurich, Switzerland, is the historical site of a Roman castle, and the later Carolingian Kaiserpfalz. It is situated on Lindenhof hill, on the left side of the Limmat river at the Schipfe.', '[{"index": "1", "level": 1, "title": "Gallery", "content": "Gallery[edit] Lindenhof''s chess board (2012)"}, {"index": "2", "level": 1, "title": "Literature", "content": "Literature[edit] Präsidialdepartement der Stadt Zürich, Statistik Stadt Zürich: Quartierspiegel Lindenhof. Zurich 2006 (PDF; 2.77 MB)"}, {"index": "3", "level": 1, "title": "See also", "content": "See also[edit] History of Zurich"}, {"index": "4", "level": 1, "title": "References", "content": "References[edit] .mw-parser-output .reflist-columns-2{column-width:30em}.mw-parser-output .reflist-columns-3{column-width:25em}body.skin-vector-2022 .mw-parser-output .reflist-columns-2{column-width:27em}body.skin-vector-2022 .mw-parser-output .reflist-columns-3{column-width:22.5em}.mw-parser-output .references[data-mw-group=upper-alpha]{list-style-type:upper-alpha}.mw-parser-output .references[data-mw-group=upper-roman]{list-style-type:upper-roman}.mw-parser-output .references[data-mw-group=lower-alpha]{list-style-type:lower-alpha}.mw-parser-output .references[data-mw-group=lower-greek]{list-style-type:lower-greek}.mw-parser-output .references[data-mw-group=lower-roman]{list-style-type:lower-roman}.mw-parser-output div.reflist-liststyle-upper-alpha .references{list-style-type:upper-alpha}.mw-parser-output div.reflist-liststyle-upper-roman .references{list-style-type:upper-roman}.mw-parser-output div.reflist-liststyle-lower-alpha .references{list-style-type:lower-alpha}.mw-parser-output div.reflist-liststyle-lower-greek .references{list-style-type:lower-greek}.mw-parser-output div.reflist-liststyle