INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63150, 'Fonts_Ufanes', 'en', 'Fonts Ufanes is an intermittent spring located near the Sant Miquel hermitage, in Campanet municipality of the north of Mallorca. The underground water flows from the mountains to Sant Miquel stream, which l''Albufera is the base level.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Serra de Tramuntana"}, {"index": "2", "level": 1, "title": "References", "content": "References[edit] http://www.caib.es/sites/espaisnaturalsprotegits/ca/monumento_natural_de_ses_fonts_ufanes-21483/ .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Ses Fonts Ufanes."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Fonts_Ufanes", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:09:36.353498+11:00', '2026-01-13 00:25:12.735211+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63151, 'Rondell', 'en', 'Rondell may refer to:', '[{"index": "1", "level": 1, "title": "People", "content": "People[edit] Rondell Bartholomew (born 1990), Grenadian 400 metre runner Ron''Dell Carter (born 1997), American football player Surname[edit] Cregg Rondell - vocalist in Boy Hits Car R. A. Rondell Stuntman, actor and assistant director (brother of Reid Rondell) Reid Rondell, Stuntman and actor, who died due to helicopter explosion during filming of \"Airwolf\" TV series."}, {"index": "2", "level": 2, "title": "Surname", "content": "Surname[edit] Cregg Rondell - vocalist in Boy Hits Car R. A. Rondell Stuntman, actor and assistant director (brother of Reid Rondell) Reid Rondell, Stuntman and actor, who died due to helicopter explosion during filming of \"Airwolf\" TV series."}, {"index": "3", "level": 1, "title": "Places", "content": "Places[edit] Rondell the first name for Mehringplatz, Berlin"}, {"index": "4", "level": 1, "title": "Music", "content": "Music[edit] The Rondells, redirects to Delbert McClinton The Rondelles, are an indiepop band originally from Albuquerque, New Mexico. Rondell (Pole single), a single by the musician Pole (musician)"}, {"index": "5", "level": 1, "title": "See also", "content": "See also[edit] Rundell fictional friend of the fictional character Charles Gunn who appears in Belonging (Angel episode) Rondel (disambiguation) Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Rondell.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Rondell", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:09:36.353498+11:00', '2026-01-13 00:25:12.735211+11:00');
