INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63226, 'Guildhall', 'en', 'A guildhall, also known as a guild hall or guild house, is a historical building originally used for tax collecting by municipalities or merchants in Europe, with many surviving today in Great Britain and the Low Countries. These buildings commonly become town halls and in some cases museums while retaining their original names.', '[{"index": "1", "level": 1, "title": "As town hall in the United Kingdom", "content": ""}, {"index": "2", "level": 2, "title": "List of guildhalls in the United Kingdom", "content": ""}, {"index": "3", "level": 1, "title": "As meeting houses for guilds", "content": ""}, {"index": "4", "level": 2, "title": "In the Low Countries", "content": ""}, {"index": "5", "level": 3, "title": "In the Netherlands", "content": ""}, {"index": "6", "level": 3, "title": "In Belgium", "content": ""}, {"index": "7", "level": 1, "title": "See also", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Guildhall", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:12:21.305883+11:00', '2026-01-13 00:25:12.741359+11:00');
