INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63309, 'Obelisk', 'en', 'An obelisk is a tall, slender, tapered monument with four sides and a pyramidal or pyramidion top. Originally constructed by Ancient Egyptians and called tekhenu, the Greeks used the Greek term obeliskos to describe them, and this word passed into Latin and ultimately English. Though William Thomas used the term correctly in his Historie of Italie of 1549, by the late sixteenth century, Shakespeare failed to distinguish between pyramids and obelisks in his plays and sonnets. Ancient obelisks are monolithic and consist of a single stone; most modern obelisks are made of several stones.', '[{"index": "1", "level": 1, "title": "Ancient obelisks", "content": ""}, {"index": "2", "level": 2, "title": "Egyptian", "content": ""}, {"index": "3", "level": 3, "title": "Nubian", "content": ""}, {"index": "4", "level": 3, "title": "Ancient Egyptian obelisks in Ancient Rome", "content": ""}, {"index": "5", "level": 3, "title": "Ancient Egyptian obelisks in modern cities", "content": ""}, {"index": "6", "level": 2, "title": "Assyrian", "content": ""}, {"index": "7", "level": 2, "title": "Ancient Roman", "content": ""}, {"index": "8", "level": 2, "title": "Byzantine", "content": ""}, {"index": "9", "level": 2, "title": "Pre-Columbian", "content": ""}, {"index": "10", "level": 1, "title": "Modern obelisks", "content": ""}, {"index": "11", "level": 2, "title": "As commemorative monuments", "content": ""}, {"index": "12", "level": 2, "title": "Others usages", "content": ""}, {"index": "13", "level": 2, "title": "Transportation and erection experiments", "content": ""}, {"index": "14", "level": 1, "title": "See also", "content": ""}, {"index": "15", "level": 1, "title": "Notes", "content": ""}, {"index": "16", "level": 1, "title": "References", "content": ""}, {"index": "17", "level": 1, "title": "External links", "cont