INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63303, 'Granadilla', 'en', 'Granadilla is a flowering plant species of genus Passiflora, or the fruit of these plants. It is often confused with passion fruit, and the term often refers specifically to the fruit of Passiflora ligularis, although other species such as the Passiflora quadrangularis are included.', '[{"index": "1", "level": 1, "title": "See also", "content": "See also[edit] Granada (disambiguation) Granadillo (disambiguation) Grenadilla (Dalbergia melanoxylon), a flowering plant in the family Fabaceae La Granadella, a town in the autonomous community of Catalonia in northeast Spain Topics referred to by the same term .mw-parser-output .dmbox{display:flex;align-items:center;clear:both;margin:0.9em 1em;border-top:1px solid #ccc;border-bottom:1px solid #ccc;padding:0.25em 0.35em;font-style:italic}.mw-parser-output .dmbox>*{flex-shrink:0;margin:0 0.25em}.mw-parser-output .dmbox-body{flex-grow:1;flex-shrink:1;padding:0.1em 0}.mw-parser-output .dmbox-invalid-type{text-align:center} This disambiguation page lists articles associated with the title Granadilla.If an internal link led you here, you may wish to change the link to point directly to the intended article."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Granadilla", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:15:09.691387+11:00', '2026-01-13 00:25:12.741359+11:00');
