INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63324, 'Dudelange_Radio_Tower', 'en', 'The Dudelange Radio Tower is a 285-meter (935 ft) high freestanding steel framework FM radio and television transmission tower, also called a lattice tower, with a triangular cross section located near Dudelange in Luxembourg. When completed in 1957 the Dudelange Radio Tower was the tallest structure in Luxembourg and the fourth tallest lattice tower in the world after the Tokyo, Eiffel and KCTV towers. It remains the tallest freestanding structure in Luxembourg today and the 5th tallest structure overall in the country.', '[{"index": "1", "level": 1, "title": "Plane Crash", "content": ""}, {"index": "2", "level": 1, "title": "Stations", "content": ""}, {"index": "3", "level": 2, "title": "Radio", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "References", "content": ""}, {"index": "6", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Dudelange_Radio_Tower", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:15:09.691387+11:00', '2026-01-13 00:25:12.747617+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63481, 'Breitenauriegel', 'en', 'The Breitenauriegel is a mountain in the Bavarian Forest of Germany.', '[{"index": "1", "level": 1, "title": "References", "content": "References[edit]"}, {"index": "2", "level": 1, "title": "External links", "content": "External links[edit] .mw-parser-output .side-box{margin:4px 0;box-sizing:border-box;border:1px solid #aaa;font-size:88%;line-height:1.25em;background-color:var(--background-color-interactive-subtle,#f8f9fa);color:inherit;display:flow-root}.mw-parser-output .infobox .side-box{font-size:100%}.mw-parser-output .side-box-abovebelow,.mw-parser-output .side-box-text{padding:0.25em 0.9em}.mw-parser-output .side-box-image{padding:2px 0 2px 0.9em;text-align:center}.mw-parser-output .side-box-imageright{padding:2px 0.9em 2px 0;text-align:center}@media(min-width:500px){.mw-parser-output .side-box-flex{display:flex;align-items:center}.mw-parser-output .side-box-text{flex:1;min-width:0}}@media(min-width:640px){.mw-parser-output .side-box{width:238px}.mw-parser-output .side-box-right{clear:right;float:right;margin-left:1em}.mw-parser-output .side-box-left{margin-right:1em}}@media print{body.ns-0 .mw-parser-output .sistersitebox{display:none!important}}@media screen{html.skin-theme-clientpref-night .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .sistersitebox img[src*=\"Wiktionary-logo-en-v2.svg\"]{filter:invert(1)brightness(55%)contrast(250%)hue-rotate(180deg)}}.mw-parser-output .plainlist ol,.mw-parser-output .plainlist ul{line-height:inherit;list-style:none;margin:0;padding:0}.mw-parser-output .plainlist ol li,.mw-parser-output .plainlist ul li{margin-bottom:0} Wikimedia Commons has media related to Breitenauriegel."}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Breitenauriegel", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:20:22.850454+11:00', '2026-01-13 00:25:12.753773+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63325, 'Olbers-Planetarium', 'en', 'The Olbers-Planetarium is located in the Free Hanseatic City of Bremen, Germany, recording about 29.000 visitors a year. It was named after Heinrich Wilhelm Olbers, a doctor and astronomer from Bremen.', '[{"index": "1", "level": 1, "title": "Location and transport connection", "content": ""}, {"index": "2", "level": 1, "title": "Events and Shows", "content": ""}, {"index": "3", "level": 2, "title": "History", "content": "History[edit] The planetarium opened its doors on 23 January 1952.&#91;1&#93; Back in the day it was part of the nautical college in Bremen, now the City University of Applied Sciences and its primary cause was to train nautical students in Celestial navigation. The first projector in place was the ZKP 1, which the German Hydrographical Institute, now called the Federal Maritime and Hydrographic Agency of Germany) funded. It was originally developed for the navigational institutions of the Kriegsmarine and Luftwaffe. In 1958 the nautical college moved to Werderstraße 73 where the planetarium is still located today. In 1979 a more modern projector, the ZKP 2 was introduced. Dr. Erwin Mücke had applied for funding from the German Research Foundation. The same year they also received a solar system projector, funded by the senat for Education and Science. The old ZKP 1 was sold to the college in Nordenham where it is still in use today. Since 2015 a hybrid system is in use. The main projector was upgraded with parts from a more recent model. ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}Dieter Vornholz und Lars Nerger. \"Olbers-Planetarium Bremen - Geschichte des Planetariums\". Planetarium.hs-bremen.de (in German). Retrieved 2018-03-19."}, {"index": "4", "level": 2, "title": "Research", "content": ""}, {"index": "5", "level": 2, "title": "Cooperation with the Olbers Society", "content": ""}, {"index": "6", "level": 2, "title": "Congress", "content": ""}, {"index": "7", "level": 1, "title": "Bibliography", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Olbers-Planetarium", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:15:09.691387+11:00', '2026-01-13 00:25:12.747617+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63326, 'Hohle_Fels', 'en', 'The Hohle Fels is a cave in the Swabian Jura of Germany that has yielded a number of important archaeological finds dating from the Upper Paleolithic. Artifacts found in the cave represent some of the earliest examples of prehistoric art and musical instruments ever discovered. The cave is just outside the town of Schelklingen in the state of Baden-Württemberg, near Ulm. Because of the outstanding archeological finds and their cultural significance, in 2017 the site became part of the UNESCO World Heritage Site Caves and Ice Age Art in the Swabian Jura.', '[{"index": "1", "level": 1, "title": "Discoveries", "content": ""}, {"index": "2", "level": 1, "title": "Archaeogenetics", "content": ""}, {"index": "3", "level": 1, "title": "UNESCO World Heritage Site", "content": ""}, {"index": "4", "level": 1, "title": "See also", "content": ""}, {"index": "5", "level": 1, "title": "Notes", "content": ""}, {"index": "6", "level": 1, "title": "Further reading", "content": ""}, {"index": "7", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hohle_Fels", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:15:09.691387+11:00', '2026-01-13 00:25:12.747617+11:00');
