INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (63388, 'Hohentwiel', 'en', 'Hohentwiel is a mountain of volcanic origin in the Hegau region of Baden-Württemberg in southern Germany. It is the Hausberg of the industrial city of Singen, located west of it and ca 10 km (6.2 mi) west of Zeller See. The ruins of the medieval Hohentwiel Castle rest on top of it.', '[{"index": "1", "level": 1, "title": "Naming etymology", "content": ""}, {"index": "2", "level": 2, "title": "Code name", "content": ""}, {"index": "3", "level": 1, "title": "Biogeography", "content": ""}, {"index": "4", "level": 2, "title": "Geography", "content": ""}, {"index": "5", "level": 2, "title": "Geology", "content": ""}, {"index": "6", "level": 3, "title": "Sedmentation since the Jurassic Period", "content": ""}, {"index": "7", "level": 3, "title": "Volcanism in the Miocene Period", "content": ""}, {"index": "8", "level": 3, "title": "The Quaternary Glaciation", "content": ""}, {"index": "9", "level": 3, "title": "Stratification", "content": ""}, {"index": "10", "level": 1, "title": "Hohentwiel Castle", "content": ""}, {"index": "11", "level": 1, "title": "See also", "content": ""}, {"index": "12", "level": 1, "title": "References", "content": ""}, {"index": "13", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/Hohentwiel", "text": "Wikipedia"}]'::jsonb, '2026-01-13 11:18:35.616668+11:00', '2026-01-13 00:25:12.747617+11:00');
