INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69636, 'USS_Cairo', 'en', 'USS Cairo is the lead ship of the City-class casemate ironclads built at the beginning of the American Civil War to serve as river gunboats.', '[{"index": "1", "level": 1, "title": "Service in the American Civil War", "content": ""}, {"index": "2", "level": 1, "title": "Armament", "content": ""}, {"index": "3", "level": 1, "title": "Discovery of the wreck", "content": ""}, {"index": "4", "level": 1, "title": "Salvage and museum", "content": ""}, {"index": "5", "level": 1, "title": "Gallery", "content": ""}, {"index": "6", "level": 1, "title": "See also", "content": ""}, {"index": "7", "level": 1, "title": "Notes", "content": ""}, {"index": "8", "level": 1, "title": "References", "content": ""}, {"index": "9", "level": 1, "title": "External links", "content": ""}]'::jsonb, '[{"ref": "wikipedia", "url": "https://en.wikipedia.org/wiki/USS_Cairo", "text": "Wikipedia"}]'::jsonb, '2026-01-13 14:36:43.379545+11:00', '2026-01-13 00:25:13.154341+11:00');
INSERT INTO viewpoint_wiki (viewpoint_id, wikipedia_title, wikipedia_lang, extract_text, sections, citations, last_updated, created_at) VALUES (69659, 'Angel_Oak', 'en', 'Angel Oak is an exceptionally large Southern live oak located in Angel Oak Park on Johns Island near Charleston, South Carolina. The tree is estimated to be 400–500 years old. It stands 66.5 ft tall, measures 28 ft in circumference, and produces shade that covers 17,200 square feet. Its longest branch distance is 187 ft in length. Angel Oak was the 210th tree registered with the Live Oak Society.', '[{"index": "1", "level": 1, "title": "Background", "content": "Background[edit] Angel Oak in March 2010 The oak derives its name from the estate of Justus Angel and his wife, Martha Waight Tucker Angel.&#91;1&#93; Local folklore tells stories of ghosts of formerly enslaved people appearing as angels around the tree.&#91;2&#93;&#91;3&#93; Despite the claims that the Angel Oak is the oldest tree east of the Mississippi River, bald cypress trees throughout North and South Carolina are significantly older. One example in North Carolina is over 1,600 years old.&#91;4&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-subscription a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .cs1-ws-icon a{background-size:contain;padding:0 1em 0 0}.mw-parser-output .cs1-code{color:inherit;background:inherit;border:none;padding:inherit}.mw-parser-output .cs1-hidden-error{display:none;color:var(--color-error,#d33)}.mw-parser-output .cs1-visible-error{color:var(--color-error,#d33)}.mw-parser-output .cs1-maint{display:none;color:#085;margin-left:0.3em}.mw-parser-output .cs1-kern-left{padding-left:0.2em}.mw-parser-output .cs1-kern-right{padding-right:0.2em}.mw-parser-output .citation .mw-selflink{font-weight:inherit}@media screen{.mw-parser-output .cs1-format{font-size:95%}html.skin-theme-clientpref-night .mw-parser-output .cs1-maint{color:#18911f}}@media screen and (prefers-color-scheme:dark){html.skin-theme-clientpref-os .mw-parser-output .cs1-maint{color:#18911f}}\"African American slave owners\". americancivilwar.com. Retrieved August 30, 2015. ^ Pakenham, pp. 142–43 ^ Dent, p. 148 ^ Pederson, Neil. \"Eastern OLDLIST: A database of maximum tree ages for Eastern North America\". www.ldeo.columbia.edu."}, {"index": "2", "level": 1, "title": "History", "content": "History[edit] Ferns and other greenery grow along the tree''s massive limbs Angel Oak was damaged severely during Hurricane Hugo in 1989 but has since recovered.&#91;1&#93; The City of Charleston has owned the tree and surrounding park since 1991.&#91;2&#93; Development is beginning to encroach on the site of Angel Oak. In 2012, plans to build a 500-unit apartment complex that would be 160 yards (150&#160;m) from Angel Oak were challenged in court by a group called Save the Angel Oak and the Coastal Conservation League; their concerns included the construction''s effect on available groundwater and nutrients.&#91;3&#93; By December 2013, the Lowcountry Land Trust, celebrated &#91;4&#93; \"the preservation of 17 acres adjacent to the majestic tree.\" The 17 acres adjacent to the Angel Oak were purchased by Lowcountry Land Trust, protecting the area from development. The Angel Oak tree is featured prominently in the romance novel Where the Fireflies Dream by Emily Nelson.&#91;5&#93;&#58;&#8202;159–164&#8202; Angel Oak was the focal point of an Allstate television ad in September 2018 saluting the strength of the Carolinas following the devastation of Hurricane Florence.&#91;6&#93; ^ .mw-parser-output cite.citation{font-style:inherit;word-wrap:break-word}.mw-parser-output .citation q{quotes:\"\\\"\"\"\\\"\"\"''\"\"''\"}.mw-parser-output .citation:target{background-color:rgba(0,127,255,0.133)}.mw-parser-output .id-lock-free.id-lock-free a{background:url(\"//upload.wikimedia.org/wikipedia/commons/6/65/Lock-green.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-limited.id-lock-limited a,.mw-parser-output .id-lock-registration.id-lock-registration a{background:url(\"//upload.wikimedia.org/wikipedia/commons/d/d6/Lock-gray-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .id-lock-subscription.id-lock-subscription a{background:url(\"//upload.wikimedia.org/wikipedia/commons/a/aa/Lock-red-alt-2.svg\")right 0.1em center/9px no-repeat}.mw-parser-output .cs1-ws-icon a{background:url(\"//upload.wikimedia.org/wikipedia/commons/4/4c/Wikisource-logo.svg\")right 0.1em center/12px no-repeat}body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-free a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-limited a,body:not(.skin-timeless):not(.skin-minerva) .mw-parser-output .id-lock-registration a,body:not(.skin-timeless):not(.skin-minerva) .m